pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual that can't fit even the smallest plausible item is wasted space.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny dead gap: worst outcome
        } else if post_residual < 25 {
            score += 25.0; // narrow gap: hard to reuse
        } else if post_residual < 50 {
            score += 8.0; // moderate gap
        }
    } else {
        score -= 40.0; // perfect fit: fully packed bin
    }

    // Reward leaving room for the lookahead item if it fits after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Extra reward for near-exact two-item packing.
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 12.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Placement creates a gap the next item cannot use: penalize more.
        score += 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.6;

    // Mild attraction toward bins with tighter residuals (good fits).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.15;

    // New-bin candidate: make empty bins moderately unattractive unless
    // the item is large relative to capacity or the fit elsewhere is bad.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.5;
        if !large_item && fitting_bins_count > 1 {
            score += 30.0;
        } else if large_item {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 25.0; // hard-to-fill gap
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit
    }

    // Reward tight fits relative to bin capacity (low waste fraction).
    score -= (1.0 - (item_size as f64 / bin_capacity as f64)) * 0.0;

    // Open-bin pressure: prefer compacting into fewer bins when many are open.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Prefer bins tighter than the mean residual (compaction of fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If next item cannot fit in the gap, penalize leaving a nearly-useless gap.
    if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size as f64 - post_residual as f64) * 0.25;
    }

    // Early in the stream, be slightly more willing to open fresh bins (spread risk).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when open bins are very full or scarce.
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        score = 55.0 - avg_fill * 70.0 - progress * 10.0 + open_bins_count as f64 * 0.2;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0; // chain: next item fills this bin exactly
    }
    // Near-perfect match: next item fits with small slack
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 400.0 * (1.0 - slack / 50.0).max(0.0);
    }
    // Next item cannot use the residual: penalize proportionally to wasted capacity
    else if next_item_size > 0 && next_item_size > post_residual {
        score += 60.0 + (post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // Penalize tiny dead space (<10) that nothing can use
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Tight fits (small post_residual relative to item) are good
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 80.0 * tightness;

    // Prefer filling bins below mean residual (balancing toward fuller bins)
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Early in stream: keep flexibility; late in stream: consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 50.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: mild penalty so open bins are preferred unless lookahead says otherwise
    if bin_residual == bin_capacity {
        score += 30.0;
        // If next item matches a fresh bin remainder perfectly, opening is attractive
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 900.0;
        }
    }

    score
}

