            score += 120.0;
        }
        if fitting_bins_count > 0 {
            let min_waste = bin_residual.saturating_sub(item_size) as f64;
            if min_waste > 0.6 * cap && progress < 0.7 {
                score -= 60.0 * (1.0 - progress);
            }
        }
    } else {
        score -= 15.0;
    }

    // Early stream: discourage fragmenting
    score += progress * 20.0 * (pr / cap);

    // Small items prefer near-perfect fits
    if item_size <= 10 && post_residual > 0 {
        score += pr * 0.45;
    }

    // Very large items: prefer any existing bin that fits
    if it > 0.7 * cap && !fresh {
        score -= 60.0;
    }

    // Exact-size match to current residual
    if post_residual == item_size {
        score -= 90.0;
        if nx > it {
            score -= 70.0;
        }
    }

    // Mid-band dead-space shaping
    let dist_from_half = (pr - half).abs();
    if pr > 0.0 && pr < cap && !fresh {
        score += (1.0 - dist_from_half / half) * 18.0;
    }

    // Late-stream consolidation
    if progress > 0.75 {
        score += (pr / cap) * 35.0 * progress;
    }

    // Mid-stream near-exact chain fit
    if progress > 0.35 && progress < 0.85 && nx > 0.0 && pr >= nx && pr - nx < 12.0 {
        score -= 45.0;
    }

    // Dead-space trap detection
    if post_residual > 0 && post_residual < 15 {
        score += 35.0 * (1.0 - progress);
    }

    // Clean remainder after next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 == 0 {
            score -= 40.0;
        } else if rem2 <= 5 {
            score -= 18.0;
        }
    }

    // Residual variance-aware tightening
    if mean_residual > 0.0 {
        let tight_gain = (pr / mean_residual).powi(2).min(4.0);
        score -= 10.0 * tight_gain * (1.0 - progress) * 0.5;
    }

    // Adaptive sliver threshold scaled by observed item sizes
    let sliver_limit = if nx > 0.0 { (nx * 0.5).clamp(8.0, 25.0) } else { 15.0 };
    if post_residual > 0 && (post_residual as f64) < sliver_limit && post_residual != next_item_size {
        score += 40.0 * (1.0 - progress) * (1.0 - post_residual as f64 / sliver_limit);
    }

    // Pair-sum lookahead
    if next_item_size > 0 {
        let pair_sum = item_size.saturating_add(next_item_size);
        if bin_residual >= pair_sum {
            let pair_slack = bin_residual - pair_sum;
            if pair_slack <= 10 {
                score -= 70.0 - 4.0 * pair_slack as f64;
            }
        }
    }

    // Prefer tightest fit when many bins fit
    if fitting_bins_count > 2 {
        score += pr * 0.12;
    }

    // Late-stream new-bin restraint
    if progress > 0.85 && fresh && fitting_bins_count > 0 {
        score += 140.0 * progress;
    }

    // Fragmentation guard
    if fitting_bins_count <= 2 && !fresh && pr > 0.5 * cap {
        score += 25.0 + 0.3 * (pr - 0.5 * cap);
    }

    // GEN-9: residual-dead-space coupling
    if !fresh && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 20.0 {
            score += miss * (2.5 + 3.0 * progress);
        }
    }

    // GEN-9: reward bins whose post-residual can host plausible future fill
    if !fresh && post_residual > 0 {
        let est_item = (cap - mean_residual).max(1.0);
        let fits_est = (post_residual as f64 / est_item).floor();
        if fits_est >= 1.0 {
            let leftover = post_residual as f64 - fits_est * est_item;
            score -= 14.0 * fits_est.min(3.0) * (1.0 - leftover / est_item) * (1.0 - 0.4 * progress);
        }
    }

    // GEN-9: fresh-bin decision refined
    if fresh && fitting_bins_count > 0 {
        let waste_existing = bin_residual.saturating_sub(item_size) as f64;
        let item_frac = it / cap;
        if waste_existing > cap * (0.5 - 0.4 * item_frac) {
            score -= 45.0 + 0.35 * (waste_existing - cap * (0.5 - 0.4 * item_frac));
        }
        if progress < 0.25 && open_bins_count < 8 {
            score -= 30.0 * (1.0 - progress);
        }
    }

    // GEN-11: awkward-band gap penalty strengthened with progress coupling
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap < 8 {
            score -= (8 - gap) as f64 * 7.0 * (0.5 + progress);
        }
    }

    // GEN-11: mid-band residual trap
    if !fresh && nx > 0.0 && pr >= nx && pr < 0.3 * cap && fitting_bins_count > 1 {
        let waste = pr - nx;
        score += waste * 1.5 * progress;
    }

    // GEN-11: fresh-bin bias against small items late
    if fresh && item_size <= 30 && fitting_bins_count > 0 && progress > 0.3 {
        score += 90.0 * progress;
    }

    // GEN-13: dead-space budget accounting
    if !fresh && post_residual > 0 {
        let remaining = ((total_items - step_index) as f64).max(1.0);
        let est_item = (cap - mean_residual).max(1.0);
        let recoverable = if pr >= est_item * 0.5 { 1.0 } else { pr / (est_item * 0.5) };
        let permanence = (1.0 - recoverable).clamp(0.0, 1.0);
        let hole_price = pr * (0.15 + 0.55 * permanence) * (1.0 - 0.6 / (1.0 + remaining * 0.02));
        score += hole_price;
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let refund = (pr - next_item_size as f64).min(pr);
            score -= refund * 0.35 * (1.0 - progress);
        }
    }

    // GEN-13: two-step chain refinement
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 >= 0.2 * cap {
            score -= 22.0 * (1.0 - 0.5 * progress);
        } else if rem2 > 0 && (rem2 as f64) < 0.08 * cap {
            score += 14.0 * (1.0 - rem2 as f64 / (0.08 * cap));
        }
    }

    // GEN-13: fresh-bin gate tightened
    if fresh && fitting_bins_count >= 2 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < 0.25 * cap {
            score += 70.0 * (1.0 - 0.5 * progress);
        }
    }

    // GEN-13: triple-chain lookahead
    if !fresh && next_item_size > 0 {
        let pair_sum = item_size.saturating_add(next_item_size);
        if post_residual == pair_sum {
            score -= 110.0 * (1.0 - 0.5 * progress);
        }
        let rem3 = bin_residual.saturating_sub(pair_sum);
        if rem3 > 0 && rem3 <= 100 && rem3 >= next_item_size / 2 {
            score -= 35.0 * (1.0 - progress);
        }
    }

    // GEN-36: near-full bin squeeze bonus
    if !fresh && pr <= 6.0 {
        score -= (6.0 - pr) * 9.0 * (0.5 + progress);
    }

    // GEN-36: among several fitting bins, reward tightness relative to mean
    if fitting_bins_count >= 2 && !fresh {
        let rel = (pr / mean_residual.max(1.0)).min(2.0);
        score += rel * 6.0;
        if pr < 0.15 * cap {
            score -= 30.0 * (1.0 - pr / (0.15 * cap));
        }
    }

    // GEN-36: dead-space shaping near item boundary
    if !fresh && pr > 0.0 && pr < cap {
        if pr < it && progress < 0.9 {
            score += (1.0 - progress) * 30.0 * (pr / cap);
        }
        if nx > 0.0 && (pr - nx).abs() < 3.0 && pr != nx {
            score += 12.0 * (1.0 - progress);
        }
    }

    // GEN-36: exact next-item fit with large next item
    if !fresh && next_item_size > 0 && post_residual == next_item_size && nx > 0.4 * cap {
        score -= 40.0 * (1.0 - progress);
    }

    // GEN-36: residual-band scrap minimization
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let scrap = (pr % mean_residual) / mean_residual;
        score += scrap * 22.0 * (0.4 + 0.6 * progress);
    }

    // GEN-36: near-miss calibration in mid band
    if !fresh && nx > 0.0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if dist_from_half < 0.15 * cap {
            score += 18.0 * (1.0 - miss / nx.max(1.0));
        }
    }

    // GEN-36: fresh-bin discount when residual would strand a large block late
    if fresh && fitting_bins_count > 0 && progress > 0.5 {
        let stranded = bin_residual.saturating_sub(item_size) as f64;
        if stranded > 0.55 * cap {
            score -= 55.0 * (progress - 0.5) * 2.0;
        }
    }

    // GEN-36: tiling-error coupling
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let est = mean_residual.max(1.0);
        let k = (pr / est).round().max(1.0);
        let tiling_err = ((pr - k * est).abs()) / est;
        score += tiling_err * 16.0 * (0.5 + 0.5 * progress);
        if tiling_err < 0.1 {
            score -= 20.0 * k.min(3.0) * (1.0 - 0.5 * progress);
        }
    }

    // GEN-36: keep room for follow-up item after next placement
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && (rem2 as f64) < nx * 0.25 && rem2 < 20 {
            score += (20.0 - rem2 as f64) * 3.0 * (0.5 + progress);
        } else if rem2 >= next_item_size {
            score -= 28.0 * (1.0 - 0.4 * progress);
        }
    }

    // GEN-36: fresh-bin opening gate vs estimated next-item demand
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < nx as f64 * 0.6 {
            score += 55.0 * (1.0 - 0.3 * progress);
        }
    }

    // GEN-40: exact-future-tiling reward strengthened
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let est = mean_residual.max(1.0);
        let k = (pr / est).round().max(1.0);
        let tiling_err = ((pr - k * est).abs()) / est;
        if tiling_err < 0.02 && pr >= est {
            score -= 34.0 * k.min(4.0) * (1.0 - 0.3 * progress);
        }
    }

    // GEN-40: two-item chain exactness for small current item
    if !fresh && next_item_size > 0 && post_residual == next_item_size {
        if item_size <= 25 {
            score -= 45.0 * (1.0 - 0.4 * progress);
        }
    }

    // GEN-40: dead-space floor coupling
    if !fresh && post_residual > 0 {
        let est_item = (cap - mean_residual).max(1.0);
        let min_plausible = (est_item * 0.35).clamp(1.0, 30.0);
        if pr < min_plausible {
            let stranded_frac = 1.0 - pr / min_plausible;
            score += stranded_frac * 26.0 * (1.0 - 0.5 * progress);
        }
    }

    // GEN-40: fresh-bin opening gate tightened
    if fresh && fitting_bins_count > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        let fresh_strand = cap - it;
        if best_waste > fresh_strand * (0.9 + 0.2 * (1.0 - progress)) {
            score -= 75.0 * (1.0 - 0.4 * progress);
        } else if best_waste < fresh_strand * 0.4 {
            score += 40.0 * (0.5 + 0.5 * progress);
        }
    }

    // GEN-40: compaction pull — squared post-residual preference
    if !fresh && post_residual > 0 && fitting_bins_count > 1 {
        let pr_frac = pr / cap;
        score += pr_frac * pr_frac * 55.0 * (0.4 + 0.6 * progress);
    }

    // GEN-40: residual-chain exactness for the item after next
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        let est_item = (cap - mean_residual).max(1.0);
        let k = (rem2 as f64 / est_item).round();
        if k >= 1.0 && ((rem2 as f64 - k * est_item).abs()) < 1.5 {
            score -= 30.0 * (1.0 - 0.3 * progress);
        }
    }

    // GEN-46 mutation: waste-aware fresh-bin veto — compare the dead space the
    // current placement would strand in the best fitting bin against the fresh
    // bin's strand; open a new bin only when the existing-bin waste is clearly
    // worse, scaled by how many bins already compete.
    if fresh && fitting_bins_count > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        let fresh_waste = cap - it;
        let competition = (fitting_bins_count as f64).min(5.0);
        if best_waste > fresh_waste + 12.0 + 8.0 * competition {
            score -= 95.0 * (1.0 - 0.3 * progress);
        } else if best_waste < fresh_waste * 0.55 {
            score += 50.0 * (0.4 + 0.6 * progress);
        }
    }

    // GEN-46 mutation: dead-space elasticity — penalize post-residuals that
    // can't absorb the next item in proportion to how "sealed" the leftover
    // gap is (gap too small for any plausible item = permanent waste).
    if !fresh && next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        let est_item = (cap - mean_residual).max(1.0);
        let seal = (1.0 - gap / est_item.max(1.0)).clamp(0.0, 1.0);
        score += gap * (1.5 + 2.5 * seal) * (0.5 + 0.5 * progress);
    }

    // GEN-46 mutation: chain-fill anticipation — reward bins whose post-residual
    // can exactly host the next item AND whose subsequent remainder is either
    // zero or a clean multiple of the mean item size (fine-grained residual
    // fitting combined with lookahead anticipation).
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 == 0 {
            score -= 65.0 * (1.0 - 0.3 * progress);
        } else if mean_residual > 1.0 {
            let k = (rem2 as f64 / mean_residual).round();
            if k >= 1.0 {
                let err = (rem2 as f64 - k * mean_residual).abs();
                if err < 2.0 {
                    score -= (30.0 - err * 8.0) * (1.0 - 0.4 * progress);
                }
            }
        }
        if rem2 >= next_item_size {
            score -= 18.0;
        }
    }

    // GEN-46 mutation: large-item harbor — when the next item is large, prefer
    // bins that will retain enough space for it after this placement, and
    // penalize bins that would strand a near-large-item gap.
    if !fresh && nx > 0.45 * cap {
        if post_residual >= next_item_size {
            score -= 55.0 * (1.0 - 0.2 * progress);
        } else if post_residual > 0.3 * cap {
            score += 40.0 * (0.5 + 0.5 * progress);
        }
    }

    // GEN-46 mutation: many-fitting-bins tightness sharpening — with several
    // candidate bins, amplify the raw post-residual term so the tightest fit
    // dominates selection and dead space is minimized globally.
    if !fresh && fitting_bins_count >= 3 {
        score += pr * (0.10 + 0.05 * (fitting_bins_count.min(8) as f64 - 3.0).min(5.0) * 0.2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fresh = bin_residual == bin_capacity;
    let half = 0.5 * cap;

    // Perfect fit: strong reward, amplified early
    if post_residual == 0 {
        score -= 1100.0 + 150.0 * (1.0 - progress);
    }

    // Cubic dead-space penalty, softened late
    score += pr.powi(3) / (cap * cap * cap) * 90.0 * (1.0 - 0.5 * progress);

    // Last-chance bin
    if fitting_bins_count == 1 && !fresh {
        score -= 350.0;
    }

    // Lookahead chain logic
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 580.0;
        } else if post_residual > next_item_size {
            let chain_left = post_residual - next_item_size;
            let chain_bonus = if chain_left <= item_size { 110.0 } else if chain_left <= next_item_size { 60.0 } else { 0.0 };
            score -= 60.0 * (pr / nx.max(1.0)).ln().max(0.0) + chain_bonus;
            let slack = pr - nx;
            if slack < 8.0 {
                score -= (8.0 - slack) * 12.0;
            }
            if chain_left > item_size && chain_left >= next_item_size {
                score -= 25.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * (0.7 + 0.5 * (1.0 - progress));
            if pr < 8.0 {
                score -= 20.0;
            }
        }
        if post_residual == item_size.saturating_add(next_item_size) {
            score -= 300.0;
        } else if post_residual < item_size.saturating_add(next_item_size) && pr < 0.25 * cap {
            score += 60.0 + 0.5 * (0.25 * cap - pr);
        }
    }

    // Tightness vs mean, amplified by open bin count
    score += (pr - mean_residual) * (0.5 + 0.005 * open_bins_count.min(60) as f64);

    // Consolidation pressure
    score += (open_bins_count as f64).powi(2) * 0.004 + open_bins_count as f64 * 0.2;

    // Waste-ratio term
    let fill_fraction = it / cap;
    let hole_fraction = pr / cap;
    if hole_fraction > fill_fraction {
        score += (hole_fraction - fill_fraction) * 140.0;
    }

    // New-bin candidate logic
    if fresh {
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 280.0;
        } else if fitting_bins_count == 1 {
            let waste_if_stuffed = bin_residual.saturating_sub(item_size) as f64;
            score -= 130.0 + 0.7 * waste_if_stuffed;
        } else {
            let best_possible_waste = bin_residual.saturating_sub(item_size) as f64;
            if best_possible_waste > 0.4 * cap {
                score -= 90.0;
            }
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 80.0;
        }
        if progress > 0.8 && pr > 0.45 * cap {
            score += 100.0 * progress;
        }
        if fitting_bins_count > 1 && pr <= 4.0 {
            score += 120.0;
        }
        if fitting_bins_count > 0 {
            let min_waste = bin_residual.saturating_sub(item_size) as f64;
            if min_waste > 0.6 * cap && progress < 0.7 {
                score -= 60.0 * (1.0 - progress);
            }
        }
    } else {
        score -= 15.0;
    }

    // Early stream: discourage fragmenting
    score += progress * 20.0 * (pr / cap);

    // Small items prefer near-perfect fits
    if item_size <= 10 && post_residual > 0 {
        score += pr * 0.45;
    }

    // Very large items: prefer any existing bin that fits
    if it > 0.7 * cap && !fresh {
        score -= 60.0;
    }

    // Exact-size match to current residual
    if post_residual == item_size {
        score -= 90.0;
        if nx > it {
            score -= 70.0;
        }
    }

    // Borrowed: mid-band dead-space shaping
    let dist_from_half = (pr - half).abs();
    if pr > 0.0 && pr < cap && !fresh {
        score += (1.0 - dist_from_half / half) * 18.0;
    }

    // Late-stream consolidation
    if progress > 0.75 {
        score += (pr / cap) * 35.0 * progress;
    }

    // Mid-stream near-exact chain fit
    if progress > 0.35 && progress < 0.85 && nx > 0.0 && pr >= nx && pr - nx < 12.0 {
        score -= 45.0;
    }

    // Dead-space trap detection
    if post_residual > 0 && post_residual < 15 {
        score += 35.0 * (1.0 - progress);
    }

    // Clean remainder after next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 == 0 {
            score -= 40.0;
        } else if rem2 <= 5 {
            score -= 18.0;
        }
    }

    // Residual variance-aware tightening
    if mean_residual > 0.0 {
        let tight_gain = (pr / mean_residual).powi(2).min(4.0);
        score -= 10.0 * tight_gain * (1.0 - progress) * 0.5;
