    if item_size as f64 > 0.7 * cap && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Exact-size match to current residual gets an extra nudge
    if post_residual == item_size {
        score -= 90.0;
    }

    // Mutation: near-exact residual matching for future packing (2-item chain lookahead)
    if next_item_size > 0 && item_size > 0 {
        let nx = next_item_size as f64;
        let it = item_size as f64;
        // If this placement leaves exactly room for item + next item (perfect 2-chain)
        if pr as u32 == item_size.saturating_add(next_item_size) {
            score -= 260.0;
        }
        // Penalize residuals that are just barely too small for the next item
        // (dead space that blocks the lookahead chain)
        else if pr > 0.0 && (pr as u32) < item_size.saturating_add(next_item_size) && pr < 0.25 * cap {
            score += 70.0 + 0.6 * (0.25 * cap - pr);
