        // Reward residuals large enough to hold next item with slack for a small follower
        if pr > nx + it {
            score -= 25.0 * ((pr - nx - it) / cap).min(0.15);
        }
        // Mid-stream: residual that fits next item exactly is worth more than generic chain
        if progress > 0.35 && progress < 0.85 && pr >= nx && pr - nx < 12.0 {
            score -= 45.0;
        }
    }

    // Mutation: variance-aware dead-space shaping — penalize residuals near
    // half-capacity (hardest to fill later) more strongly
    let half = 0.5 * cap;
    let dist_from_half = (pr - half).abs();
    if pr > 0.0 && pr < cap {
        score += (1.0 - dist_from_half / half) * 18.0;
    }

    // Mutation: late-stream consolidation — prefer filling the emptiest bins
    // first when nearing the end so fewer bins stay partially used
    if progress > 0.75 {
        score += (pr / cap) * 35.0 * progress;
    }

    score
}

