pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize large dead space that small future items could still use
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dead_space_penalty = (post_residual as f64).powi(2) / (bin_capacity as f64).powi(2) * 50.0;
    score += dead_space_penalty * (1.0 - 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            score -= 50.0 * (post_residual as f64 / (next_item_size.max(1) as f64)).ln().max(0.0);
        } else {
            // next item cannot use the leftover: penalize proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Compare residual against mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Mild penalty for many open bins: encourage consolidation
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate: keep neutral-to-slightly-high unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0;
        // If few bins can fit and item is large, opening a new bin is attractive
        if fitting_bins_count <= 1 {
            score -= 150.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 60.0;
        }
    }

    // Early stream: slightly discourage fragmenting many bins early
    score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post-residual with stream progress
    let poly = x * x * (1.0 - x) + t * x * (1.0 - x * x);
    score += 18.0 * poly;

    // Penalize dead space more as stream progresses
    score += t * (pr * pr) / cap;

    // Lookahead: reward residual that fits the next item smoothly
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 / cap) * t;
    }

    // Last-chance bin bonus (avoid opening new bins unnecessarily)
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Mild penalty when bin residual deviates from mean residual
    score += 0.05 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // Slight preference for tighter bins among many open bins
    score += 0.01 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity divided into 5 classes (20-wide bands)
    let item_class = item_size / 20;           // 0..4 (small..huge)
    let next_class = next_item_size / 20;      // 0..4, or 0 if no next item (0)
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect fit bonus: post_residual in tiny residue classes is excellent
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Dead-space penalty: post_residual too small to host the smallest plausible item
    // (sizes can be as small as 1, so only exactly-zero residual is truly dead).
    if post_residual > 0 && post_residual < 4 {
        score += 25.0;
    }

    // Harmonic pairing: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chain
        } else if post_residual >= next_item_size {
            score -= 8.0;
            // modulo harmony: next item divides the post residual almost evenly
            let m = post_residual % next_item_size.max(1);
            if m <= 3 {
                score -= 10.0;
            }
        } else {
            // next item cannot fit here regardless; slight penalty for stranding
            score += 6.0;
        }
        // complementary class bonus: big + small pairs pack well
        if item_class + next_class >= 3 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless current fit is bad
    if bin_residual == bin_capacity {
        // neutral base; add cost, subtracted if existing bins have bad fits
        score += 20.0;
        if post_residual > 30 {
            score += 10.0; // opening a bin then wasting >30 is bad, but it's a fresh bin so this rarely triggers
        }
        // early in stream, opening bins is fine (build diversity)
        score -= 25.0 * (1.0 - progress);
    } else {
        // prefer bins whose residual is harmonically aligned with item (integer division threshold)
        let q = bin_residual / item_size.max(1); // how many copies of item would fit
        if q >= 2 {
            score -= 5.0 * q.min(4) as f64;
        }
        // penalize bins far from mean residual (imbalance)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
        // prefer tighter bins overall (smaller residual before placement)
        score += bin_residual as f64 * 0.05;
        // late in stream, consolidate aggressively
        score -= 15.0 * progress;
    }

    // avoid bin proliferation
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1..100).
    // We penalize gaps in the awkward zone (1..=15) quadratically.
    if post_residual > 0 && post_residual <= 15 {
        score += (18 - post_residual) as f64 * (18 - post_residual) as f64 * 1.5;
    }

    // Perfect fit: strong reward (subtract heavily).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if post_residual is just barely too small for the next item (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor tight packing
    // of existing bins by rewarding low post_residual relative to mean residual.
    let open_pressure = open_bins_count as f64 * 0.35;
    score += open_pressure;

    // Encourage filling bins below mean residual (tighter than average) when many bins open.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: make the empty bin attractive only when remaining items are large
    // or current fit would create dead space. Penalize opening new bins mildly by default.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, opening a new bin is cheaper (fewer future items to place),
        // so reduce the penalty as the stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 20.0;
        // If the next item is large, a fresh bin is more valuable.
        score -= (next_item_size as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual exactly fits next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Exact match gets an extra discount.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving residual slightly larger than next item (unusable sliver).
        if post_residual > next_item_size && post_residual < next_item_size + 10 {
            score += 25.0;
        }
        // Reward if next item fits exactly after residual shrinks to something small.
        if post_residual < next_item_size && post_residual >= 10 {
            score -= 5.0;
        }
    } else {
        // Last item: minimize waste directly.
        score += 0.0;
    }

    // Prefer bins whose residual is below mean (tighter bins) — keeps big holes available.
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so we only open new bins when fit is truly bad.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * post_residual as f64;
        // But if no other bin fits well, opening fresh is fine — handled by others' scores.
    }

    // Slight preference to fill bins earlier in the stream (consolidation).
    score += 0.02 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space: residuals too small for any plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only this bin fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
        // If next item fits exactly into post_residual, extra reward.
        if post_residual as u64 == next_item_size as u64 {
            score -= 20.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 10.0 * fill_ratio * (1.0 + open_pressure);

    // Mild preference for bins with residuals near the mean (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep options open); late, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, costly late.
        score += 40.0 * progress - 20.0 * (1.0 - progress);
        // Never open a new bin if the item fits perfectly somewhere.
        if post_residual == 0 { score += 100.0; }
    } else {
        score -= 12.0 * progress * fill_ratio;
    }

    // Exact-fit celebration.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with progress:
    // late in the stream, tight fits (small post_residual) are rewarded more aggressively.
    let pr = post_residual as f64;
    let pr_norm = pr / cap; // 0..1
    let w = 1.0 + 2.0 * progress; // grows smoothly from 1 to 3
    score += w * pr_norm * pr_norm * cap * 0.5;

    // Reward tight fits non-linearly: (1 - pr_norm)^2 grows as fit tightens
    score -= 8.0 * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Penalize dead space that can't fit even the smallest plausible item,
    // with smooth quadratic penalty scaled by progress.
    if pr < item_size as f64 * 0.25 {
        score += 4.0 * progress * (1.0 - pr / (item_size as f64 * 0.25)) * (1.0 - pr / (item_size as f64 * 0.25)) * 10.0;
    }

    // Lookahead: if next item fits into post_residual, reward this bin smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_q = (next_item_size as f64 / cap) * (pr / cap);
        score -= 6.0 * fit_q;
    } else if next_item_size > 0 {
        // next item won't fit: mild penalty, stronger late in stream
        score += 2.0 + 3.0 * progress;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize so it's chosen only when open bins fit poorly.
    if bin_residual as f64 == cap {
        score += 25.0 - 10.0 * progress;
        // but if item is huge relative to mean residual, opening fresh is less bad
        if (item_size as f64) > mean_residual {
            score -= 15.0;
        }
    }

    // Smooth diversity term: prefer bins whose residual deviates from mean
    // (consume the outliers), quadratic coupling.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.05 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod small integers
    // Penalize post-residuals that are "dead" (small, hard to fill)
    if post_residual > 0 {
        let pr = post_residual;
        // Dead space penalty: residuals below typical small-item floor
        if pr < 10 {
            score += 40.0 * (1.0 - pr as f64 / 10.0);
        }
        // Harmonic favorability: residuals expressible as sums of common item sizes
        // mod classes: 0 mod 10 (aligned), 5 mod 10 (half-aligned)
        let r10 = (pr % 10) as f64;
        score += r10 * 0.8; // misalignment penalty
        let r5 = (pr % 5) as f64;
        score += r5 * 0.5;
        // mod 3 classes: many distributions have items leaving mod-3 structure
        let r3 = (pr % 3) as f64;
        score += r3 * 0.3;
        // Integer division thresholds: reward residuals in "usable bands"
        let band = pr / 20; // 0..=5 bands
        score -= band as f64 * 2.5;
    } else {
        // Perfect fit: strong reward
        score -= 30.0;
    }

    // Lookahead: does post_residual accommodate next item harmonically?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits exactly or leaves good residue
            let next_post = post_residual - next_item_size;
            score -= 6.0;
            if next_post == 0 {
                score -= 10.0; // chain of perfect fits
            } else if next_post < 10 {
                score += 4.0; // creates dead space after next
            }
        } else {
            // this bin becomes closed after this item; slight reward if post_residual small
            score += 2.0 * (post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin is bad
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = cap * 0.55;
        // open early in stream when many items remain: new bins are cheap investments
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        score -= 15.0 * (1.0 - progress);
        // if item is large relative to capacity, new bin is fine
        score -= (item_size as f64 / cap) * 10.0;
        // if existing fitting bins are scarce, new bin reasonable
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // reward tight fits in existing bins
