            score -= (6 - gap) as f64 * 6.0;
        }
    }

    // GEN-10 mutation: hole-shape matching — a post-placement residual is only
    // valuable if it matches a plausible future item size. Reward residuals that
    // are multiples/harmonics of the next item size; penalize residuals that
    // fall just below a multiple (unreachable by any single item).
    if !fresh && next_item_size > 0 && post_residual > 0 {
        let nx_u = next_item_size;
        let k = post_residual / nx_u.max(1);
        let rem = post_residual % nx_u.max(1);
