            // leftover after the chain is a doomed sliver unless it matches next
            if rem2 != nx_u_compat(next_item_size) {
                score += (20 - rem2) as f64 * 1.5 * (1.0 - progress);
            }
        }
        if rem2 >= 25 && rem2 <= 60 {
            // mid-band leftover is reusable if next item could recurse into it
            score -= 10.0 * (1.0 - progress);
        }
    }

