    }

    // GEN-8: near-full bin bonus
    if !fresh && pr <= 6.0 {
        score -= (6.0 - pr) * 8.0 * (0.5 + progress);
    }

    // GEN-8: when several bins fit, extra reward for the tightest relative to the mean
    if fitting_bins_count >= 2 && !fresh {
        let rel = (pr / mean_residual.max(1.0)).min(2.0);
        score += rel * 6.0;
