    // GEN-9: reward bins whose residual after placement can host a plausible
    // future fill — estimate via mean item footprint (capacity - mean_residual
    // approximates mean item size when bins are opened full).
    if !fresh && post_residual > 0 {
        let est_item = (cap - mean_residual).max(1.0);
        let fits_est = (post_residual as f64 / est_item).floor();
