    }

    // GEN-10 mutation: extend the awkward-band idea to a graded penalty —
    // any leftover gap after the next item is placed is a potential dead hole;
    // penalize proportionally to how far it falls short of a full extra item.
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let gap = post_residual - next_item_size;
