    if !fresh && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 20.0 {
            let orphan = (pr / mean_residual.max(1.0)).min(1.5);
            score += miss * (2.5 + 3.0 * progress) * (0.8 + 0.3 * orphan);
        }
    }

    // GEN-9: reward bins whose residual after placement can host a plausible
    // future fill, estimated via mean item footprint. GEN-10: also reward when
    // the leftover after the estimated fill is near zero (recursive packing).
    if !fresh && post_residual > 0 {
        let est_item = (cap - mean_residual).max(1.0);
        let fits_est = (post_residual as f64 / est_item).floor();
        if fits_est >= 1.0 {
            let leftover = post_residual as f64 - fits_est * est_item;
            score -= 14.0 * fits_est.min(3.0) * (1.0 - leftover / est_item) * (1.0 - 0.4 * progress);
            if leftover < 4.0 {
                score -= 10.0 * (1.0 - progress);
            }
        }
    }

    // GEN-9: fresh-bin decision refined — compare waste of opening now vs. the
    // best compaction available in an existing bin. GEN-10: scale the opening
    // threshold by fitting count (more alternatives -> demand better waste).
    if fresh && fitting_bins_count > 0 {
        let waste_existing = bin_residual.saturating_sub(item_size) as f64;
        let item_frac = it / cap;
        let thresh = cap * (0.5 - 0.4 * item_frac) + (fitting_bins_count.min(5) as f64) * 4.0;
        if waste_existing > thresh {
            score -= 45.0 + 0.35 * (waste_existing - thresh);
        }
        if progress < 0.25 && open_bins_count < 8 {
            score -= 30.0 * (1.0 - progress);
        }
    }

    // GEN-9: penalize creating residuals in the "awkward band" that rarely
    // matches typical item sizes.
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap < 6 {
            score -= (6 - gap) as f64 * 6.0;
        }
    }

    // GEN-10 mutation: two-step lookahead waste accounting. When the residual
    // after placing the item can be exactly consumed by the next item AND the
    // leftover after that chain is small, this is the strongest compaction
    // signal — reward proportionally to how many bins compete (scarce fits
    // matter more).
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && rem2 <= item_size {
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score -= 20.0 + 40.0 * scarcity * (1.0 - rem2 as f64 / (item_size as f64).max(1.0));
        }
    }

    // GEN-10: anti-hoarding of large residuals — a bin left with a huge hole
    // that no plausible item (bounded by 2x next item size) can fill is a
    // compaction failure; penalize softly but persistently.
