    // Late-stream new-bin restraint
    if progress > 0.85 && fresh && fitting_bins_count > 0 {
        score += 140.0 * progress;
    }

    // Triple-chain lookahead
    if next_item_size > 0 {
        let pair_sum = item_size.saturating_add(next_item_size);
        if post_residual == pair_sum {
            score -= 110.0 * (1.0 - 0.5 * progress);
        }
        let rem3 = bin_residual.saturating_sub(pair_sum);
        if rem3 > 0 && rem3 <= 100 && rem3 >= next_item_size / 2 {
            score -= 35.0 * (1.0 - progress);
        }
    }

    // Fragmentation guard
    if fitting_bins_count <= 2 && !fresh && pr > 0.5 * cap {
        score += 25.0 + 0.3 * (pr - 0.5 * cap);
    }

    // GEN-8 mutation: dead-space budget shaping
    if pr > 0.0 && pr < cap && !fresh {
        if (pr as f64) < it && progress < 0.9 {
            score += (1.0 - progress) * 30.0 * (pr / cap);
        }
        if nx > 0.0 && (pr - nx).abs() < 3.0 && pr != nx {
            score += 12.0 * (1.0 - progress);
        }
    }

    // GEN-8: near-full bin bonus
    if !fresh && pr <= 6.0 {
        score -= (6.0 - pr as f64) * 8.0 * (0.5 + progress);
    }

    // GEN-8: when several bins fit, extra reward for the tightest relative to the mean
    if fitting_bins_count >= 2 && !fresh {
        let rel = (pr / mean_residual.max(1.0)).min(2.0);
        score += rel * 6.0;
        if pr < 0.15 * cap {
            score -= 30.0 * (1.0 - pr / (0.15 * cap));
        }
    }

    // GEN-8: fresh-bin bias against small items late
    if fresh && item_size <= 30 && fitting_bins_count > 0 && progress > 0.3 {
        score += 90.0 * progress;
    }

    // GEN-9: residual-dead-space coupling
    if !fresh && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 20.0 {
            score += miss * (2.5 + 3.0 * progress);
        }
    }

    // GEN-9: reward bins whose residual after placement can host a plausible future fill
    if !fresh && post_residual > 0 {
        let est_item = (cap - mean_residual).max(1.0);
        let fits_est = (post_residual as f64 / est_item).floor();
        if fits_est >= 1.0 {
            let leftover = post_residual as f64 - fits_est * est_item;
            score -= 14.0 * fits_est.min(3.0) * (1.0 - leftover / est_item) * (1.0 - 0.4 * progress);
        }
    }

    // GEN-9: fresh-bin decision refined
    if fresh && fitting_bins_count > 0 {
        let waste_existing = bin_residual.saturating_sub(item_size) as f64;
        let item_frac = it / cap;
        if waste_existing > cap * (0.5 - 0.4 * item_frac) {
            score -= 45.0 + 0.35 * (waste_existing - cap * (0.5 - 0.4 * item_frac));
        }
        if progress < 0.25 && open_bins_count < 8 {
            score -= 30.0 * (1.0 - progress);
        }
    }

    // GEN-9: penalize awkward-band residuals
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap < 6 {
            score -= (6 - gap) as f64 * 6.0;
        }
    }

    // GEN-10 mutation: extend awkward-band penalty to a graded dead-zone between
    // the next item and twice it — residuals in (nx, 2*nx) rarely get filled by a
    // single next item and block two-item chains; penalize proportionally.
    if !fresh && next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let over = (post_residual - next_item_size) as f64;
        score += over * 0.55 * (0.5 + progress);
    }

    // GEN-10: two-step chain viability — if placing here leaves a residual that
    // can host the next item AND the remainder after that is near zero or below
    // a small item, reward the chain more when bins are plentiful.
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 == 0 {
            score -= 25.0 + 20.0 * (open_bins_count.min(20) as f64) * 0.05;
        } else if (rem2 as f64) <= (nx * 0.35).max(4.0) {
            score -= 15.0 * (1.0 - progress);
        }
    }

    // GEN-10: fresh-bin lookahead — opening a new bin is only attractive if the
    // next item likely cannot use the current bin's leftover after this placement.
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let leftover_here = bin_residual.saturating_sub(item_size);
        if leftover_here >= next_item_size {
            // current bin still usable for next item: opening now wastes that
            score += 70.0 * (1.0 - 0.5 * progress);
        }
    }

    // GEN-10: sharpen near-full preference when few items remain — closing out
    // bins dominates end-of-stream quality.
    if progress > 0.9 && !fresh {
        score -= (cap - pr).max(0.0) * 0.35;
    }

    // GEN-10: mid-band residual shaping — residuals just above half capacity are
    // the most reusable; residuals just below half are the most wasteful.
    if !fresh && pr > 0.0 && pr < cap {
        if pr > half && pr < 0.75 * cap {
            score -= 12.0 * (pr - half) / half;
        } else if pr > 0.25 * cap && pr < half {
            score += 10.0 * (half - pr) / half;
        }
    }

    score
}

