    if post_residual > 0 && (post_residual as f64) < sliver_limit && post_residual != next_item_size {
        score += 40.0 * (1.0 - progress) * (1.0 - post_residual as f64 / sliver_limit);
    }

    // Pair-sum lookahead
    if next_item_size > 0 {
        let pair_sum = item_size.saturating_add(next_item_size);
        if bin_residual >= pair_sum {
            let pair_slack = bin_residual - pair_sum;
            if pair_slack <= 10 {
                score -= 70.0 - 4.0 * pair_slack as f64;
            }
        }
    }

    // Prefer tightest fit when many bins fit
    if fitting_bins_count > 2 {
        score += pr * 0.12;
    }

    // Late-stream new-bin restraint
    if progress > 0.85 && fresh && fitting_bins_count > 0 {
        score += 140.0 * progress;
    }

    // Triple-chain lookahead
    if next_item_size > 0 {
        let pair_sum = item_size.saturating_add(next_item_size);
        if post_residual == pair_sum {
            score -= 110.0 * (1.0 - 0.5 * progress);
        }
        let rem3 = bin_residual.saturating_sub(pair_sum);
        if rem3 > 0 && rem3 <= 100 && rem3 >= next_item_size / 2 {
            score -= 35.0 * (1.0 - progress);
        }
    }

    // Fragmentation guard
    if fitting_bins_count <= 2 && !fresh && pr > 0.5 * cap {
        score += 25.0 + 0.3 * (pr - 0.5 * cap);
    }

    // GEN-8 mutation: dead-space budget shaping
    if pr > 0.0 && pr < cap && !fresh {
        if (pr as f64) < it && progress < 0.9 {
            score += (1.0 - progress) * 30.0 * (pr / cap);
        }
        if nx > 0.0 && (pr - nx).abs() < 3.0 && pr != nx {
            score += 12.0 * (1.0 - progress);
        }
    }

    // GEN-8: near-full bin bonus
    if !fresh && pr <= 6.0 {
        score -= (6.0 - pr as f64) * 8.0 * (0.5 + progress);
    }

    // GEN-8: when several bins fit, extra reward for the tightest relative to the mean
    if fitting_bins_count >= 2 && !fresh {
        let rel = (pr / mean_residual.max(1.0)).min(2.0);
        score += rel * 6.0;
        if pr < 0.15 * cap {
            score -= 30.0 * (1.0 - pr / (0.15 * cap));
        }
    }

    // GEN-8: fresh-bin bias against small items late
    if fresh && item_size <= 30 && fitting_bins_count > 0 && progress > 0.3 {
        score += 90.0 * progress;
    }

    // GEN-9: residual-dead-space coupling — penalize holes too small for the next item
    if !fresh && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 20.0 {
            score += miss * (2.5 + 3.0 * progress);
        }
    }

    // GEN-9: reward bins whose residual after placement can host plausible future fills
    if !fresh && post_residual > 0 {
        let est_item = (cap - mean_residual).max(1.0);
        let fits_est = (post_residual as f64 / est_item).floor();
        if fits_est >= 1.0 {
            let leftover = post_residual as f64 - fits_est * est_item;
            score -= 14.0 * fits_est.min(3.0) * (1.0 - leftover / est_item) * (1.0 - 0.4 * progress);
        }
    }

    // GEN-9: fresh-bin decision refined — compare waste of opening now vs best compaction
    if fresh && fitting_bins_count > 0 {
        let waste_existing = bin_residual.saturating_sub(item_size) as f64;
        let item_frac = it / cap;
        if waste_existing > cap * (0.5 - 0.4 * item_frac) {
            score -= 45.0 + 0.35 * (waste_existing - cap * (0.5 - 0.4 * item_frac));
        }
        if progress < 0.25 && open_bins_count < 8 {
            score -= 30.0 * (1.0 - progress);
        }
    }

    // GEN-9: penalize awkward-band residuals just above the next item
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap < 6 {
            score -= (6 - gap) as f64 * 6.0;
        }
    }

    // GEN-11: dead-space budget accounting (refined in GEN-12: permanence
    // curve steepened and the recoverability threshold now couples to the
    // next item size so holes that exactly host nx are not over-priced).
    if !fresh && post_residual > 0 {
        let remaining = ((total_items - step_index) as f64).max(1.0);
        let hole = pr;
        let est_item = (cap - mean_residual).max(1.0);
        let host_target = if nx > 0.0 { est_item.min(nx).max(1.0) } else { est_item };
        let recoverable = if hole >= host_target * 0.6 { 1.0 } else { hole / (host_target * 0.6) };
        let permanence = (1.0 - recoverable).clamp(0.0, 1.0);
        let hole_price = hole * (0.15 + 0.65 * permanence) * (1.0 - 0.6 / (1.0 + remaining * 0.02));
        score += hole_price;
        if next_item_size > 0 && hole >= next_item_size as f64 {
            let refund = (hole - next_item_size as f64).min(hole);
            score -= refund * 0.4 * (1.0 - progress);
        }
    }

    // GEN-11: two-step chain refinement
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 >= 0.2 * cap {
            score -= 22.0 * (1.0 - 0.5 * progress);
        } else if rem2 > 0 && (rem2 as f64) < 0.08 * cap {
            score += 14.0 * (1.0 - rem2 as f64 / (0.08 * cap));
        }
    }

    // GEN-11: fresh-bin gate tightened
    if fresh && fitting_bins_count >= 2 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < 0.25 * cap {
            score += 70.0 * (1.0 - 0.5 * progress);
        }
    }

    // GEN-12: hole-size histogram coupling — a hole is only worth keeping if
    // it matches a plausible item size; holes landing in the "dead band"
    // between the observed mean item footprint and capacity are priced
    // extra since they rarely get filled exactly.
    if !fresh && post_residual > 0 {
        let est_item = (cap - mean_residual).max(1.0);
        if pr > est_item * 1.4 && pr < cap * 0.85 {
            let deadness = ((pr - est_item * 1.4) / (cap * 0.85 - est_item * 1.4).max(1.0)).clamp(0.0, 1.0);
            score += deadness * 20.0 * (0.4 + 0.6 * progress);
        }
    }

    // GEN-12: next-item squeeze bonus — when placing here leaves a residual
    // that the next item would leave at a perfect zero, boost the chain reward
    // proportionally to how much of the stream remains.
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 <= est_item_floor(cap, mean_residual) {
            score -= 18.0 * (1.0 - progress) * (1.0 - rem2 as f64 / est_item_floor(cap, mean_residual).max(1.0));
        }
    }

    // GEN-12: fresh-bin parity check — when the new bin would end up emptier
    // than the average open bin after placement, penalize slightly more to
    // consolidate load into existing partial bins.
    if fresh && fitting_bins_count > 0 {
        let new_res = cap - it;
        if new_res > mean_residual * 1.3 && progress > 0.2 {
            score += 25.0 * (new_res - mean_residual * 1.3).min(40.0) / 40.0;
        }
    }

    score
}

fn est_item_floor(cap: f64, mean_residual: f64) -> f64 {
    (cap - mean_residual).max(1.0).floor()
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
