        } else if rem2 > 0 && (rem2 as f64) < 0.08 * cap {
            score += 14.0 * (1.0 - rem2 as f64 / (0.08 * cap));
        }
    }

    // GEN-12: large items strongly prefer any existing bin that fits
    if it > 0.7 * cap && !fresh {
