        score -= (6.0 - pr) * 8.0 * (0.5 + progress);
    }

    // GEN-8: when several bins fit, extra reward for tightest relative to mean
    if fitting_bins_count >= 2 && !fresh {
        let rel = (pr / mean_residual.max(1.0)).min(2.0);
        score += rel * 6.0;
        if pr < 0.15 * cap {
            score -= 30.0 * (1.0 - pr / (0.15 * cap));
        }
    }

    // GEN-11 mutation: awkward-band gap penalty strengthened with progress coupling
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap < 8 {
            score -= (8 - gap) as f64 * 7.0 * (0.5 + progress);
        }
    }

    // GEN-11 mutation: mid-band residual trap
    if !fresh && nx > 0.0 && pr >= nx && pr < 0.3 * cap && fitting_bins_count > 1 {
        let waste = pr - nx;
        score += waste * 1.5 * progress;
    }

    // GEN-11 mutation: fresh-bin bias against small items late
    if fresh && item_size <= 30 && fitting_bins_count > 0 && progress > 0.3 {
        score += 90.0 * progress;
    }

    // GEN-13 mutation: dead-space budget accounting — price each placement's
    // leftover hole against remaining stream length
    if !fresh && post_residual > 0 {
        let remaining = ((total_items - step_index) as f64).max(1.0);
        let est_item = (cap - mean_residual).max(1.0);
        let recoverable = if pr >= est_item * 0.5 { 1.0 } else { pr / (est_item * 0.5) };
        let permanence = (1.0 - recoverable).clamp(0.0, 1.0);
        let hole_price = pr * (0.15 + 0.55 * permanence) * (1.0 - 0.6 / (1.0 + remaining * 0.02));
        score += hole_price;
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let refund = (pr - next_item_size as f64).min(pr);
            score -= refund * 0.35 * (1.0 - progress);
        }
    }

    // GEN-13 mutation: two-step chain refinement — reusable band vs stranded remainder
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 >= 0.2 * cap {
            score -= 22.0 * (1.0 - 0.5 * progress);
        } else if rem2 > 0 && (rem2 as f64) < 0.08 * cap {
            score += 14.0 * (1.0 - rem2 as f64 / (0.08 * cap));
        }
    }

    // GEN-13 mutation: fresh-bin gate tightened
    if fresh && fitting_bins_count >= 2 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < 0.25 * cap {
            score += 70.0 * (1.0 - 0.5 * progress);
        }
    }

    // GEN-13 mutation: triple-chain lookahead — reward residuals surviving two more placements
    if !fresh && next_item_size > 0 {
        let pair_sum = item_size.saturating_add(next_item_size);
        if post_residual == pair_sum {
            score -= 110.0 * (1.0 - 0.5 * progress);
        }
        let rem3 = bin_residual.saturating_sub(pair_sum);
        if rem3 > 0 && rem3 <= 100 && rem3 >= next_item_size / 2 {
            score -= 35.0 * (1.0 - progress);
        }
    }

    // GEN-14 mutation: residual-fit ratio coupling — combine fine-grained residual
    // fitting with lookahead anticipation by rewarding bins whose post-residual
    // is a near-exact multiple of the next item size (multi-fill potential).
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let multi = (post_residual as f64 / nx).floor();
        if multi >= 2.0 {
            let leftover = pr - multi * nx;
            if leftover <= 3.0 {
                score -= 55.0 * (1.0 - leftover / 3.0) * (1.0 - 0.4 * progress) * multi.min(3.0).ln();
            }
        }
        // penalize residual that can host the next item only once with a
        // large stranded remainder that no typical item can fill
        let est_item = (cap - mean_residual).max(1.0);
        if pr - nx < est_item * 0.3 && pr - nx > 0.0 {
            score += (pr - nx) * (0.8 + 0.7 * progress);
        }
    }

    // GEN-14 mutation: capacity-normalized compaction pressure — when many bins
    // are open, prefer the bin that leaves the smallest relative hole vs capacity
    if open_bins_count > 6 && !fresh {
        score += (pr / cap) * (open_bins_count.min(40) as f64) * 1.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
