    }

    // GEN-8: fresh-bin bias against small items late
    if fresh && item_size <= 30 && fitting_bins_count > 0 && progress > 0.3 {
        score += 90.0 * progress;
    }

    // GEN-9: residual-dead-space coupling — penalize holes too small for the next item
    if !fresh && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 20.0 {
            score += miss * (2.5 + 3.0 * progress);
        }
    }

    // GEN-9: reward bins whose residual after placement can host plausible future fills
    if !fresh && post_residual > 0 {
        let est_item = (cap - mean_residual).max(1.0);
        let fits_est = (post_residual as f64 / est_item).floor();
        if fits_est >= 1.0 {
            let leftover = post_residual as f64 - fits_est * est_item;
            score -= 14.0 * fits_est.min(3.0) * (1.0 - leftover / est_item) * (1.0 - 0.4 * progress);
        }
    }

    // GEN-9: fresh-bin decision refined — compare waste of opening now vs best compaction
    if fresh && fitting_bins_count > 0 {
        let waste_existing = bin_residual.saturating_sub(item_size) as f64;
        let item_frac = it / cap;
        if waste_existing > cap * (0.5 - 0.4 * item_frac) {
            score -= 45.0 + 0.35 * (waste_existing - cap * (0.5 - 0.4 * item_frac));
        }
        if progress < 0.25 && open_bins_count < 8 {
            score -= 30.0 * (1.0 - progress);
        }
    }

    // GEN-9: penalize awkward-band residuals just above the next item
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap < 6 {
            score -= (6 - gap) as f64 * 6.0;
        }
    }

    // GEN-11: dead-space budget accounting
    if !fresh && post_residual > 0 {
        let remaining = ((total_items - step_index) as f64).max(1.0);
        let hole = pr;
        let est_item = (cap - mean_residual).max(1.0);
        let recoverable = if hole >= est_item * 0.5 { 1.0 } else { hole / (est_item * 0.5) };
        let permanence = (1.0 - recoverable).clamp(0.0, 1.0);
        let hole_price = hole * (0.15 + 0.55 * permanence) * (1.0 - 0.6 / (1.0 + remaining * 0.02));
        score += hole_price;
        if next_item_size > 0 && hole >= next_item_size as f64 {
            let refund = (hole - next_item_size as f64).min(hole);
            score -= refund * 0.35 * (1.0 - progress);
        }
    }

    // GEN-11: two-step chain refinement
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 >= 0.2 * cap {
            score -= 22.0 * (1.0 - 0.5 * progress);
        } else if rem2 > 0 && (rem2 as f64) < 0.08 * cap {
            score += 14.0 * (1.0 - rem2 as f64 / (0.08 * cap));
        }
    }

    // GEN-11: fresh-bin gate tightened
    if fresh && fitting_bins_count >= 2 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < 0.25 * cap {
            score += 70.0 * (1.0 - 0.5 * progress);
        }
    }

    // GEN-14 mutation: multi-item hole capacity pricing — a residual hole that can
    // absorb several typical items is far more valuable than one that absorbs a
    // single item; scale the recoverability reward by the number of future items
    // the hole can host, weighted by remaining stream length.
    if !fresh && post_residual > 0 {
        let est_item = (cap - mean_residual).max(1.0);
        let hosts = (pr / est_item).floor().min(4.0);
        if hosts >= 1.0 {
            let remaining_frac = ((total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64).min(1.0);
            score -= 10.0 * hosts * remaining_frac * (1.0 - (pr - hosts * est_item) / est_item).max(0.0);
        }
    }

    // GEN-14: exact triple-fit lookahead — if item + next item + a typical item
    // exactly matches the current residual, reward strongly.
    if !fresh && next_item_size > 0 {
        let est_item = (cap - mean_residual).max(1.0);
        let triple = item_size.saturating_add(next_item_size) as f64 + est_item;
        if (bin_residual as f64 - triple).abs() < 2.0 {
            score -= 55.0 * (1.0 - 0.6 * progress);
        }
    }

    // GEN-14: fresh-bin refinement — when the next item is large and would not
    // fit in the leftover of the best existing bin, opening fresh is safer.
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let best_leftover = bin_residual.saturating_sub(item_size);
        if best_leftover < next_item_size && next_item_size > item_size {
            score += 40.0 * (1.0 - progress);
        }
    }

    score
}

