            score -= 30.0 * (1.0 - progress);
        }
    }

    // GEN-9: penalize awkward-band residuals just above the next item
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap < 6 {
            score -= (6 - gap) as f64 * 6.0;
        }
    }

    // GEN-11: dead-space budget accounting
    if !fresh && post_residual > 0 {
        let remaining = ((total_items - step_index) as f64).max(1.0);
        let hole = pr;
        let est_item = (cap - mean_residual).max(1.0);
        let recoverable = if hole >= est_item * 0.5 { 1.0 } else { hole / (est_item * 0.5) };
        let permanence = (1.0 - recoverable).clamp(0.0, 1.0);
        let hole_price = hole * (0.15 + 0.55 * permanence) * (1.0 - 0.6 / (1.0 + remaining * 0.02));
        score += hole_price;
        if next_item_size > 0 && hole >= next_item_size as f64 {
            let refund = (hole - next_item_size as f64).min(hole);
            score -= refund * 0.35 * (1.0 - progress);
        }
    }

    // GEN-11: two-step chain refinement
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 >= 0.2 * cap {
            score -= 22.0 * (1.0 - 0.5 * progress);
        } else if rem2 > 0 && (rem2 as f64) < 0.08 * cap {
            score += 14.0 * (1.0 - rem2 as f64 / (0.08 * cap));
        }
    }

    // GEN-11: fresh-bin gate tightened
    if fresh && fitting_bins_count >= 2 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < 0.25 * cap {
            score += 70.0 * (1.0 - 0.5 * progress);
        }
    }

    // GEN-15 mutation A: recoverable-hole refinement — a hole counts as recoverable
    // only if it can host the next item or a typical item; otherwise price it harder
    // when the stream still has many items left (holes early are the worst waste).
    if !fresh && post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && (rem2 as f64) < 0.5 * (cap - mean_residual).max(1.0) {
            // after the next item, leftover is sub-typical: mild penalty scaled by remaining stream
            let remaining_frac = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
            score += rem2 as f64 * 0.55 * remaining_frac;
        }
    }

    // GEN-15 mutation B: dual-fit lookahead — reward bins where both this item and
    // the next land with near-zero remainder, extra weight early/mid stream.
    if !fresh && next_item_size > 0 && bin_residual >= item_size.saturating_add(next_item_size) {
        let rem2 = bin_residual - item_size.saturating_add(next_item_size);
        if rem2 == 0 {
            score -= 120.0 * (1.0 - 0.4 * progress);
        } else if rem2 <= 3 {
            score -= 55.0 * (1.0 - 0.4 * progress);
        }
    }

    // GEN-15 mutation C: fresh-bin gate uses next-item compatibility — opening a
    // new bin is more attractive when the fresh residual would exactly host the
    // next item after this one (perfect two-step chain from a clean bin).
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let rem_after_pair = bin_capacity.saturating_sub(item_size.saturating_add(next_item_size));
        if rem_after_pair == 0 {
            score -= 160.0 * (1.0 - progress);
        } else if rem_after_pair <= 8 {
            score -= 60.0 * (1.0 - progress) * (1.0 - rem_after_pair as f64 / 8.0);
        }
    }

    // GEN-15 mutation D: sharpen tightest-fit selection among many candidates by
    // amplifying the relative ranking of small residuals when bins are plentiful.
    if fitting_bins_count >= 3 && !fresh && pr > 0.0 {
        let rank_gain = (1.0 - pr / cap).powi(2);
        score -= 20.0 * rank_gain * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it is smaller than the smallest plausible item (1..100 range),
    // but practically, gaps below ~10 are almost never reusable.
    if post_residual < 10 {
        score += 40.0; // unusable dead space
    } else if post_residual < 20 {
        score += 15.0; // rarely usable
    } else if post_residual < 35 {
        score += 4.0; // usable only for small items
    }

    // Reward tight fits: smaller post_residual relative to item size is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Open-bin pressure: discourage spreading across many bins when a near-full
    // placement is available; encourage using existing bins when few are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (bin_capacity as f64);
    score += pressure * (2.0 + 6.0 * progress);

    // Last-chance bin: strongly favor using the only bin that can fit the item,
    // otherwise a new bin must be opened.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward heavily.
    if next_item_size > 0 && (post_residual as f64) == next_item_size as f64 {
        score -= 20.0;
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 5.0; // next item can still be placed here
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 8.0; // dead space relative to lookahead
    }

    // New-bin candidate handling: only prefer a fresh bin if all open bins would
    // leave terrible dead space. Compare against mean residual of open bins.
    if bin_residual == bin_capacity {
        // Fresh bin starts with full residual; baseline score is post_residual = 100 - item.
        // Penalize opening a new bin when open bins exist and could reasonably fit.
        if open_bins_count > 0 {
            let avg_dead = mean_residual - item_size as f64;
            if avg_dead >= 0.0 && avg_dead <= 30.0 {
                score += 30.0; // existing bins would leave acceptable space
            }
        }
        // Slight intrinsic cost for opening a new bin grows with number of open bins
        // being low (we want to consolidate early).
        if open_bins_count == 0 {
            score -= 5.0;
        }
    }

    // Mean residual coupling: bins with residual far below mean are already tight;
    // prefer placing into bins whose residual is above mean (keeps balance).
    let diff = bin_residual as f64 - mean_residual;
    if diff > 0.0 {
        score -= 2.0 * (diff / bin_capacity as f64);
    } else {
        score += 2.0 * ((-diff) / bin_capacity as f64);
    }

    score
}

