    // deepen the chain reward when the post-next remainder is exactly a
    // plausible item size band (near-zero-dead-space chain of length 2).
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 <= mean_residual.max(4.0) * 1.2 && rem2 > 0 {
            score -= 26.0 * (1.0 - progress);
        }
    }

    // GEN-15 mutation B: multi-fit discrimination sharpened — when many bins
    // can host the item, weight the tightest fit more aggressively against
    // the observed residual spread, targeting the diagnosed dead-space ratio.
    if fitting_bins_count >= 3 && !fresh && mean_residual > 0.0 {
        let spread_penalty = (pr / mean_residual).sqrt();
        score += spread_penalty * 10.0 * (0.4 + 0.6 * progress);
