            score -= (12.0 - pr) * 3.5 * (1.0 - 0.5 * progress);
        }
    }

    // GEN-15 mutation C: fresh-bin lookahead vs next item — opening a new bin
    // is worthwhile when the next item is large and existing residuals would
    // strand it; discourage otherwise.
    if fresh && next_item_size > 0 && fitting_bins_count > 0 {
        let waste_existing = bin_residual.saturating_sub(item_size) as f64;
        if next_item_size as f64 > waste_existing * 0.9 && waste_existing > 0.3 * cap {
            score -= 40.0 * (1.0 - progress);
        } else if waste_existing < 0.15 * cap {
            score += 55.0 * (1.0 - 0.4 * progress);
        }
    }

    // GEN-15 mutation D: residual band harmonization — mildly favor placements
    // whose post-residual sits just below a "typical item" multiple, keeping
    // future small-item fits near-perfect.
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let k = (pr / mean_residual).round().max(1.0);
        let band_gap = (pr - k * mean_residual).abs();
        score += band_gap * 0.9 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward when post_residual exactly matches next item (perfect 2-step chain)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - gap / 100.0).max(0.0);
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize post_residual that is too small for next item (dead space)
        if (post_residual as u32) < next_item_size {
            score += 15.0;
        }
    } else {
        // Last item: just minimize waste
        score = post_residual as f64;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size >= 50 {
            score -= 25.0;
        }
        // If next item is small, new bin wastes pairing potential
        if next_item_size > 0 && next_item_size <= item_size {
            score += 10.0;
        }
    }

    score
}

