    if fresh && it > 0.6 * cap && fitting_bins_count > 0 {
        let waste_existing = bin_residual.saturating_sub(item_size) as f64;
        if waste_existing < 0.1 * cap {
            score += 80.0;
        } else {
            score -= 40.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (low post residual).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    } else {
        // Penalize dead space super-linearly; residual below 10 is nearly unusable.
        let dead = post_residual.min(9) as f64;
        score += (10.0 - dead) * (10.0 - dead) * 0.8;
    }

    // Last-chance bonus: only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward leaving residual that still fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if next item would exactly consume post_residual only when it's a perfect follow-up? Reward that too.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Penalize leaving residual that next item cannot use and is small (dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0;
    }

    // Time horizon: early in stream, be conservative (favor spreading into new bins less);
    // late in stream, prefer filling existing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0;

    // Global state: many open bins with high mean residual -> discourage opening new bins,
    // encourage using bins with above-average residual.
    if bin_residual < bin_capacity {
        if (bin_residual as f64) > mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }
    if open_bins_count > 8 {
        score -= 4.0; // consolidate into existing bins
    }

    // New-bin candidate: only attractive when the item is large and no good fit exists.
    if bin_residual == bin_capacity {
        if item_size >= 70 && (fitting_bins_count == 0 || post_residual < 15) {
            score -= 18.0;
        } else {
            score += 30.0;
        }
    }

    score
}

