        if best_waste < 0.25 * cap {
            score += 70.0 * (1.0 - 0.5 * progress);
        }
    }

    // ---- GEN-15 mutations ----

    // GEN-15: multiplicative hole-cost coupling — instead of pricing the hole
    // linearly, scale its cost by how poorly it matches any "natural" fill size
