    // multiple of the estimated item size is cheap; an odd-sized hole is
    // expensive dead space.
    if !fresh && post_residual > 0 {
        let hole = pr;
        let est_item = (cap - mean_residual).max(1.0);
        let candidates = [nx, it, est_item];
        let mut best_align = f64::INFINITY;
        for c in candidates.iter() {
            if *c > 0.5 {
                let k = (hole / c).round().max(1.0);
                let align = (hole - k * c).abs() / c;
                best_align = best_align.min(align);
            }
        }
        let align = best_align.min(1.0);
        score += align * 55.0 * (0.4 + 0.6 * progress) * (hole / cap).sqrt();
    }

    // GEN-15: bin-level saturation targeting — when a bin's residual after
    // placement is within a small band of a "domino chain" (item + next item
    // + mean item), reward it strongly; this encourages multi-item fill plans
    // that leave near-zero final waste.
    if !fresh && next_item_size > 0 {
        let est_item = (cap - mean_residual).max(1.0);
        let chain2 = it + nx;
        let chain3 = chain2 + est_item;
        for (chain, w) in [(chain2, 26.0), (chain3, 16.0)] {
            if bin_residual as f64 >= chain {
                let slack = bin_residual as f64 - chain;
                if slack < 10.0 {
                    score -= w * (1.0 - slack / 10.0) * (1.0 - 0.5 * progress);
                }
            }
        }
    }

    // GEN-15: residual-bucket competition — among fitting bins, reward those
    // whose post-residual falls in the smallest distinct bucket, sharpening
    // best-fit selection beyond the raw linear pr term.
    if !fresh && fitting_bins_count >= 2 {
        let bucket = (pr / 10.0).floor();
        score += bucket * 4.0 * (0.5 + progress);
    }

    // GEN-15: fresh-bin lookahead parity — when the next item is large relative
    // to the item being placed, opening a fresh bin now lets the next item
    // potentially pair with the residual; reward that configuration mildly.
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        if next_item_size >= item_size && bin_residual.saturating_sub(item_size) >= next_item_size {
            score -= 35.0 * (1.0 - progress);
        }
    }

    // GEN-15: late-stream exact-closure push — near the end, a placement that
    // leaves a residual exactly equal to the next item is almost a guaranteed
    // extra bin saved; amplify the existing chain bonus late.
    if !fresh && next_item_size > 0 && post_residual == next_item_size && progress > 0.6 {
        score -= 120.0 * (progress - 0.6) / 0.4;
    }

