    let open_pressure = (open_bins_count as f64).ln() + 1.0;
    score += norm_pr * open_pressure * 3.0;

    // Deviation from mean residual: prefer bins near the mean (balanced packing),
    // with weight growing over the stream
    let dev = (pr as f64 - mean_residual) / cap;
    score += dev.abs() * (2.0 + 6.0 * progress);

    // New-bin candidate: make empty bin attractive only when item is large relative to capacity
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score -= 4.0 * fill_ratio * fill_ratio;
        score += 8.0 * (1.0 - fill_ratio);
    }

    score
}

