        let hole_price = pr * (0.15 + 0.55 * permanence) * (1.0 - 0.6 / (1.0 + remaining * 0.02));
        score += hole_price;
        if next_item_size > 0 && pr >= nx {
            let refund = (pr - nx).min(pr);
            score -= refund * 0.35 * (1.0 - progress);
        }
    }

    // GEN-16: two-step chain refinement — residual after next item in reusable band
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 >= 0.2 * cap {
            score -= 22.0 * (1.0 - 0.5 * progress);
        } else if rem2 > 0 && (rem2 as f64) < 0.08 * cap {
            score += 14.0 * (1.0 - rem2 as f64 / (0.08 * cap));
        }
    }

    // GEN-16: reward residuals that can host plausible future fills
    if !fresh && post_residual > 0 {
        let est_item = (cap - mean_residual).max(1.0);
        let fits_est = (pr / est_item).floor();
        if fits_est >= 1.0 {
            let leftover = pr - fits_est * est_item;
            score -= 14.0 * fits_est.min(3.0) * (1.0 - leftover / est_item) * (1.0 - 0.4 * progress);
        }
    }

    // GEN-16: awkward-band residuals just above the next item
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap < 6 {
            score -= (6 - gap) as f64 * 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Bins whose post_residual falls into "useful" residue classes are rewarded.
    let pr = post_residual;
    let class = pr % 25; // quarter-capacity harmonic class
    match class {
        0 => score -= 18.0,            // perfect multiple of quarter capacity: highly reusable
        10 => score -= 10.0,           // exactly fits a small item class
        5 | 15 | 20 => score -= 5.0,   // decent reusable slots
        _ => score += 6.0,             // awkward dead space
    }

    // Integer-division thresholds: post_residual bucketed by size tiers.
    if pr == 0 {
        score -= 40.0; // perfect packing is best possible
    } else if pr < 10 {
        score += 25.0; // unusable sliver: worst dead space
    }

    // Coupling with lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= 8.0;
            // harmonic match on modulo class between next item and post_residual
            if (pr % 10) == (next_item_size % 10) {
                score -= 6.0;
            }
        } else {
            score += 4.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer tightest relative fit.
    score += (post_residual as f64) / (bin_capacity as f64) * 10.0;

    // Penalize opening new bins when few items remain relative to stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive when mean residual across open bins is poor
        score += 12.0 * (mean_residual / bin_capacity as f64) - 10.0 * progress;
        if open_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        score -= 3.0; // mild bias toward reusing open bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
