    if fitting_bins_count >= 2 && !fresh {
        let rel = (pr / mean_residual.max(1.0)).min(2.0);
        score += rel * 6.0;
        if pr < 0.15 * cap {
            score -= 30.0 * (1.0 - pr / (0.15 * cap));
        }
    }

    // GEN-8: fresh-bin bias against small items late
    if fresh && item_size <= 30 && fitting_bins_count > 0 && progress > 0.3 {
        score += 90.0 * progress;
    }

    // GEN-9: residual-dead-space coupling — penalize holes too small for the next item
    if !fresh && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 20.0 {
            score += miss * (2.5 + 3.0 * progress);
        }
    }

    // GEN-9: reward bins whose residual after placement can host plausible future fills
    if !fresh && post_residual > 0 {
        let est_item = (cap - mean_residual).max(1.0);
        let fits_est = (post_residual as f64 / est_item).floor();
        if fits_est >= 1.0 {
            let leftover = post_residual as f64 - fits_est * est_item;
            score -= 14.0 * fits_est.min(3.0) * (1.0 - leftover / est_item) * (1.0 - 0.4 * progress);
        }
    }

    // GEN-9: fresh-bin decision refined — compare waste of opening now vs best compaction
    if fresh && fitting_bins_count > 0 {
        let waste_existing = bin_residual.saturating_sub(item_size) as f64;
        let item_frac = it / cap;
        if waste_existing > cap * (0.5 - 0.4 * item_frac) {
            score -= 45.0 + 0.35 * (waste_existing - cap * (0.5 - 0.4 * item_frac));
        }
        if progress < 0.25 && open_bins_count < 8 {
            score -= 30.0 * (1.0 - progress);
        }
    }

    // GEN-9: penalize awkward-band residuals just above the next item
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap < 6 {
            score -= (6 - gap) as f64 * 6.0;
        }
    }

    // GEN-11 mutation: dead-space budget accounting
    if !fresh && post_residual > 0 {
        let remaining = ((total_items - step_index) as f64).max(1.0);
        let hole = pr;
        let est_item = (cap - mean_residual).max(1.0);
        let recoverable = if hole >= est_item * 0.5 { 1.0 } else { hole / (est_item * 0.5) };
        let permanence = (1.0 - recoverable).clamp(0.0, 1.0);
        let hole_price = hole * (0.15 + 0.55 * permanence) * (1.0 - 0.6 / (1.0 + remaining * 0.02));
        score += hole_price;
        if next_item_size > 0 && hole >= next_item_size as f64 {
            let refund = (hole - next_item_size as f64).min(hole);
            score -= refund * 0.35 * (1.0 - progress);
        }
    }

    // GEN-11: two-step chain refinement
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 >= 0.2 * cap {
            score -= 22.0 * (1.0 - 0.5 * progress);
        } else if rem2 > 0 && (rem2 as f64) < 0.08 * cap {
            score += 14.0 * (1.0 - rem2 as f64 / (0.08 * cap));
        }
    }

    // GEN-11: fresh-bin gate tightened
    if fresh && fitting_bins_count >= 2 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < 0.25 * cap {
            score += 70.0 * (1.0 - 0.5 * progress);
        }
    }

    // GEN-16 mutation A: exact two-item completion — if the residual after
    // placement equals a plausible future item (estimated from the observed
    // mean footprint), reward the bin as a predicted perfect closure.
    if !fresh && post_residual > 0 && mean_residual > 0.5 {
        let est = (cap - mean_residual).round().max(1.0);
        if (pr - est).abs() <= 2.0 {
            score -= 55.0 * (1.0 - 0.4 * progress);
        }
        // quarter/half-capacity harmonic residuals are highly reusable targets
        for k in [4.0f64, 3.0, 2.0] {
            if (pr - cap / k).abs() <= 3.0 {
                score -= 20.0 * (1.0 - progress);
            }
        }
    }

    // GEN-16 mutation B: next-item orphan risk — if this placement leaves a
    // residual that neither fits the next item nor is close to it, and the
    // bin was already tight, apply a graded penalty proportional to how
    // "stranded" the hole is relative to the mean item footprint.
    if !fresh && next_item_size > 0 && post_residual > 0 {
        let est_item = (cap - mean_residual).max(1.0);
        if pr < nx {
            let stranded = (nx - pr) / est_item;
            if stranded < 0.5 {
                score += 25.0 * (0.5 - stranded) * (0.5 + progress);
            }
        }
    }

    // GEN-16 mutation C: fresh-bin switch arbitration — open a new bin only
    // when the best existing fit would strand more than the expected future
    // fill of that bin; price the switch against remaining stream length.
    if fresh && fitting_bins_count > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        let remaining_frac = 1.0 - progress;
        let strand_threshold = cap * (0.30 + 0.25 * (1.0 - remaining_frac));
        if best_waste > strand_threshold {
            score -= (best_waste - strand_threshold) * (0.4 + 0.4 * remaining_frac);
        } else {
            score += 40.0 * (1.0 - best_waste / strand_threshold.max(1.0));
        }
    }

    // GEN-16 mutation D: compaction steering when many bins fit — reward
    // minimization of post-residual directly, scaled by how many options exist.
    if fitting_bins_count >= 3 && !fresh {
        score += pr * 0.10 * (fitting_bins_count.min(8) as f64 / 8.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible future item are "dead space" -> heavy penalty.
    let dead_threshold: u32 = 10; // smallest possible item
    if post_residual < dead_threshold {
        // Perfect fill: reward strongly.
        score -= 40.0;
    } else {
        // Penalize small-but-nonzero gaps quadratically (hard-to-use slivers).
        let gap = post_residual as f64;
        if gap < 25.0 {
            score += (25.0 - gap) * (25.0 - gap) * 0.35;
        }
    }

    // Reward bins whose post-residual still matches the lookahead item size:
    // a perfect two-item chain is highly desirable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Lookahead won't fit here: mild penalty proportional to waste.
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Tight fit reward: how much of the bin the current item consumes.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; with few bins, opening a new bin is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= pressure * 2.5;

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Deviation from mean residual: prefer bins that are either much fuller
    // (low residual) than average; penalize near-average slack.
    let dev = bin_residual as f64 - mean_residual;
    score -= dev * 0.15;
    score += (dev.abs()) * 0.05;

    // Late in the stream, consolidate aggressively (fewer residual fragments).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0 - progress * 2.0;

    // New-bin candidate: make it attractive only when this item is large
    // (a big item deserves a fresh bin) and open-bin pressure is high.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 10.0;
        score = 100.0 - large_item_bonus - pressure * 1.5;
        // Late stream: discourage opening new bins, force consolidation.
        score += progress * 20.0;
        // If only this bin fits, a new bin is actually fine.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}

