pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the leftover space after
    // placing the current item matches the next item's size exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // Tight lookahead fit: strongly subtract.
        score -= (bin_capacity as f64) * (1.0 - diff / (bin_capacity as f64)) * 0.5;
        // Perfect match bonus.
        if diff == 0.0 {
            score -= 25.0;
        } else if diff <= 10.0 {
            score -= 10.0 - diff * 0.5;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize the wasted lookahead potential.
        score += (next_item_size - post_residual) as f64 * 0.3;
