    // Penalize creating tiny unusable dead space (relative to smallest item ~1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Progression: later in stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * open_bins_count as f64 * 0.2;

    score
}

