        if waste_existing > cap * (0.5 - 0.4 * item_frac) {
            score -= 45.0 + 0.35 * (waste_existing - cap * (0.5 - 0.4 * item_frac));
        }
        if progress < 0.25 && open_bins_count < 8 {
            score -= 30.0 * (1.0 - progress);
        }
    }

    // GEN-11: awkward-band gap penalty strengthened with progress coupling
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap < 8 {
            score -= (8 - gap) as f64 * 7.0 * (0.5 + progress);
        }
    }

    // GEN-11: mid-band residual trap
    if !fresh && nx > 0.0 && pr >= nx && pr < 0.3 * cap && fitting_bins_count > 1 {
        let waste = pr - nx;
        score += waste * 1.5 * progress;
    }

    // GEN-11: fresh-bin bias against small items late
    if fresh && item_size <= 30 && fitting_bins_count > 0 && progress > 0.3 {
        score += 90.0 * progress;
    }

    // GEN-13: dead-space budget accounting
    if !fresh && post_residual > 0 {
        let remaining = ((total_items - step_index) as f64).max(1.0);
        let est_item = (cap - mean_residual).max(1.0);
        let recoverable = if pr >= est_item * 0.5 { 1.0 } else { pr / (est_item * 0.5) };
        let permanence = (1.0 - recoverable).clamp(0.0, 1.0);
        let hole_price = pr * (0.15 + 0.55 * permanence) * (1.0 - 0.6 / (1.0 + remaining * 0.02));
        score += hole_price;
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let refund = (pr - next_item_size as f64).min(pr);
            score -= refund * 0.35 * (1.0 - progress);
        }
    }

    // GEN-13: two-step chain refinement
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 >= 0.2 * cap {
            score -= 22.0 * (1.0 - 0.5 * progress);
        } else if rem2 > 0 && (rem2 as f64) < 0.08 * cap {
            score += 14.0 * (1.0 - rem2 as f64 / (0.08 * cap));
        }
    }

    // GEN-13: fresh-bin gate tightened
    if fresh && fitting_bins_count >= 2 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < 0.25 * cap {
            score += 70.0 * (1.0 - 0.5 * progress);
        }
    }

    // GEN-13: triple-chain lookahead
    if !fresh && next_item_size > 0 {
        let pair_sum = item_size.saturating_add(next_item_size);
        if post_residual == pair_sum {
            score -= 110.0 * (1.0 - 0.5 * progress);
        }
        let rem3 = bin_residual.saturating_sub(pair_sum);
        if rem3 > 0 && rem3 <= 100 && rem3 >= next_item_size / 2 {
            score -= 35.0 * (1.0 - progress);
        }
    }

    // GEN-17 mutation: near-full bin bonus — a bin that lands within 6 units
    // of capacity is effectively closed; reward driving it to completion,
    // scaled by progress so late-stream sealing is prioritized.
    if !fresh && pr <= 6.0 {
        score -= (6.0 - pr) * 8.0 * (0.5 + progress);
    }

    // GEN-17 mutation: dead-space budget shaping — penalize residuals smaller
    // than the current item (unfillable by it) and near-miss chain offsets.
    if !fresh && pr > 0.0 && pr < cap {
        if (pr as u32) < item_size && progress < 0.9 {
            score += (1.0 - progress) * 30.0 * (pr / cap);
        }
        if nx > 0.0 && (pr - nx).abs() < 3.0 && pr != nx {
            score += 12.0 * (1.0 - progress);
        }
    }

    // GEN-17 mutation: relative tightness bonus when several bins fit —
    // combine fine-grained residual ranking with the mean-residual anchor.
    if fitting_bins_count >= 2 && !fresh {
        let rel = (pr / mean_residual.max(1.0)).min(2.0);
        score += rel * 6.0;
        if pr < 0.15 * cap {
            score -= 30.0 * (1.0 - pr / (0.15 * cap));
        }
    }

    // GEN-17 mutation: compaction-aware fresh gate — when a fresh bin would
    // be opened while a fitting bin exists, price the permanent waste of the
    // chosen existing bin's residual against the new bin's guaranteed waste
    // (cap - item). Prefer the option with lower expected dead space.
    if fresh && fitting_bins_count > 0 {
        let new_bin_waste = (cap - it).max(0.0);
        let best_existing_waste = bin_residual.saturating_sub(item_size) as f64;
        let diff = best_existing_waste - new_bin_waste;
        if diff > 0.0 {
            score -= (12.0 + 0.25 * diff) * (1.0 - 0.5 * progress);
        } else {
            score += (-diff) * 0.2 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream processed (dynamic time horizon).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative tightness of the fit.
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    let residual_frac = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits strongly (wasted space is the enemy).
    score -= 40.0 * fit_ratio * (1.0 - residual_frac);

    // Non-linear penalty on post residual: dead space below the smallest
    // possible item (1..100 range, assume small items exist) is worthless.
    if post_residual < 10 {
        score -= 25.0; // near-perfect packing bonus
    } else if post_residual > 50 {
        // Large leftover is only OK if future items can use it.
        score += 10.0 * residual_frac;
    }

    // Lookahead coupling: if the next item fits the post residual exactly-ish,
    // this placement is excellent; if next item is large and post residual
    // becomes useless, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains nicely into this bin.
            let chain_tight = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - chain_tight / bin_capacity as f64);
        } else if post_residual > 0 && next_item_size > post_residual {
            // Next item cannot use the leftover; leftover is dead unless tiny.
            if post_residual >= 1 && post_residual < 10 {
                score += 2.0; // fine, it was already dead
            } else {
                score += 6.0 * residual_frac;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoids opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): penalize opening new bins when decent
    // fits exist, but allow it when mean residual across open bins is low
    // (open bins are nearly full) or many bins are already open and fragmented.
    if bin_residual == bin_capacity {
        let base_penalty = 15.0 + 10.0 * (1.0 - t);
        score += base_penalty;
        // If open bins have little room on average, a new bin is reasonable.
        let mean_frac = mean_residual / bin_capacity as f64;
        score -= 20.0 * (1.0 - mean_frac).min(1.0);
        // Late in the stream, prefer consolidating into existing bins.
        score += 8.0 * t;
    }

    // Mild pressure to use bins with more room when many bins are open
    // (reduce fragmentation by filling emptier bins first).
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Global state coupling: with many open bins, discourage spreading.
    if open_bins_count > 8 {
        if bin_residual != bin_capacity {
            score -= 2.0;
        } else {
            score += 4.0;
        }
    }

    score
}

