    // GEN-11: two-step chain refinement — prefer placements where the residual
    // after the next item lands in the "reusable band" (>= 20% of capacity).
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 >= 0.2 * cap {
            score -= 22.0 * (1.0 - 0.5 * progress);
        } else if rem2 > 0 && (rem2 as f64) < 0.08 * cap {
            score += 14.0 * (1.0 - rem2 as f64 / (0.08 * cap));
        }
    }

    // GEN-11: fresh-bin gate tightened — when several bins fit with modest
    // waste, opening a new bin should be clearly discouraged.
    if fresh && fitting_bins_count >= 2 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < 0.25 * cap {
            score += 70.0 * (1.0 - 0.5 * progress);
        }
    }

    // GEN-17 mutation A: harmonic hole pricing — replace the flat recoverable
    // ratio with a sharper harmonic curve so near-miss holes (just below the
    // next item) are priced more aggressively, while large reusable holes
    // are priced more gently. This targets the diagnosed dead-space weakness.
    if !fresh && post_residual > 0 && next_item_size > 0 {
        let hole = pr;
        if hole < nx {
            let miss = nx - hole;
            score += miss * miss / (nx.max(1.0)) * (1.2 + 1.5 * progress);
        }
    }

    // GEN-17 mutation B: waste-anticipation gate for fresh bins — compare the
    // immediate waste of opening a new bin against the *committed* waste of
    // stuffing the best existing bin, weighted by how many future items could
    // still use the leftover space. Open early when the leftover in the
    // existing bin is likely reusable; stuff the bin when the leftover is
    // likely stranded.
    if fresh && fitting_bins_count > 0 {
        let waste_existing = bin_residual.saturating_sub(item_size) as f64;
        let est_item = (cap - mean_residual).max(1.0);
        let reuse_prob = (waste_existing / est_item).min(1.5) / 1.5;
        let committed_cost = waste_existing * (1.0 - reuse_prob);
        let open_cost = cap * 0.02 * (1.0 - progress);
        if committed_cost > open_cost + 0.15 * cap {
            score += 55.0;
        } else if committed_cost < open_cost * 0.5 {
            score -= 35.0 * (1.0 - 0.5 * progress);
        }
    }

    // GEN-17 mutation C: residual-band shaping — reward placements whose
    // post-residual falls into a "harvestable" band that matches a plausible
    // future item size (multiples of the estimated item footprint), and
    // penalize residuals that sit in a dead zone just below such a multiple.
    if !fresh && post_residual > 0 {
        let est_item = (cap - mean_residual).max(1.0);
        let k = (pr / est_item).floor().max(1.0);
        let gap_to_multiple = pr - k * est_item;
        let gap_up = (k + 1.0) * est_item - pr;
        let closer = gap_to_multiple.min(gap_up);
        if closer / est_item < 0.12 {
            score -= 20.0 * (1.0 - closer / (0.12 * est_item)) * (1.0 - 0.5 * progress);
        } else if closer / est_item > 0.55 {
            score += 10.0 * (closer / est_item - 0.55) * (1.0 - progress);
        }
    }

    // GEN-17 mutation D: endgame squeeze — in the final stretch, residual
    // space can never be reused by a full future stream, so weight the raw
    // post-residual much more heavily and reward stuffing bins to the brim.
    if progress > 0.9 {
        let remaining = ((total_items - step_index) as f64).max(1.0);
        let urgency = (1.0 - remaining / ((total_items * 0.1) as f64).max(1.0)).clamp(0.0, 1.0);
        score += pr * 0.25 * urgency;
        if !fresh && pr <= 12.0 {
            score -= (12.0 - pr) * 4.0 * urgency;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in stream: mildly penalize large residuals (keep bins flexible).
    // Late in stream: strongly reward small residuals (tight packing matters).
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    score -= poly * 60.0 * (1.0 - progress);
    score += poly * 25.0 * progress;

    // Smooth interaction: residual^2 scaled by progress favors tight fits later.
    score += (pr_norm * pr_norm) * 15.0 * progress;

    // Reward filling the bin nearly completely, weighted by progress.
    let fill = item_size as f64 / cap;
    score -= fill * fill * 20.0 * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening new bins when many bins exist and progress is high.
    if bin_residual == bin_capacity {
        score += 12.0 + 18.0 * progress + (open_bins_count as f64).sqrt() * 3.0;
    }

    // Lookahead: if next item fits post_residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
