            score -= 10.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 5.0 * ((nxt - pr) / cap);
        }
    }

    // Mean residual coupling: prefer bins deviating below mean (consolidate space).
    score += 0.4 * (pr - mean_residual) * (1.0 - progress);

    score
}

