    }

    // GEN-18 mutation: near-full bin bonus — squeeze the last units of waste out
    if !fresh && pr <= 6.0 {
        score -= (6.0 - pr as f64) * 9.0 * (0.5 + progress);
    }

    // GEN-18 mutation: among several fitting bins, reward tightness relative to mean
    if fitting_bins_count >= 2 && !fresh {
        let rel = (pr / mean_residual.max(1.0)).min(2.0);
        score += rel * 6.0;
        if pr < 0.15 * cap {
            score -= 30.0 * (1.0 - pr / (0.15 * cap));
        }
    }

    // GEN-18 mutation: dead-space shaping near item boundary — penalize holes
    // just below the item size that strand space, discounted late
    if !fresh && pr > 0.0 && pr < cap {
        if (pr as f64) < it && progress < 0.9 {
            score += (1.0 - progress) * 30.0 * (pr / cap);
        }
        if nx > 0.0 && (pr - nx).abs() < 3.0 && pr != nx {
            score += 12.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: absolute reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover space by residue classes
    // mod 10 and mod 20. Residuals divisible by 10 are "harmonic" (likely to be
    // refilled by future items in a 1..100 integer stream); odd or prime-ish
    // leftovers are dead space.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        0.0
    } else if pr % 20 == 0 {
        -18.0
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr % 2 == 0 {
        -2.0
    } else {
        4.0 // odd residual: penalize
    };
    score += class_bonus;

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0;
        } else if next_item_size <= pr {
            // next item fits: residual after that placement, harmonic-weighted
            let pr2 = pr - next_item_size;
            let w = if pr2 % 10 == 0 { 1.5 } else if pr2 % 5 == 0 { 1.0 } else { 0.5 };
            score -= w * (next_item_size as f64);
        } else {
            // next item cannot use this leftover: penalize harmonic-bad leftovers more
            if pr % 10 != 0 && pr % 5 != 0 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when this bin would leave a badly
    // non-harmonic residual and many open bins already exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_leftover = (pr % 10 != 0) as f64 * 20.0 + (pr % 5 != 0) as f64 * 10.0;
        // base penalty keeps new bins from opening casually
        score += 60.0 + 40.0 * progress - bad_leftover;
        if next_item_size > 0 && next_item_size > pr {
            score -= 30.0; // fresh bin guarantees the next item a home
        }
    }

    // Prefer fuller bins: couple with mean residual across open bins.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Slight preference to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

