pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: hard penalty for small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 18.0;
    }

    // Reward tight fits strongly (small post_residual relative to item).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio;

    // Reward bins that can also fit the lookahead item (chaining placements).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0;
    }

    // Last-chance pressure: strongly favor the only fitting bin to avoid opening new ones.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer closing them out (large fill).
    let progress = step_index as f64 / total_items as f64;
    let bin_pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    score += 0.05 * bin_pressure * (1.0 - fill_ratio);

    // Prefer bins below mean residual (more filled) to consolidate.
    let dev = mean_residual - post_residual as f64;
    score -= 0.15 * dev;

    // New-bin candidate: neutral-ish baseline, penalized unless item is huge relative to residuals.
    if bin_residual == bin_capacity {
        let avg_gap = mean_residual.max(1.0);
        let open_penalty = 20.0 * open_bins_count as f64;
        score += open_penalty - 0.3 * avg_gap;
        if item_size >= 60 {
            score -= 25.0;
        }
    }

    score
}

