    if fresh && fitting_bins_count > 0 {
        let remaining_frac = ((total_items - step_index) as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
        let min_existing_waste = bin_residual.saturating_sub(item_size) as f64;
        if min_existing_waste < 0.35 * cap {
            score += 85.0 * (0.5 + 0.5 * remaining_frac);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits: post_residual close to 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post_residual, this is a perfect chain — heavily reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // Next item fits; reward proportionally to how snug the chain is.
            let chain_waste = (post_residual - next_item_size) as f64;
            if chain_waste <= 10.0 {
                score -= 300.0 - chain_waste * 10.0;
            } else {
                score -= (300.0 - chain_waste * 10.0).max(20.0);
            }
        } else {
            // Next item will NOT fit here: penalize small dead space that
            // likely becomes unusable (worse than a large usable residual).
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += (15.0 - gap) * 8.0;
            }
        }
    }

    // Compare against mean residual across open bins: prefer bins whose
    // residual is tighter than average (consolidate fill).
    let mean_gap = mean_residual - post_residual as f64;
    score -= mean_gap * 2.0;

    // Penalize leaving a residual far below the mean (fragmenting space).
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when the item is large and open
    // bins would leave big awkward residuals.
    if bin_residual == bin_capacity {
        let awkwardness = if next_item_size > 0 && post_residual > 0
            && (post_residual as f64) < next_item_size as f64 { 1.0 } else { 0.0 };
        score += 150.0 + awkwardness * 100.0;
        // Early in the stream, opening bins is cheaper (more future items
        // to fill them); later, prefer squeezing into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 120.0;
        // If item is large relative to capacity, a fresh bin is natural.
        score -= (item_size as f64 / bin_capacity as f64) * 100.0;
    }

    // Mild penalty for very large leftover residual that is unlikely to be
    // filled by typical items.
    if post_residual > 60 {
        score += (post_residual - 60) as f64 * 1.5;
    }

    score
}

