        }
    }

    // GEN-13: two-step chain refinement
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 >= 0.2 * cap {
            score -= 22.0 * (1.0 - 0.5 * progress);
        } else if rem2 > 0 && (rem2 as f64) < 0.08 * cap {
            score += 14.0 * (1.0 - rem2 as f64 / (0.08 * cap));
        }
    }

    // GEN-13: fresh-bin gate tightened
    if fresh && fitting_bins_count >= 2 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < 0.25 * cap {
            score += 70.0 * (1.0 - 0.5 * progress);
        }
    }

    // GEN-13: triple-chain lookahead
    if !fresh && next_item_size > 0 {
        let pair_sum = item_size.saturating_add(next_item_size);
        if post_residual == pair_sum {
            score -= 110.0 * (1.0 - 0.5 * progress);
        }
        let rem3 = bin_residual.saturating_sub(pair_sum);
        if rem3 > 0 && rem3 <= 100 && rem3 >= next_item_size / 2 {
            score -= 35.0 * (1.0 - progress);
        }
    }

    // GEN-23 mutation A: tiling-fit reward — post-residual close to an integer
    // multiple of the estimated future item size means future items can tile
    // the remaining space with minimal scrap; combined with lookahead so that
    // bins whose remainder after the next item still tiles get extra reward.
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let est = mean_residual.max(1.0);
        let k = (pr / est).round().max(1.0);
        let tiling_err = ((pr - k * est).abs()) / est;
        score += tiling_err * 14.0 * (0.5 + 0.5 * progress);
        if tiling_err < 0.08 {
            score -= 22.0 * k.min(3.0) * (1.0 - 0.5 * progress);
            if next_item_size > 0 && post_residual >= next_item_size {
                let rem2 = post_residual - next_item_size;
                if rem2 as f64 >= est * 0.8 {
                    score -= 18.0;
                }
            }
        }
    }

    // GEN-23 mutation B: residual-band matching against mean residual —
    // residual that is a leftover modulo the mean item size is scrap that
    // future items of typical size cannot absorb; penalize proportionally.
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let scrap = (pr % mean_residual) / mean_residual;
        score += scrap * 24.0 * (0.4 + 0.6 * progress);
    }

    // GEN-23 mutation C: near-full squeeze — when only a few units remain,
    // aggressively reward the tightest possible placement to eliminate scrap.
    if !fresh && pr <= 6.0 {
        score -= (6.0 - pr) * 10.0 * (0.5 + progress);
    }

    // GEN-23 mutation D: fresh-bin opening gate — only open a new bin when the
    // best existing fit would strand more than the estimated next-item demand;
    // otherwise existing bins should absorb the item.
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < nx * 0.6 {
            score += 60.0 * (1.0 - 0.3 * progress);
        }
        if best_waste > nx * 1.4 && best_waste > 0.35 * cap {
            score -= 40.0 * (1.0 - progress);
        }
    }

    // GEN-23 mutation E: lookahead chain continuation — reward bins where the
    // remainder after the next item is still at least half the next item, so
    // a third placement is plausible; penalize residuals just below the next
    // item (near-miss dead space) with progress-weighted severity.
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 >= nx * 0.5 {
            score -= 20.0 * (1.0 - 0.4 * progress);
        } else if rem2 > 0 {
            score += (nx * 0.5 - rem2 as f64) * 2.0 * (0.5 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
