    // next item would otherwise leave a tiny stranded remainder
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && (rem2 as f64) < nx * 0.25 && rem2 < 20 {
            score += (20.0 - rem2 as f64) * 3.0 * (0.5 + progress);
        } else if rem2 >= next_item_size {
            score -= 28.0 * (1.0 - 0.4 * progress);
        }
    }

    // GEN-22: fresh-bin opening gate — only open when the best existing fit
    // would strand more than the estimated next-item demand
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < nx as f64 * 0.6 {
            score += 55.0 * (1.0 - 0.3 * progress);
        }
    }

    // GEN-24 mutation: dual-chain waste budget — combine the two-step remainder
    // with the item+next pair so placements leaving a residual exactly equal to
    // a plausible future item are strongly preferred over mid-band scrap.
    if !fresh && next_item_size > 0 && post_residual > 0 {
        let rem2 = post_residual.saturating_sub(next_item_size);
        if rem2 > 0 && rem2 <= next_item_size && (rem2 as f64) < mean_residual.max(1.0) * 1.2 {
            score -= (next_item_size - rem2) as f64 * 2.2 * (1.0 - 0.4 * progress);
        }
    }

    // GEN-24 mutation: compaction pressure — scale residual penalty by how
    // close the bin is to full, so near-complete bins absorb the last items.
    if !fresh && post_residual > 0 {
        let used_frac = 1.0 - bin_residual as f64 / cap;
        score += pr * 0.35 * used_frac * (0.5 + 0.5 * progress);
    }

    // GEN-24 mutation: fresh-bin final gate — never open a new bin late when
    // any existing bin fits with less than half-capacity waste.
    if fresh && fitting_bins_count > 0 && progress > 0.6 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < 0.5 * cap {
            score += 60.0 * (progress - 0.6) * 2.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
