        }
    }

    // GEN-25 mutation: continuous dead-space gradient — replace the hard
    // near-full step with a smooth convex penalty over the whole residual
    // range, so mid-band residuals are graded rather than binned.
    if !fresh && pr > 0.0 {
        let frac = pr / cap;
        score += frac * frac * 55.0 * (0.6 + 0.4 * progress);
        if frac < 0.06 {
            score -= (0.06 - frac) * 260.0;
        }
    }

    // GEN-25 mutation: two-item lookahead capacity check — prefer bins that
    // can still host the next item AND a plausible follow-up (mean-sized).
    if !fresh && nx > 0.0 && pr >= nx {
        let rem2 = pr - nx;
        let est = mean_residual.max(1.0).min(0.4 * cap);
        if rem2 >= est * 0.8 {
            score -= 26.0 * (1.0 - 0.4 * progress);
        } else if rem2 > 0.0 && rem2 < est * 0.4 {
            score += 20.0 * (1.0 - rem2 / (est * 0.4)) * (0.5 + progress);
        }
    }

    // GEN-25 mutation: fresh-bin decision sharpened — open a new bin only when
    // the best existing fit would strand more than the next item can consume,
    // scaled by how much of the stream remains.
    if fresh && fitting_bins_count > 0 {
        let stranded = bin_residual.saturating_sub(item_size) as f64;
        let demand = nx.max(est_stream_hint(mean_residual, cap));
        if stranded > demand * 1.15 {
            score -= 70.0 * (1.0 - 0.5 * progress);
        } else if stranded < demand * 0.5 {
            score += 65.0 * (1.0 - 0.3 * progress);
        }
    }

    // GEN-25 mutation: anti-fragmentation — penalize bins left with residuals
    // in the "useless band" that no plausible item (item or next) can fill.
    if !fresh && post_residual > 0 {
        let usable = (pr >= it as f64 * 0.999) || (nx > 0.0 && pr >= nx);
        if !usable {
            let band_center = 0.35 * cap;
            let band = 1.0 - ((pr - band_center).abs() / band_center).min(1.0);
            score += band * 34.0 * (0.4 + 0.6 * progress);
        }
    }

    score
}

#[inline]
fn est_stream_hint(mean_residual: f64, cap: f64) -> f64 {
    // Estimated typical item size implied by observed residual pressure.
    (cap - mean_residual).clamp(1.0, cap)
}

