        let dead = pr / cap;
        if dead < 0.1 {
            score -= (0.1 - dead) * 220.0 * (0.6 + 0.4 * progress);
        }
    }

    // NEW GEN-25 mutation: two-item chain exactness — if placing here leaves a
    // residual exactly equal to the sum of the next item and the estimated
    // mean item size, reward it as a perfect 3-chain.
    if !fresh && nx > 0.0 && mean_residual > 1.0 {
        let triple = nx + mean_residual;
        if (pr - triple).abs() < 1.5 {
            score -= 55.0 * (1.0 - 0.5 * progress);
        }
    }

    score
}

