            let stranded = (next_item_size - post_residual) as f64;
            score += stranded * 1.8 * horizon * (0.4 + 0.6 * (1.0 - progress));
        } else {
            let rem2 = post_residual - next_item_size;
            if rem2 == 0 {
                score -= 90.0 * horizon;
            } else if rem2 <= item_size {
                score -= 45.0 * horizon * (1.0 - rem2 as f64 / (item_size.max(1) as f64));
            }
        }
    }

    // GEN-26 mutation: capacity-aware fresh-bin arbitration — open a new bin
    // only when the best existing fit strands more than a progress-scaled
    // fraction of capacity AND the item is not tiny (tiny items tile well).
    if fresh && fitting_bins_count > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        let gate = cap * (0.45 - 0.25 * progress) + it * 0.3;
        if best_waste < gate {
            score += 65.0 + 0.25 * (gate - best_waste);
        } else if best_waste > gate {
            score -= 40.0 * (best_waste - gate) / cap;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: reward tight fits with a strongly convex penalty on leftover space.
    let mut score = (post / cap).powf(2.0 + 2.0 * progress) * cap;

    // Cubic coupling: dead space becomes increasingly costly as the stream progresses.
    score += (post / cap).powi(3) * cap * (0.5 + progress);

    // Lookahead: reward bins whose post-residual exactly accommodates the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let gap = (post - nxt) / cap;
            score -= (1.0 - gap).powi(2) * 12.0 * (1.0 - progress);
        } else {
            // Post-residual too small for the lookahead: mild penalty scaled by waste.
            score += (nxt - post) / cap * 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit this item.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress) + 10.0 * progress;
    }

    // Many open bins: encourage consolidation by penalizing bins deviating from mean residual.
    let dev = (post - mean_residual) / cap;
    score += dev * dev * cap * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate: only attractive early in the stream or when the fit is poor.
    if bin_residual == bin_capacity {
        let early_bonus = 25.0 * (1.0 - progress) * (1.0 - progress);
        score = cap - early_bonus + post * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0;
        }
    }

    score
}

