        let recoverable = if pr >= est_item * 0.5 { 1.0 } else { pr / (est_item * 0.5) };
        let permanence = (1.0 - recoverable).clamp(0.0, 1.0);
        let hole_price = pr * (0.15 + 0.55 * permanence) * (1.0 - 0.6 / (1.0 + remaining * 0.02));
        score += hole_price;
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let refund = (pr - next_item_size as f64).min(pr);
            score -= refund * 0.35 * (1.0 - progress);
        }
    }

    // GEN-13: two-step chain refinement
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 >= 0.2 * cap {
            score -= 22.0 * (1.0 - 0.5 * progress);
        } else if rem2 > 0 && (rem2 as f64) < 0.08 * cap {
            score += 14.0 * (1.0 - rem2 as f64 / (0.08 * cap));
        }
    }

    // GEN-13: fresh-bin gate tightened
    if fresh && fitting_bins_count >= 2 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < 0.25 * cap {
            score += 70.0 * (1.0 - 0.5 * progress);
        }
    }

    // GEN-13: triple-chain lookahead
    if !fresh && next_item_size > 0 {
        let pair_sum = item_size.saturating_add(next_item_size);
        if post_residual == pair_sum {
            score -= 110.0 * (1.0 - 0.5 * progress);
        }
    }

    // GEN-20: near-full bin bonus — squeeze the last units of waste out
    if !fresh && pr <= 6.0 {
        score -= (6.0 - pr) * 9.0 * (0.5 + progress);
    }

    // GEN-20: among several fitting bins, reward tightness relative to mean
    if fitting_bins_count >= 2 && !fresh {
        let rel = (pr / mean_residual.max(1.0)).min(2.0);
        score += rel * 6.0;
        if pr < 0.15 * cap {
            score -= 30.0 * (1.0 - pr / (0.15 * cap));
        }
    }

    // GEN-20: exact next-item fit with large next item — extra reward
    if !fresh && next_item_size > 0 && post_residual == next_item_size && nx > 0.4 * cap {
        score -= 40.0 * (1.0 - progress);
    }

    // GEN-22: reward placements whose post-residual tiles well with the mean
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let est = mean_residual.max(1.0);
        let k = (pr / est).round().max(1.0);
        let tiling_err = ((pr - k * est).abs()) / est;
        score += tiling_err * 16.0 * (0.5 + 0.5 * progress);
        if tiling_err < 0.1 {
            score -= 20.0 * k.min(3.0) * (1.0 - 0.5 * progress);
        }
    }

    // GEN-26 mutation: residual-band matching against mean residual — minimize scrap
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let scrap = (pr % mean_residual) / mean_residual;
        score += scrap * 22.0 * (0.4 + 0.6 * progress);
    }

    // GEN-26 mutation: lookahead trade-off — when the next item would leave a
    // tiny remainder, prefer bins that keep enough room for a follow-up item.
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && (rem2 as f64) < nx * 0.25 && rem2 < 20 {
            score += (20.0 - rem2 as f64) * 3.0 * (0.5 + progress);
        } else if rem2 >= next_item_size {
            score -= 28.0 * (1.0 - 0.4 * progress);
        }
    }

    // GEN-26 mutation: near-miss calibration — prefer residual just under next item
    if !fresh && nx > 0.0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        score += 18.0 * (1.0 - miss / nx.max(1.0)) * (1.0 - progress);
    }

    // GEN-26 mutation: fresh-bin discount when residual would strand a large block late
    if fresh && fitting_bins_count > 0 && progress > 0.5 {
        let stranded = bin_residual.saturating_sub(item_size) as f64;
        if stranded > 0.55 * cap {
            score -= 55.0 * (progress - 0.5) * 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into coarse classes.
    // Classes: 0 (perfect fit), 1..=9 (tight), 10..=24 (medium), 25..=49 (loose), >=50 (half-empty).
    let post = post_residual as i64;
    let class = if post == 0 { 0 }
        else if post <= 9 { 1 }
        else if post <= 24 { 2 }
        else if post <= 49 { 3 }
        else { 4 };
    score += match class {
        0 => -60.0,               // perfect fit: strong reward
        1 => -25.0,               // near-perfect
        2 => 5.0,                 // medium dead space
        3 => 20.0,                // loose
        _ => 35.0,                // half-empty: heavy penalty
    };

    // Integer-division thresholds on post_residual: divisible leftovers pair well
    // with common small item classes (multiples of 10).
    if post > 0 && post % 10 == 0 {
        score -= 12.0;            // leftover is a "harmonic" multiple of 10
    }
    if post > 0 && post % 5 == 0 && post % 10 != 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 18.0 - (slack as f64).min(20.0); // reward chained fit, less if sloppy
        }
        // Penalize if post_residual is just barely too small for next item (teasing fit).
        if next_item_size > post_residual && next_item_size - post_residual <= 5 && post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && post_residual <= 30 {
        score -= 15.0;
    } else if fitting_bins_count == 1 {
        score += 10.0; // bad fit in only fitting bin; consider fresh bin
    }

    // New-bin candidate handling: an empty bin has post_residual = capacity - item_size.
    // Prefer keeping it closed unless open bins would leave >= 40 dead space.
    if bin_residual == bin_capacity {
        // Base neutral-ish score: fresh bin wastes the most potential.
        score += 15.0;
        // But if the item is huge, a fresh bin is fine.
        if item_size >= 60 {
            score -= 10.0;
        }
        // Early in stream, opening bins is cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Global pressure: many open bins with high mean residual -> favor filling existing bins.
    if open_bins_count > 2 && mean_residual > 30.0 {
        score -= 8.0;
    }

    // Modulo harmony between item and capacity: items dividing capacity pack cleanly.
    if bin_capacity % item_size == 0 {
        score -= 6.0;
    }

    score
}

