    // Penalize placements proportional to the exact stranded waste, but only
    // when that waste is below the next item's size (unrecoverable) and
    // weighted by how much of the stream remains to be packed.
    if !fresh && post_residual > 0 && next_item_size > 0 {
        let stranded = (next_item_size - post_residual.min(next_item_size)) as f64;
        if stranded > 0.0 {
            let remaining_frac = 1.0 - progress;
            score += stranded * stranded * 0.09 * remaining_frac;
        }
    }

    // GEN-26 mutation: dual-fit bonus — reward bins whose post-residual can
    // host the next item AND whose current residual is closest to item+next
    // (perfect two-item tiling), sharpened when few bins remain useful.
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 == 0 {
            score -= 95.0 * (0.6 + 0.4 * (fitting_bins_count.min(4) as f64 / 4.0));
        } else if rem2 <= 3 {
            score -= 30.0 * (1.0 - progress);
        }
    }

    // GEN-26 mutation: fresh-bin gate — compare the waste of the best existing
    // bin against the fresh-bin's own waste after placement; open a new bin
    // only when it strictly dominates, scaled by stream progress.
    if fresh && fitting_bins_count > 0 {
        let fresh_waste = (bin_capacity - item_size) as f64;
        let existing_waste_floor = (bin_residual.saturating_sub(item_size)) as f64;
        if fresh_waste > existing_waste_floor + 0.15 * cap {
            score += 40.0 + 60.0 * (1.0 - progress) * ((fresh_waste - existing_waste_floor) / cap);
        }
    }

    // GEN-26 mutation: compaction harmonic — nonlinear reward for very small
    // post-residuals, pushing the final units of slack into existing bins
    // rather than letting them accumulate across many partially-filled bins.
    if !fresh && post_residual > 0 {
        score -= 220.0 / (pr + 2.0) * (0.35 + 0.65 * progress);
    }

    score
}

