            score += 55.0 * (1.0 - 0.3 * progress);
        }
    }

    // GEN-27 mutation: combine fine-grained fitting with lookahead —
    // post-residual that exactly hosts the next item AND whose remainder
    // still fits the current item again (multi-cycle tiling) gets a bonus.
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 >= item_size && (rem2 % item_size.max(1)) <= 2 {
            score -= 26.0 * (1.0 - 0.4 * progress);
        }
        // penalize residuals that fit next item but strand a gap just below
        // the current item size (dead space the stream can't reuse)
        if rem2 > 0 && rem2 < item_size && rem2 < 12 {
            score += (12 - rem2) as f64 * 4.0 * (0.4 + 0.6 * progress);
        }
    }

    // GEN-27 mutation: dead-space ratio shaping — convert residual waste into
    // a smooth quadratic penalty scaled by stream position, so mid-stream
    // placements strongly prefer low post-residuals.
    if !fresh && post_residual > 0 {
        let waste_frac = pr / cap;
        score += waste_frac * waste_frac * 55.0 * (0.35 + 0.65 * progress);
    }

    // GEN-27 mutation: fresh-bin decision — open a new bin only when the best
    // existing fit wastes more than a fraction of the next item's demand,
    // tightened early when few bins are open.
    if fresh && fitting_bins_count > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        let gate = if progress < 0.4 { 0.35 * cap } else { 0.2 * cap };
        if best_waste < gate {
            score += 65.0 * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && best_waste > 0.0 && best_waste < nx as f64 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0; // chain: next item fills this bin exactly
    }
    // Near-perfect match: next item fits with small slack
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 400.0 * (1.0 - slack / 50.0).max(0.0);
    }
    // Next item cannot use the residual: penalize proportionally to wasted capacity
    else if next_item_size > 0 && next_item_size > post_residual {
        score += 60.0 + (post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // Penalize tiny dead space (<10) that nothing can use
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Tight fits (small post_residual relative to item) are good
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 80.0 * tightness;

    // Prefer filling bins below mean residual (balancing toward fuller bins)
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Early in stream: keep flexibility; late in stream: consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 50.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: mild penalty so open bins are preferred unless lookahead says otherwise
    if bin_residual == bin_capacity {
        score += 30.0;
        // If next item matches a fresh bin remainder perfectly, opening is attractive
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 900.0;
        }
    }

    score
}

