        score += dead_ratio * 40.0 * remaining_frac * (1.0 - small_leftover * 0.5);
    }

    // NEW: complementarity bonus — prefer bins whose post-residual equals the
    // complement of the next item w.r.t. common item sizes (tile pairing).
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 >= 1 && rem2 <= 50 && (rem2 as f64 - it).abs() <= 2.0 {
            score -= 25.0 * (1.0 - 0.3 * progress);
        }
    }

    // NEW: fine-grained tie-break among many fitting bins — reward the
    // minimal absolute residual more aggressively when options abound.
    if !fresh && fitting_bins_count >= 3 && pr > 0.0 {
        score += (pr as f64).ln() * 8.0 * (0.3 + 0.7 * progress);
    }

    score
}

