    // the bin that stays unfilled after placement, weighted by how much of the
    // stream remains to be packed (early waste is more recoverable).
    if !fresh && post_residual > 0 {
        let remaining_frac = 1.0 - progress;
        let dead_ratio = pr / cap;
        score += dead_ratio * 65.0 * (0.35 + 0.65 * remaining_frac);
    }

