    // near-divisors of plausible future item sizes, tiling the bin fully.
    if !fresh && post_residual > 0 && nx > 0.0 {
        let div = (nx / pr.max(1.0)).floor().max(1.0);
        let leftover = (nx - div * pr) as f64;
        if leftover < 6.0 {
            score -= (6.0 - leftover) * 5.0 * (1.0 - 0.5 * progress);
        }
    }

    // GEN-27 mutation: residual ladder — bonus when post-residual matches a
    // common complement of small items (keeps slivers packable).
    if !fresh && post_residual > 0 {
        let ladder = [1u32, 2, 3, 4, 5, 10, 20, 25, 50];
        if ladder.contains(&post_residual) {
            score -= 24.0 * (1.0 - 0.4 * progress);
        }
    }

    // GEN-27 mutation: fresh-bin gate — compare stranded waste against the
    // expected future demand; open only when existing bins would strand more.
    if fresh && fitting_bins_count > 0 {
        let stranded = bin_residual.saturating_sub(item_size) as f64;
        let demand = nx.max(mean_residual) * 0.5;
        if stranded < demand {
            score += 40.0 * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    score
}

