    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling: post_residual interacts with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 40.0
                 + norm_pr * progress * 20.0;
    score += coupling;

    // Penalize residual that fails to fit the lookahead item (dead space)
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * (0.5 + progress);
    } else if next_item_size > 0 {
        // Reward bins that can still host the next item
        score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Slight preference for tighter bins as bins accumulate
    score += (open_bins_count as f64).ln() * norm_pr * 5.0;

    // Mild deviation from mean residual discourages fragmentation
    score += ((pr - mean_residual) / cap).abs() * 3.0;

    // New-bin candidate: neutral-ish baseline with smooth adjustment
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.2 * progress) + (open_bins_count as f64) * 0.5;
    }

    score
}

