        if pr < 0.15 * cap {
            score -= 30.0 * (1.0 - pr / (0.15 * cap));
        }
    }

    // GEN-20: dead-space shaping near item boundary
    if !fresh && pr > 0.0 && pr < cap {
        if pr < it && progress < 0.9 {
            score += (1.0 - progress) * 30.0 * (pr / cap);
        }
        if nx > 0.0 && (pr - nx).abs() < 3.0 && pr != nx {
            score += 12.0 * (1.0 - progress);
        }
    }

    // GEN-20: exact next-item fit with large next item — extra reward
    if !fresh && next_item_size > 0 && post_residual == next_item_size && nx > 0.4 * cap {
        score -= 40.0 * (1.0 - progress);
    }

    // GEN-20: residual-band matching against mean residual — minimize scrap
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let scrap = (pr % mean_residual) / mean_residual;
        score += scrap * 22.0 * (0.4 + 0.6 * progress);
    }

    // GEN-20: near-miss calibration — prefer residual just under next item
    if !fresh && nx > 0.0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        let mid_band = dist_from_half < 0.15 * cap;
        if mid_band {
            score += 18.0 * (1.0 - miss / nx.max(1.0));
        }
    }

    // GEN-20: fresh-bin discount when residual would strand a large block late
    if fresh && fitting_bins_count > 0 && progress > 0.5 {
        let stranded = bin_residual.saturating_sub(item_size) as f64;
        if stranded > 0.55 * cap {
            score -= 55.0 * (progress - 0.5) * 2.0;
        }
    }

    // GEN-22: tiling-error shaping (reinforced direction)
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let est = mean_residual.max(1.0);
        let k = (pr / est).round().max(1.0);
        let tiling_err = ((pr - k * est).abs()) / est;
        score += tiling_err * 20.0 * (0.5 + 0.5 * progress);
        if tiling_err < 0.1 {
            score -= 24.0 * k.min(3.0) * (1.0 - 0.5 * progress);
        }
    }

    // GEN-22: lookahead trade-off — keep room for a follow-up item
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && (rem2 as f64) < nx * 0.25 && rem2 < 20 {
            score += (20.0 - rem2 as f64) * 3.0 * (0.5 + progress);
        } else if rem2 >= next_item_size {
            score -= 32.0 * (1.0 - 0.4 * progress);
        }
    }

    // GEN-22: fresh-bin opening gate
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < nx as f64 * 0.6 {
            score += 55.0 * (1.0 - 0.3 * progress);
        }
    }

    // GEN-28 mutation: two-item tiling of the post-residual — reward bins where
    // the residual after this item can be tiled by the next item plus the mean
    // observed item size with near-zero scrap, i.e. a full 2-deep chain plan.
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if mean_residual > 1.0 {
            let est = mean_residual.max(1.0);
            let k2 = (rem2 as f64 / est).round();
            if k2 >= 1.0 {
                let t2 = ((rem2 as f64 - k2 * est).abs()) / est;
                if t2 < 0.15 {
                    score -= 30.0 * k2.min(2.0) * (1.0 - 0.4 * progress);
                } else {
                    score += t2 * 14.0 * progress;
                }
            }
        }
        // exact two-chain: rem2 equals next item's own size (a second copy fits)
        if rem2 == next_item_size {
            score -= 65.0 * (1.0 - 0.3 * progress);
        }
    }

    // GEN-28 mutation: dead-space budget refinement — sharpen the permanence
    // pricing with a quadratic term so mid-band residuals are priced harder
    // when many bins are already open (consolidation over proliferation).
    if !fresh && post_residual > 0 {
        let est_item = (cap - mean_residual).max(1.0);
        let ratio = pr / est_item.max(1.0);
        if ratio < 1.0 {
            let frag_pressure = (1.0 - ratio) * (1.0 - ratio);
            score += frag_pressure * (10.0 + 0.35 * open_bins_count.min(50) as f64) * (0.6 + 0.4 * progress);
        }
    }

    // GEN-28 mutation: fresh-bin gate — compare the waste of opening a new bin
    // against the best existing-bin waste implied by the tiling estimate; open
    // only when the existing options strand clearly more space than a fresh bin
    // would leave after absorbing this item and the next one.
    if fresh && fitting_bins_count > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        let fresh_waste = (bin_capacity as f64 - it).max(0.0);
        let demand2 = nx + it;
        let existing_score_waste = if best_waste > fresh_waste + 0.15 * cap {
            // existing bins strand notably more — opening is attractive
            -40.0 * (1.0 - 0.5 * progress)
        } else {
            40.0 + 0.25 * (fresh_waste - best_waste).max(0.0)
        };
        score += existing_score_waste;
        if demand2 > bin_capacity as f64 && best_waste > 0.5 * cap {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting gap: bins whose residual falls into
    // "small" residue classes are nearly dead, penalize heavily.
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;

    // Modulo-10 harmonic class of post residual.
    let class = pr % 10;
    let dead_penalty = match class {
        0 => -8.0,               // perfect fill possible later
        1..=5 => 6.0,            // tiny unusable slivers
        6..=9 => 2.0,            // moderate
        _ => 0.0,
    };
    score += dead_penalty;

    // Integer-division thresholds: gaps below 10 are dead space.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Fractional capacity coupling: reward leaving room for common item
    // fractions (25, 50, 75) if the lookahead item can use it.
    if next_item_size > 0 && post_residual >= next_item_size {
        // lookahead fits exactly here -> strong bonus
        score -= 12.0 + (next_item_size as f64) * 0.15;
        if post_residual == next_item_size {
            score -= 20.0; // perfect two-item fill
        }
    } else if next_item_size > 0 {
        // lookahead cannot fit in the gap we leave -> mild penalty scaled
        // by how close the gap is to a harmonic fraction of capacity
        let frac = post_residual as f64 / cap;
        if (frac - 0.25).abs() < 0.02 || (frac - 0.5).abs() < 0.02 || (frac - 0.75).abs() < 0.02 {
            score += 4.0; // wasted a "clean" fraction
        }
        score += 3.0;
    }

    // Best-fit sharpening: prefer tight fits.
    score += (post_residual as f64) * 0.35;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity when
    // many bins fit; penalize proportional to open bins, but relax when
    // current fit is terrible (huge post residual) late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = if post_residual >= next_item_size { 0.0 } else { 1.0 };
        score += 15.0 + (open_bins_count as f64) * 2.5 - fit_quality * (20.0 + progress * 10.0);
        // early stream: prefer consolidating into open bins
        score += (1.0 - progress) * 10.0;
    }

    // Slight bias toward filling bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let nx = next_item_size as f64;
    let it = item_size as f64;
    let fresh = bin_residual == bin_capacity;
    let half = 0.5 * cap;

    // Perfect fit: strong reward, amplified early
    if post_residual == 0 {
        score -= 1250.0 + 100.0 * (1.0 - progress);
    }

    // Cubic dead-space penalty, softened late in stream
    score += pr.powi(3) / (cap * cap * cap) * 90.0 * (1.0 - 0.5 * progress);

    // Last-chance bin: strongly prefer it
    if fitting_bins_count == 1 && !fresh {
        score -= 350.0;
    }

    // Lookahead chain logic
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 580.0;
            if nx > 0.4 * cap {
                score -= 40.0 * (1.0 - progress);
            }
        } else if post_residual > next_item_size {
            let chain_left = post_residual - next_item_size;
            let chain_bonus = if chain_left <= item_size { 110.0 } else if chain_left <= next_item_size { 60.0 } else { 0.0 };
            score -= 60.0 * (pr / nx.max(1.0)).ln().max(0.0) + chain_bonus;
            let slack = pr - nx;
            if slack < 8.0 {
                score -= (8.0 - slack) * 12.0;
            }
            if chain_left > item_size && chain_left >= next_item_size {
                score -= 25.0;
            }
            // awkward small gap after next item
            let gap = chain_left;
            if gap > 0 && gap < 8 {
                score -= (8 - gap) as f64 * 7.0 * (0.5 + progress);
            }
        } else {
            score += (next_item_size - post_residual) as f64 * (0.7 + 0.5 * (1.0 - progress));
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 20.0 {
                score += miss * (2.5 + 3.0 * progress);
            }
        }
        if post_residual == item_size.saturating_add(next_item_size) {
            score -= 300.0 + 110.0 * (1.0 - 0.5 * progress);
        } else if (post_residual as u32) < item_size.saturating_add(next_item_size) && pr < 0.25 * cap {
            score += 60.0 + 0.5 * (0.25 * cap - pr);
        }
        // pair-sum lookahead on the bin's own residual
        let pair_sum = item_size.saturating_add(next_item_size);
        if bin_residual >= pair_sum {
            let pair_slack = bin_residual - pair_sum;
            if pair_slack <= 10 {
                score -= 70.0 - 4.0 * pair_slack as f64;
            }
        }
    }

    // Tightness vs mean, amplified by open bin count
    score += (pr - mean_residual) * (0.5 + 0.005 * open_bins_count.min(60) as f64);

    // Consolidation pressure
    score += (open_bins_count as f64).powi(2) * 0.004 + open_bins_count as f64 * 0.2;

    // Waste-ratio term
    let fill_fraction = it / cap;
    let hole_fraction = pr / cap;
    if hole_fraction > fill_fraction {
        score += (hole_fraction - fill_fraction) * 140.0;
    }

    // New-bin candidate logic
    if fresh {
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 280.0;
        } else if fitting_bins_count == 1 {
            let waste_if_stuffed = bin_residual.saturating_sub(item_size) as f64;
            score -= 130.0 + 0.7 * waste_if_stuffed;
        } else {
            let best_possible_waste = bin_residual.saturating_sub(item_size) as f64;
            if best_possible_waste > 0.4 * cap {
                score -= 90.0;
            }
            if best_possible_waste < 0.25 * cap {
                score += 70.0 * (1.0 - 0.5 * progress);
            }
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 80.0;
        }
        if progress > 0.8 && pr > 0.45 * cap {
            score += 100.0 * progress;
        }
        if fitting_bins_count > 1 && pr <= 4.0 {
            score += 120.0;
        }
        // late restraint: don't open bins when an existing fit exists
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 140.0 * progress;
        }
        // fresh-bin bias against small items mid/late stream
        if item_size <= 30 && fitting_bins_count > 0 && progress > 0.3 {
            score += 90.0 * progress;
        }
        // gate: only open when the best existing fit would strand less than next demand
        if fitting_bins_count > 0 && next_item_size > 0 {
            let best_waste = bin_residual.saturating_sub(item_size) as f64;
            if best_waste < nx * 0.6 {
                score += 55.0 * (1.0 - 0.3 * progress);
            }
        }
        if fitting_bins_count > 0 && progress > 0.5 {
            let stranded = bin_residual.saturating_sub(item_size) as f64;
            if stranded > 0.55 * cap {
                score -= 55.0 * (progress - 0.5) * 2.0;
            }
        }
    } else {
        score -= 15.0;
    }

    // Early stream: discourage fragmenting
    score += progress * 20.0 * (pr / cap);

    // Small items prefer near-perfect fits
    if item_size <= 10 && post_residual > 0 {
        score += pr * 0.45;
    }

    // Very large items: prefer any existing bin that fits
    if it > 0.7 * cap && !fresh {
        score -= 60.0;
    }

    // Exact-size match to current residual
    if post_residual == item_size {
        score -= 90.0;
        if nx > it {
            score -= 70.0;
        }
    }

    // Variance-aware dead-space shaping
    if !fresh {
        let dist_from_half = (pr - half).abs();
        if pr > 0.0 && pr < cap {
            score += (1.0 - dist_from_half / half) * 18.0;
        }
    }

    // Late-stream consolidation
    if progress > 0.75 {
        score += (pr / cap) * 35.0 * progress;
    }

    // Mid-stream near-exact chain fit
    if progress > 0.35 && progress < 0.85 && nx > 0.0 && pr >= nx && pr - nx < 12.0 {
        score -= 45.0;
    }

    // GEN-20: near-full bin bonus — squeeze the last units of waste out
    if !fresh && pr <= 6.0 {
        score -= (6.0 - pr) * 9.0 * (0.5 + progress);
    }

    // GEN-20: among several fitting bins, reward tightness relative to mean
    if fitting_bins_count >= 2 && !fresh {
        let rel = (pr / mean_residual.max(1.0)).min(2.0);
        score += rel * 6.0;
        if pr < 0.15 * cap {
            score -= 30.0 * (1.0 - pr / (0.15 * cap));
        }
    }

    // GEN-22: tiling-error coupling with mean residual
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let est = mean_residual.max(1.0);
        let k = (pr / est).round().max(1.0);
        let tiling_err = ((pr - k * est).abs()) / est;
        score += tiling_err * 16.0 * (0.5 + 0.5 * progress);
        if tiling_err < 0.1 {
            score -= 20.0 * k.min(3.0) * (1.0 - 0.5 * progress);
        }
    }

    // GEN-22: keep room for a follow-up item after the next item lands
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && (rem2 as f64) < nx * 0.25 && rem2 < 20 {
            score += (20.0 - rem2 as f64) * 3.0 * (0.5 + progress);
        } else if rem2 >= next_item_size {
            score -= 28.0 * (1.0 - 0.4 * progress);
        }
    }

    // GEN-28 mutation: adaptive sliver penalty scaled to observed item sizes
    let sliver_limit = if nx > 0.0 { (nx * 0.5).clamp(8.0, 25.0) } else { 15.0 };
    if post_residual > 0 && (post_residual as f64) < sliver_limit && post_residual != next_item_size {
        score += 40.0 * (1.0 - progress) * (1.0 - post_residual as f64 / sliver_limit);
    }

    // GEN-28 mutation: residual variance-aware tightening
    if mean_residual > 0.0 && !fresh {
        let tight_gain = (pr / mean_residual).powi(2).min(4.0);
        score -= 10.0 * tight_gain * (1.0 - progress) * 0.5;
    }

    // GEN-28 mutation: prefer tightest fit when many bins fit
    if fitting_bins_count > 2 && !fresh {
        score += pr * 0.12;
    }

    // GEN-28 mutation: fragmentation guard for nearly-empty fitting bins
    if fitting_bins_count <= 2 && !fresh && pr > 0.5 * cap {
        score += 25.0 + 0.3 * (pr - 0.5 * cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space avoidance: penalize small unusable gaps heavily (non-linear)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }

    // Reward tight fits (exact or near-exact packing)
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Open-bin pressure: penalize selecting bins when many bins are open,
    // encouraging consolidation into fewer bins unless the fit is excellent
    let progress = step_index as f64 / total_items as f64;
    let bin_pressure = (open_bins_count as f64).ln().max(1.0);
    score += 3.0 * bin_pressure * (1.0 - progress);

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin if this bin's fit is bad
    if bin_residual == bin_capacity {
        // Neutral-ish base, penalized if existing bins would leave small gaps
        score += 15.0;
        if post_residual < 10 {
            score -= 20.0; // fresh bin leaves big residual, fine
        }
        // Prefer opening a new bin early when few bins are open
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_leftover = post_residual - next_item_size;
        if next_leftover < 10 {
            score -= 12.0;
        }
    }

    // Penalize bins whose residual deviates wildly from mean (fragmentation signal)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

