    // GEN-29 mutation: fresh-bin opportunity cost — compare the stranded waste of
    // opening a new bin against the best existing fit; open only when clearly better.
    if fresh && fitting_bins_count > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        let new_waste = cap - it;
        if new_waste > best_waste + 0.12 * cap {
            score += 65.0 * (0.5 + 0.5 * progress);
        } else if best_waste > new_waste + 0.1 * cap {
            score -= 45.0;
        }
    }

    // GEN-29 mutation: residual ladder — reward residuals that match common item
    // sizes implied by the stream (next item or its complement to capacity).
    if !fresh && next_item_size > 0 && post_residual > 0 {
        let comp = bin_capacity.saturating_sub(next_item_size);
        if post_residual == comp {
            score -= 30.0 * (1.0 - 0.4 * progress);
        }
        if post_residual == next_item_size / 2 {
            score -= 18.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals the next item's size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }
    // Near-perfect match: next item fits with small slack afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize residuals that are too small for the next item (dead space risk),
    // especially when post_residual is nonzero but unusable.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Favor tight fits relative to the current item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness;

    // Last-chance bin: strongly reward using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }
    // Mild reward when few fitting bins exist (avoid fragmentation).
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual close to the mean keeps the fleet balanced.
    let mean_dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_dev;

    // New-bin candidate (empty bin): make it attractive only when it is genuinely better.
    if bin_residual == bin_capacity {
        // Default: slightly discourage opening new bins.
        score += 20.0;
        // But if the item is large and open bins are fragmented, opening a new bin
        // preserves flexibility.
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 * 0.6 {
            score -= 45.0;
        }
        // Early in the stream, new bins are cheap.
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight late-stream conservatism: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fresh = bin_residual == bin_capacity;
    let half = 0.5 * cap;

    // Perfect fit: strong reward, amplified early
    if post_residual == 0 {
        score -= 1150.0 + 150.0 * (1.0 - progress);
    }

    // Cubic dead-space penalty, softened late
    score += pr.powi(3) / (cap * cap * cap) * 90.0 * (1.0 - 0.5 * progress);

    // Last-chance bin
    if fitting_bins_count == 1 && !fresh {
        score -= 350.0;
    }

    // Lookahead chain logic
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 580.0;
        } else if post_residual > next_item_size {
            let chain_left = post_residual - next_item_size;
            let chain_bonus = if chain_left <= item_size { 110.0 } else if chain_left <= next_item_size { 60.0 } else { 0.0 };
            score -= 60.0 * (pr / nx.max(1.0)).ln().max(0.0) + chain_bonus;
            let slack = pr - nx;
            if slack < 8.0 {
                score -= (8.0 - slack) * 12.0;
            }
            if chain_left > item_size && chain_left >= next_item_size {
                score -= 25.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * (0.7 + 0.5 * (1.0 - progress));
            if pr < 8.0 {
                score -= 20.0;
            }
        }
        if post_residual == item_size.saturating_add(next_item_size) {
            score -= 300.0;
        } else if post_residual < item_size.saturating_add(next_item_size) && pr < 0.25 * cap {
            score += 60.0 + 0.5 * (0.25 * cap - pr);
        }
