    if !fresh && next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let err = ((pr - mean_residual) / mean_residual).abs();
        if err < 0.2 {
            score -= 32.0 * (1.0 - err / 0.2) * (1.0 - 0.3 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early stream: mild penalty on large residuals (encourage tight packing growth).
    // Late stream: strong penalty on wasted residual (fewer chances to fill gaps).
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) + norm_pr * (0.5 + 2.5 * progress * progress);
    score += poly * cap * 0.25;

    // Reward near-perfect fits with a smooth saturating term.
    let fit_quality = 1.0 - (pr / cap);
    score -= (fit_quality * fit_quality * fit_quality) * item_size as f64 * 0.6;

    // Lookahead: reward leaving space exactly matching the next item; penalize
    // residuals that neither fit the next item nor stay useful.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let diff = (pr - nxt) as f64;
            score -= (1.0 - diff / cap) * 6.0;
        } else {
            score += (nxt - pr) / cap * 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 12.0 + 0.15 * item_size as f64;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer tighter ones (already via post_residual),
        // slight penalty to keep competition smooth.
        score += (fitting_bins_count as f64).ln() * 0.8;
    }

    // Mean residual context: penalize bins far below mean residual (they are
    // the "holey" ones) with a smooth quadratic divergence term.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // New-bin candidate: make it moderately attractive early, expensive late,
    // and cheap if no existing bin fits well.
    if bin_residual == bin_capacity {
        let new_bin_cost = 30.0 + 60.0 * progress * progress - 10.0 * (1.0 - progress);
        score += new_bin_cost;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // fresh bin can serve the lookahead too
        }
    }

    // Late-stream urgency: compress scores toward minimizing residual.
    score += progress * (pr / cap) * 15.0;

    score
}

