        let rem3 = bin_residual.saturating_sub(pair_sum);
        if rem3 > 0 && rem3 <= 100 && rem3 >= next_item_size / 2 {
            score -= 35.0 * (1.0 - progress);
        }
    }

    // GEN-29 mutation: near-full bin bonus — squeeze last units of waste
    if !fresh && pr <= 6.0 {
        score -= (6.0 - pr) * 11.0 * (0.5 + progress);
    }

    // GEN-29 mutation: tiling against mean residual — reward post-residuals
    // that are near-multiples of the observed item size so future items tile
    // the space exactly; penalize tiling error proportionally.
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let est = mean_residual.max(1.0);
        let k = (pr / est).round().max(1.0);
        let tiling_err = ((pr - k * est).abs()) / est;
        score += tiling_err * 18.0 * (0.5 + 0.5 * progress);
        if tiling_err < 0.1 {
            score -= 22.0 * k.min(3.0) * (1.0 - 0.5 * progress);
        }
    }

    // GEN-29 mutation: fresh-bin opening gate — only open when the best
    // existing fit would strand less than the estimated next-item demand.
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < nx * 0.6 {
            score += 60.0 * (1.0 - 0.3 * progress);
        }
    }

    // GEN-29 mutation: tightest-of-many bonus — when several bins fit, reward
    // small post-residuals sharply to break ties toward near-perfect fits.
    if fitting_bins_count >= 2 && !fresh {
        if pr < 0.15 * cap {
            score -= 32.0 * (1.0 - pr / (0.15 * cap));
        }
    }

    // GEN-29 mutation: chain remainder must remain usable — penalize
    // placements that leave a remainder too small for the next item when
    // space was otherwise plentiful.
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && (rem2 as f64) < nx * 0.25 && rem2 < 20 {
            score += (20.0 - rem2 as f64) * 3.5 * (0.5 + progress);
        }
    }

    score
}

