pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into bands of 10.
    let class = post_residual / 10;
    // Small classes (tight fits) are valuable -> subtract; large classes -> mild add.
    match class {
        0 => score -= 40.0,
        1 => score -= 25.0,
        2 => score -= 12.0,
        3 => score -= 5.0,
        4 => score += 3.0,
        5 => score += 8.0,
        6 => score += 14.0,
        7 => score += 20.0,
        8 => score += 26.0,
        _ => score += 30.0,
    }

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Perfect pairing: the next item exactly fills the residual left here.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 55.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item can still fit after this placement: good chaining.
        score -= (post_residual - next_item_size) as f64 * 0.4;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space created relative to lookahead: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it, else bin gets wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when the item barely fits anywhere else
    // or open bins are very full on average.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let avg_fullness = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        // Penalize opening a new bin mildly; relax when bins are nearly full.
        score += 35.0 - 40.0 * avg_fullness - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative anyway
        }
    }

    // Prefer fuller bins slightly (couple with mean residual).
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

