    }

    // Tightness vs mean, amplified by open bin count
    score += (pr - mean_residual) * (0.5 + 0.005 * open_bins_count.min(60) as f64);

    // Consolidation pressure
    score += (open_bins_count as f64).powi(2) * 0.004 + open_bins_count as f64 * 0.2;

    // Waste-ratio term
    let fill_fraction = it / cap;
    let hole_fraction = pr / cap;
    if hole_fraction > fill_fraction {
        score += (hole_fraction - fill_fraction) * 140.0;
    }

    // New-bin candidate logic
    if fresh {
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 280.0;
        } else if fitting_bins_count == 1 {
            let waste_if_stuffed = bin_residual.saturating_sub(item_size) as f64;
            score -= 130.0 + 0.7 * waste_if_stuffed;
        } else {
            let best_possible_waste = bin_residual.saturating_sub(item_size) as f64;
            if best_possible_waste > 0.4 * cap {
                score -= 90.0;
            }
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 80.0;
        }
        if progress > 0.8 && pr > 0.45 * cap {
            score += 100.0 * progress;
        }
        if fitting_bins_count > 1 && pr <= 4.0 {
            score += 120.0;
        }
        // late-stream restraint
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 140.0 * progress;
        }
        // fresh gate: don't open when existing fit would waste less than next-item demand
        if fitting_bins_count > 0 && next_item_size > 0 {
            let best_waste = bin_residual.saturating_sub(item_size) as f64;
            if best_waste < nx * 0.6 {
                score += 55.0 * (1.0 - 0.3 * progress);
            }
            if best_waste > 0.55 * cap && progress > 0.5 {
                score -= 55.0 * (progress - 0.5) * 2.0;
            }
        }
        // bias against small items opening bins late
        if item_size <= 30 && fitting_bins_count > 0 && progress > 0.3 {
            score += 90.0 * progress;
        }
    } else {
        score -= 15.0;
    }

    // Early stream: discourage fragmenting
    score += progress * 20.0 * (pr / cap);

    // Small items prefer near-perfect fits
    if item_size <= 10 && post_residual > 0 {
        score += pr * 0.45;
    }

    // Very large items: prefer any existing bin that fits
    if it > 0.7 * cap && !fresh {
        score -= 60.0;
    }

    // Exact-size match to current residual
    if post_residual == item_size {
        score -= 90.0;
        if nx > it {
            score -= 70.0;
        }
    }

    // Variance-aware dead-space shaping
    let dist_from_half = (pr - half).abs();
    if pr > 0.0 && pr < cap && !fresh {
        score += (1.0 - dist_from_half / half) * 18.0;
    }

    // Late-stream consolidation
    if progress > 0.75 {
        score += (pr / cap) * 35.0 * progress;
    }

    // Mid-stream near-exact chain fit
    if progress > 0.35 && progress < 0.85 && nx > 0.0 && pr >= nx && pr - nx < 12.0 {
        score -= 45.0;
    }

    // Near-full bin bonus — squeeze the last units of waste out
    if !fresh && pr <= 6.0 {
        score -= (6.0 - pr) * 9.0 * (0.5 + progress);
    }

    // Among several fitting bins, reward tightness relative to mean
    if fitting_bins_count >= 2 && !fresh {
        let rel = (pr / mean_residual.max(1.0)).min(2.0);
        score += rel * 6.0;
        if pr < 0.15 * cap {
            score -= 30.0 * (1.0 - pr / (0.15 * cap));
        }
        if nx > 0.0 && pr >= nx && pr < 0.3 * cap {
            score += (pr - nx) * 1.5 * progress;
        }
    }

    // Tiling: reward post-residuals that are near-multiples of mean item size
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let est = mean_residual.max(1.0);
        let k = (pr / est).round().max(1.0);
        let tiling_err = ((pr - k * est).abs()) / est;
        score += tiling_err * 16.0 * (0.5 + 0.5 * progress);
        if tiling_err < 0.1 {
            score -= 20.0 * k.min(3.0) * (1.0 - 0.5 * progress);
        }
    }

    // Dead-space budget accounting
    if !fresh && post_residual > 0 {
        let remaining = ((total_items - step_index) as f64).max(1.0);
        let est_item = (cap - mean_residual).max(1.0);
        let recoverable = if pr >= est_item * 0.5 { 1.0 } else { pr / (est_item * 0.5) };
        let permanence = (1.0 - recoverable).clamp(0.0, 1.0);
        let hole_price = pr * (0.15 + 0.55 * permanence) * (1.0 - 0.6 / (1.0 + remaining * 0.02));
        score += hole_price;
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let refund = (pr - next_item_size as f64).min(pr);
            score -= refund * 0.35 * (1.0 - progress);
        }
    }

    // Awkward-band gap penalty
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap < 8 {
            score -= (8 - gap) as f64 * 7.0 * (0.5 + progress);
        }
    }

    // Fragmentation guard
    if fitting_bins_count <= 2 && !fresh && pr > 0.5 * cap {
        score += 25.0 + 0.3 * (pr - 0.5 * cap);
    }

    // Prefer tightest fit when many bins fit
    if fitting_bins_count > 2 {
        score += pr * 0.12;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 - (post_residual as f64) * 4.0; // worst for gap=1 -> +56, gap=10 -> +20
    } else if post_residual > 10 && post_residual <= 20 {
        score += 8.0; // medium-small gaps mildly penalized
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or stream is late.
        score += 30.0 + 12.0 * open_pressure + 20.0 * progress;
        // But if the next item is small enough to use this bin's future residual well,
        // slightly soften the penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward matching residual to mean (keeps bin population balanced).
        score -= 0.3 * (mean_residual - post_residual as f64).abs().min(50.0);
        // If the next item fits exactly in the post-residual, big reward (lookahead chaining).
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fresh = bin_residual == bin_capacity;
    let half = 0.5 * cap;

    // Perfect fit: strong reward, amplified early
    if post_residual == 0 {
        score -= 1150.0 + 170.0 * (1.0 - progress);
    }

    // Cubic dead-space penalty, softened late
    score += pr.powi(3) / (cap * cap * cap) * 95.0 * (1.0 - 0.5 * progress);

    // Last-chance bin
    if fitting_bins_count == 1 && !fresh {
        score -= 350.0;
    }

    // Lookahead chain logic
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 590.0;
        } else if post_residual > next_item_size {
            let chain_left = post_residual - next_item_size;
            let chain_bonus = if chain_left <= item_size { 115.0 } else if chain_left <= next_item_size { 62.0 } else { 0.0 };
            score -= 60.0 * (pr / nx.max(1.0)).ln().max(0.0) + chain_bonus;
            let slack = pr - nx;
            if slack < 8.0 {
                score -= (8.0 - slack) * 12.0;
            }
            if chain_left > item_size && chain_left >= next_item_size {
                score -= 25.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * (0.7 + 0.5 * (1.0 - progress));
            if pr < 8.0 {
                score -= 20.0;
            }
        }
        if post_residual == item_size.saturating_add(next_item_size) {
            score -= 300.0;
        } else if post_residual < item_size.saturating_add(next_item_size) && pr < 0.25 * cap {
            score += 60.0 + 0.5 * (0.25 * cap - pr);
        }
    }

    // Tightness vs mean, amplified by open bin count
    score += (pr - mean_residual) * (0.5 + 0.005 * open_bins_count.min(60) as f64);

    // Consolidation pressure
    score += (open_bins_count as f64).powi(2) * 0.004 + open_bins_count as f64 * 0.2;

    // Waste-ratio term
    let fill_fraction = it / cap;
    let hole_fraction = pr / cap;
    if hole_fraction > fill_fraction {
        score += (hole_fraction - fill_fraction) * 145.0;
