        if post_residual >= next_item_size {
            // Leftover reusable by next item: subtract proportional to how snugly it fits.
            let snug = (post_residual - next_item_size) as f64;
            score -= 20.0 + 15.0 * (1.0 - snug / bin_capacity as f64);
        } else {
            // Leftover cannot host next item: dead space penalty, worse if tiny.
            let dead = post_residual as f64;
            score += 10.0 * (1.0 - dead / bin_capacity as f64);
        }
    }

    // Perfect closure bonus: filling the bin exactly is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Compare post_residual relative to mean residual across open bins:
    // leaving below-average residual (tighter packing) is good.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize new-bin option mildly so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.2 * mean_residual;
        // If nothing fits well (large post_residual everywhere), new bin becomes attractive.
        if post_residual as f64 > mean_residual + 10.0 {
            score -= 30.0;
        }
    }

    // Slight late-stream conservatism: keep bins tight as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
