        if nx > 0.0 && (pr - nx).abs() < 3.0 && pr != nx {
            score += 12.0 * (1.0 - progress);
        }
    }

    // GEN-20: exact next-item fit with large next item
    if !fresh && next_item_size > 0 && post_residual == next_item_size && nx > 0.4 * cap {
        score -= 40.0 * (1.0 - progress);
    }

    // GEN-20: residual-band matching against mean residual
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let scrap = (pr % mean_residual) / mean_residual;
        score += scrap * 22.0 * (0.4 + 0.6 * progress);
    }

    // GEN-20: near-miss calibration
    if !fresh && nx > 0.0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        let mid_band = dist_from_half < 0.15 * cap;
        if mid_band {
            score += 18.0 * (1.0 - miss / nx.max(1.0));
        }
    }

    // GEN-20: fresh-bin discount when residual would strand a large block late
    if fresh && fitting_bins_count > 0 && progress > 0.5 {
        let stranded = bin_residual.saturating_sub(item_size) as f64;
        if stranded > 0.55 * cap {
            score -= 55.0 * (progress - 0.5) * 2.0;
        }
    }

    // GEN-22: tiling-error shaping
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let est = mean_residual.max(1.0);
        let k = (pr / est).round().max(1.0);
        let tiling_err = ((pr - k * est).abs()) / est;
        score += tiling_err * 16.0 * (0.5 + 0.5 * progress);
        if tiling_err < 0.1 {
            score -= 20.0 * k.min(3.0) * (1.0 - 0.5 * progress);
        }
    }

    // GEN-22: lookahead trade-off on remainder
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && (rem2 as f64) < nx * 0.25 && rem2 < 20 {
            score += (20.0 - rem2 as f64) * 3.0 * (0.5 + progress);
        } else if rem2 >= next_item_size {
            score -= 28.0 * (1.0 - 0.4 * progress);
        }
    }

    // GEN-22: fresh-bin opening gate
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < nx as f64 * 0.6 {
            score += 55.0 * (1.0 - 0.3 * progress);
        }
    }

    // GEN-31 mutation A: dead-space ratio refinement — sharpen the cubic penalty
    // with a quadratic companion term so mid-band residuals are priced more
    // smoothly, reducing stranded waste in the 20–50% residual band.
    if !fresh && pr > 0.0 && pr < cap {
        let frac = pr / cap;
        if frac > 0.2 && frac < 0.5 {
            let band_pos = (frac - 0.2) / 0.3;
            score += (1.0 - (2.0 * band_pos - 1.0).powi(2)) * 22.0 * (0.4 + 0.6 * progress);
        }
    }

    // GEN-31 mutation B: chain-depth-aware refund — when the post-residual can
    // host the next item AND still leaves room matching the mean item size,
    // deepen the reward to encourage multi-item chains per bin.
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && mean_residual > 1.0 {
            let k = (rem2 as f64 / mean_residual).round();
            let err = ((rem2 as f64 - k * mean_residual).abs()) / mean_residual;
            if err < 0.15 {
                score -= 30.0 * (1.0 - err / 0.15) * (0.6 + 0.4 * progress);
            }
        }
    }

    // GEN-31 mutation C: fresh-bin gate recalibrated — open a new bin only when
    // every existing fit would strand more than the mean item demand; tighten
    // the threshold slightly with progress to force late consolidation.
    if fresh && fitting_bins_count > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        let gate = mean_residual.max(nx as f64) * (0.75 - 0.25 * progress);
        if best_waste < gate {
            score += 65.0 * (1.0 - 0.3 * progress);
        }
    }

    // GEN-31 mutation D: endgame squeeze — in the final stretch, prize bins
    // whose residual is within reach of typical remaining item sizes.
    if progress > 0.7 && !fresh && post_residual > 0 {
        let est = mean_residual.max(1.0);
        if pr >= est * 0.9 && pr <= est * 1.6 {
            score -= 26.0 * (progress - 0.7) / 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed for time-dependent behavior.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness reward: strongly prefer placements leaving little waste,
    // with a quadratic penalty on leftover space.
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += 30.0 * tightness;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward heavily; if post residual is too small for the next item
    // but nonzero, penalize dead space that blocks the lookahead item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item can still be placed here: good chaining.
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Post residual unusable for next item: mild penalty scaled by waste.
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Prefer filling bins whose residual is already small relative to
    // the global mean residual (consolidate waste).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize using a very large-residual bin for a small item when
    // many other bins are open (preserve big holes for big items).
    let hole_ratio = bin_residual as f64 / bin_capacity as f64;
    let item_ratio = item_size as f64 / bin_capacity as f64;
    if hole_ratio - item_ratio > 0.4 {
        score += 15.0 * (hole_ratio - item_ratio - 0.4);
    }

    // New-bin candidate handling: it is attractive early in the stream
    // or when the fit into any open bin is poor (large post residual).
    if bin_residual == bin_capacity {
        let early_bonus = 20.0 * (1.0 - progress);
        score -= early_bonus;
        // If the current item would leave a bad fit in open bins,
        // opening a fresh bin is fine; otherwise discourage it slightly
        // as open bins accumulate.
        score += 0.8 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 5.0; // fresh bin keeps flexibility for similar items
        }
    }

    // Late in the stream, close out bins: favor placements that leave
    // residuals smaller than the smallest typical item (dead space).
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold + 1.0 && post_residual > 0 {
        score += 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
