            let tightness = 1.0 - leftover / demand;
            score -= 20.0 * fits.min(3.0) * tightness * (1.0 - 0.4 * progress);
            // exact tiling bonus when leftover could still host the next item
            if nx > 0.0 && leftover >= nx && leftover - nx < 6.0 {
