    // Smooth non-linear coupling: quadratic and cubic post-residual shaping
    score += 40.0 * norm_pr * norm_pr * (1.0 - norm_pr);

    // Progress-dependent penalty: late in the stream, avoid leaving large residuals
    score += progress * 25.0 * norm_pr * norm_pr;

    // Reward tight fits, stronger as stream progresses (smooth sigmoid-like term)
    let tight = 1.0 - norm_pr;
    score -= (0.5 + 0.5 * progress) * 30.0 * tight * tight;

