            score -= 15.0 * ng * (1.0 - ng) * (1.0 - progress);
        } else {
            score += 8.0 * (-gap / cap);
        }
    }

    // Last-chance bin bonus (smooth, avoids hard constant)
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr * 0.5);
    }

    // Mild penalty for opening new bins when many bins are already open
    if bin_residual == bin_capacity {
        score += 12.0 + 5.0 * (open_bins_count as f64).sqrt() + 10.0 * progress;
    }

    // Mean-residual deviation coupling
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    score
}

