    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into
    // capacity-fraction buckets. Residuals in "small" classes (<= ~15) are
    // nearly dead space; residuals in large classes remain reusable.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Integer-division thresholds on post_residual (harmonic classes of C=100)
    let class = if post_residual == 0 { 0 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 20 { 2 }
        else if post_residual <= 33 { 3 }
        else if post_residual <= 50 { 4 }
        else { 5 };

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 60.0;
    }
    score -= match class {
        1 => 25.0,
        2 => 12.0,
        3 => 4.0,
        4 => -3.0,
        _ => -8.0,
    };

    // Modulo arithmetic: residuals divisible by common item sizes (10/20/25/50)
    // are more likely to be exactly filled by future items.
    let harmonic_bonus = if post_residual % 10 == 0 { 6.0 }
        else if post_residual % 25 == 0 { 5.0 }
        else if post_residual % 5 == 0 { 2.5 }
        else { 0.0 };
    score -= harmonic_bonus;

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement is excellent.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let nxt_post = post_residual - next_item_size;
            score -= (nxt_post as f64) * 0.35;
            if nxt_post % 10 == 0 { score -= 3.0; }
        } else {
            // next item cannot follow into this bin -> mild penalty scaled
            // by how "wasted" the residual looks relative to next item
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    } else {
        // Last item: prefer filling existing bins completely
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid
    // opening a new bin for a poor fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Penalize opening a new bin when good existing options exist, but allow
    // it when this bin's residual is small (dead space anyway).
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost of opening a bin
        score += 55.0;
        // but if current bin's would-be residual is tiny, new bin is fine
        if post_residual >= 50 { score -= 10.0; }
        if fitting_bins_count == 0 { score -= 40.0; }
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0 * (1.0 - frac);

    // Coupling with mean residual: if this bin's residual is far below the
    // mean, it is already fragmented; penalize leaving it more fragmented.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.08;
    } else {
        score += dev * 0.05;
    }

    // Many open bins -> consolidation pressure on large-residual bins.
    if open_bins_count > 3 {
        score -= (open_bins_count.min(20) as f64) * 0.4 * frac;
    }

    score
}

