    let mut score = post_residual as f64;

    // New-bin candidate baseline: moderately high so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin is cheaper early (more future items to fill it) and
        // when this item is a "last chance" nowhere else.
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 60.0 };
        return 55.0 + desperation - 25.0 * progress;
    }

    // Aggressive 2-step lookahead: reward exact match with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect: next item exactly fills this bin.
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item still fits here: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / 100.0);
        } else {
            // Next item cannot use leftover: penalize dead space severity.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.35 * dead;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 30.0;
    }

    // Reward using bins with low residual relative to mean (consolidate waste).
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.25 * (mean_residual - res);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Penalize very small unusable leftovers (dead space < typical min item 10).
    if res > 0 && res < 10 {
        score += 15.0;
    }

    score
}

