    if fresh && fitting_bins_count > 0 {
        let waste_existing = bin_residual.saturating_sub(item_size) as f64;
        let open_cost = cap - it;
        if open_cost > waste_existing {
            score += (open_cost - waste_existing) * 0.35 * (1.0 - 0.3 * progress);
        }
    }

