}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Penalize leaving small dead space (< 10, unusable for min item size 1 but wasteful mid-range).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that next item cannot use: mild penalty.
        score += 3.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize spreading across many open bins with large mean residual (fragmentation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score += 0.5 * (mean_residual - post_residual as f64).abs();
    }

    // New-bin candidate logic: only attractive when open bins are very fragmented
    // (high mean residual) or late in the stream with few bins.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let penalty = 40.0 + 60.0 * (1.0 - fragmentation) + 30.0 * (1.0 - progress);
        // Discount penalty if existing fits are terrible (post_residual high relative).
        score += penalty - 20.0 * (post_residual as f64 / bin_capacity as f64);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for bins with below-average residual (keep big holes for big items).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    score
}

