    if fitting_bins_count <= 2 && !fresh && pr > 0.5 * cap {
        score += 25.0 + 0.3 * (pr - 0.5 * cap);
    }

    // Residual-dead-space coupling
    if !fresh && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 20.0 {
            score += miss * (2.5 + 3.0 * progress);
        }
        let mid_band = dist_from_half < 0.15 * cap;
        if mid_band {
            score += 18.0 * (1.0 - miss / nx.max(1.0));
        }
    }

    // Reward bins whose post-residual can host plausible future fill
    if !fresh && post_residual > 0 {
        let est_item = (cap - mean_residual).max(1.0);
        let fits_est = (post_residual as f64 / est_item).floor();
        if fits_est >= 1.0 {
            let leftover = post_residual as f64 - fits_est * est_item;
            score -= 14.0 * fits_est.min(3.0) * (1.0 - leftover / est_item) * (1.0 - 0.4 * progress);
        }
    }

    // Awkward-band gap penalty
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap < 8 {
            score -= (8 - gap) as f64 * 7.0 * (0.5 + progress);
        }
    }

    // Mid-band residual trap
    if !fresh && nx > 0.0 && pr >= nx && pr < 0.3 * cap && fitting_bins_count > 1 {
        let waste = pr - nx;
        score += waste * 1.5 * progress;
    }

    // Dead-space budget accounting
    if !fresh && post_residual > 0 {
        let remaining = ((total_items - step_index) as f64).max(1.0);
        let est_item = (cap - mean_residual).max(1.0);
        let recoverable = if pr >= est_item * 0.5 { 1.0 } else { pr / (est_item * 0.5) };
        let permanence = (1.0 - recoverable).clamp(0.0, 1.0);
        let hole_price = pr * (0.15 + 0.55 * permanence) * (1.0 - 0.6 / (1.0 + remaining * 0.02));
        score += hole_price;
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let refund = (pr - next_item_size as f64).min(pr);
            score -= refund * 0.35 * (1.0 - progress);
        }
    }

    // Two-step chain refinement
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 >= 0.2 * cap {
            score -= 22.0 * (1.0 - 0.5 * progress);
        } else if rem2 > 0 && (rem2 as f64) < 0.08 * cap {
            score += 14.0 * (1.0 - rem2 as f64 / (0.08 * cap));
        }
        if rem2 > 0 && (rem2 as f64) < nx * 0.25 && rem2 < 20 {
            score += (20.0 - rem2 as f64) * 3.0 * (0.5 + progress);
        } else if rem2 >= next_item_size {
            score -= 28.0 * (1.0 - 0.4 * progress);
        }
    }

    // Near-full bin bonus
    if !fresh && pr <= 6.0 {
        score -= (6.0 - pr) * 9.0 * (0.5 + progress);
    }

    // Among several fitting bins, reward tightness relative to mean
    if fitting_bins_count >= 2 && !fresh {
        let rel = (pr / mean_residual.max(1.0)).min(2.0);
        score += rel * 6.0;
        if pr < 0.15 * cap {
            score -= 30.0 * (1.0 - pr / (0.15 * cap));
        }
    }

    // Dead-space shaping near item boundary
    if !fresh && pr > 0.0 && pr < cap {
        if pr < it && progress < 0.9 {
            score += (1.0 - progress) * 30.0 * (pr / cap);
        }
        if nx > 0.0 && (pr - nx).abs() < 3.0 && pr != nx {
            score += 12.0 * (1.0 - progress);
        }
    }

    // Exact next-item fit with large next item
    if !fresh && next_item_size > 0 && post_residual == next_item_size && nx > 0.4 * cap {
        score -= 40.0 * (1.0 - progress);
    }

    // Residual-band matching against mean residual
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let scrap = (pr % mean_residual) / mean_residual;
        score += scrap * 22.0 * (0.4 + 0.6 * progress);
        let est = mean_residual.max(1.0);
        let k = (pr / est).round().max(1.0);
        let tiling_err = ((pr - k * est).abs()) / est;
        score += tiling_err * 16.0 * (0.5 + 0.5 * progress);
        if tiling_err < 0.1 {
            score -= 20.0 * k.min(3.0) * (1.0 - 0.5 * progress);
        }
    }

    // GEN-33 mutation: lookahead-aware compaction — when placing here leaves a
    // residual that exactly tiles with the estimated mean item size, reward
    // strongly; penalize residuals that fall into an unfillable sliver band.
    if !fresh && post_residual > 0 {
        let est = mean_residual.max(1.0);
        let tiles = (pr / est).floor();
        if tiles >= 1.0 && pr - tiles * est < 2.0 {
            score -= 26.0 * tiles.min(4.0) * (0.6 + 0.4 * (1.0 - progress));
        }
        let next_gap = if nx > 0.0 && pr > nx { pr - nx } else { 0.0 };
        if next_gap > 0.0 && next_gap < est * 0.3 {
            score += 20.0 * (1.0 - next_gap / (est * 0.3)) * progress;
        }
    }

    // GEN-33 mutation: fresh-bin opening gate — restrain opening when an open
    // bin would remain more than half usable after placement.
    if fresh && fitting_bins_count > 0 && progress > 0.4 {
        let usable_after = bin_residual.saturating_sub(item_size) as f64;
        if usable_after < 0.35 * cap {
            score += 80.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill: strongest reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class logic: decompose post_residual into decade class + remainder.
    // Residuals whose remainder is small relative to the class are "unusable slivers".
    let class = post_residual / 10;
    let rem = post_residual % 10;
    score += rem as f64 * 0.7;          // ragged remainder penalized
    score -= class as f64 * 1.5;        // larger usable blocks mildly favored

    // Dead-space band: residuals in (0,10) are near-useless slivers
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Lookahead coupling: does post_residual serve the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;              // exact harmonic match
        } else if post_residual >= next_item_size {
            score -= 12.0;              // still usable
        } else {
            score += 18.0;              // next item won't fit here
        }
        // next item exactly fills post_residual's class boundary (multiple of 10)
        if next_item_size % 10 == 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 28.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless open bins are fragmented
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.25 + open_bins_count as f64 * 2.0;
        // if no open bin leaves room for the next item, opening is less bad
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 25.0;
        }
    }

    // Stream progression: early on, be picky (favor tight fits); late, consolidate
    let t = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - t) * 6.0 - t * 4.0;

    // Mild consolidation pressure: fewer open bins relative to capacity -> prefer reuse
    score += open_bins_count as f64 * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
