    if fresh && fitting_bins_count > 0 {
        let waste_existing = bin_residual.saturating_sub(item_size) as f64;
        let avg_dead = (mean_residual * (mean_residual + 1.0) / 2.0 / cap.max(1.0)).max(0.0);
        let net_gain = waste_existing - avg_dead * cap * 0.35;
        if net_gain > 0.0 {
            score -= (net_gain / cap).min(1.0) * 70.0 * (1.0 - 0.4 * progress);
        } else {
            score += 35.0 * (1.0 - 0.5 * progress);
        }
    }

    // GEN-33 mutation: residual ladder — among fitting bins, sharply prefer the
    // smallest post-residual when the item nearly empties the bin; otherwise add a
    // graded pressure proportional to how far the residual sits above the item size.
    if !fresh {
        let overhang = pr.max(0.0);
        if overhang > 0.0 && overhang < 0.05 * cap {
            score -= (0.05 * cap - overhang) * 14.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual that can't fit even the smallest plausible item is wasted space.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny dead gap: worst outcome
        } else if post_residual < 25 {
            score += 25.0; // narrow gap: hard to reuse
        } else if post_residual < 50 {
            score += 8.0; // moderate gap
        }
    } else {
        score -= 40.0; // perfect fit: fully packed bin
    }

    // Reward leaving room for the lookahead item if it fits after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Extra reward for near-exact two-item packing.
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 12.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Placement creates a gap the next item cannot use: penalize more.
        score += 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.6;

    // Mild attraction toward bins with tighter residuals (good fits).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.15;

    // New-bin candidate: make empty bins moderately unattractive unless
    // the item is large relative to capacity or the fit elsewhere is bad.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.5;
        if !large_item && fitting_bins_count > 1 {
            score += 30.0;
        } else if large_item {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
