    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 >= 0.2 * cap {
            score -= 22.0 * (1.0 - 0.5 * progress);
        } else if rem2 > 0 && (rem2 as f64) < 0.08 * cap {
            score += 14.0 * (1.0 - rem2 as f64 / (0.08 * cap));
        }
    }

    // Fresh-bin gate tightened
    if fresh && fitting_bins_count >= 2 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < 0.25 * cap {
            score += 70.0 * (1.0 - 0.5 * progress);
        }
    }

    // Triple-chain lookahead
    if !fresh && next_item_size > 0 {
        let pair_sum = item_size.saturating_add(next_item_size);
        if post_residual == pair_sum {
            score -= 110.0 * (1.0 - 0.5 * progress);
        }
        let rem3 = bin_residual.saturating_sub(pair_sum);
        if rem3 > 0 && rem3 <= 100 && rem3 >= next_item_size / 2 {
            score -= 35.0 * (1.0 - progress);
        }
    }

    // Near-full bin bonus — squeeze the last units of waste out
    if !fresh && pr <= 6.0 {
        score -= (6.0 - pr) * 9.0 * (0.5 + progress);
    }

    // Among several fitting bins, reward tightness relative to mean
    if fitting_bins_count >= 2 && !fresh {
        let rel = (pr / mean_residual.max(1.0)).min(2.0);
        score += rel * 6.0;
        if pr < 0.15 * cap {
            score -= 30.0 * (1.0 - pr / (0.15 * cap));
        }
    }

    // Dead-space shaping near item boundary
    if !fresh && pr > 0.0 && pr < cap {
        if pr < it && progress < 0.9 {
            score += (1.0 - progress) * 30.0 * (pr / cap);
        }
        if nx > 0.0 && (pr - nx).abs() < 3.0 && pr != nx {
            score += 12.0 * (1.0 - progress);
        }
    }

    // Exact next-item fit with large next item — extra reward
    if !fresh && next_item_size > 0 && post_residual == next_item_size && nx > 0.4 * cap {
        score -= 40.0 * (1.0 - progress);
    }

    // Residual-band matching against mean residual — minimize scrap
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let scrap = (pr % mean_residual) / mean_residual;
        score += scrap * 22.0 * (0.4 + 0.6 * progress);
    }

    // Near-miss calibration — prefer residual just under next item
    if !fresh && nx > 0.0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        let mid_band = dist_from_half < 0.15 * cap;
        if mid_band {
            score += 18.0 * (1.0 - miss / nx.max(1.0));
        }
    }

    // Fresh-bin discount when residual would strand a large block late
    if fresh && fitting_bins_count > 0 && progress > 0.5 {
        let stranded = bin_residual.saturating_sub(item_size) as f64;
        if stranded > 0.55 * cap {
            score -= 55.0 * (progress - 0.5) * 2.0;
        }
    }

    // Tiling-error shaping: reward placements whose post-residual is a near-multiple
    // of the mean observed item size, so future items tile the remaining space exactly.
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let est = mean_residual.max(1.0);
        let k = (pr / est).round().max(1.0);
        let tiling_err = ((pr - k * est).abs()) / est;
        score += tiling_err * 16.0 * (0.5 + 0.5 * progress);
        if tiling_err < 0.1 {
            score -= 20.0 * k.min(3.0) * (1.0 - 0.5 * progress);
        }
    }

    // Lookahead trade-off — when the next item would leave a tiny remainder,
    // prefer bins that keep enough room for a follow-up item.
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && (rem2 as f64) < nx * 0.25 && rem2 < 20 {
            score += (20.0 - rem2 as f64) * 3.0 * (0.5 + progress);
        } else if rem2 >= next_item_size {
            score -= 28.0 * (1.0 - 0.4 * progress);
        }
    }

    // Fresh-bin opening gate — only open when the best existing fit would
    // strand more than the estimated next-item demand.
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < nx as f64 * 0.6 {
            score += 55.0 * (1.0 - 0.3 * progress);
        }
    }

    // GEN-34 mutation A: dead-space-to-fill ratio shaping — penalize bins whose
    // post-residual exceeds the mean item demand by a fraction of the item,
    // refining the diagnosed weakness in residual/dead-space ratio.
    if !fresh && post_residual > 0 {
        let ratio = pr / (it.max(1.0) + nx.max(1.0));
        if ratio > 0.35 {
            score += (ratio - 0.35) * 55.0 * (0.6 + 0.4 * progress);
        } else if ratio < 0.12 && pr > 0.0 {
            score -= (0.12 - ratio) * 70.0 * (1.0 - 0.3 * progress);
        }
    }

    // GEN-34 mutation B: harmonic waste pricing — quadratic residual penalty
    // weighted by remaining stream length, so early dead space costs more
    // (it has more chances to compound) than late dead space.
    if !fresh && post_residual > 0 {
        let remaining = ((total_items - step_index) as f64).max(1.0);
        let stream_frac = (remaining / total_items.max(1) as f64).clamp(0.0, 1.0);
        score += (pr * pr) / cap * 0.09 * (0.4 + 0.6 * stream_frac);
    }

    // GEN-34 mutation C: exact-divisibility bonus — when the post-residual is
    // an exact multiple of the next item, the bin will close perfectly on a
    // later step; reward this proportionally to how many copies fit.
    if !fresh && next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 {
        let copies = (post_residual / next_item_size).min(4) as f64;
        score -= 18.0 * copies * (1.0 - 0.4 * progress);
    }

    // GEN-34 mutation D: complementary-pair detection — if the next item leaves
    // a remainder exactly equal to the current item size, the bin can absorb a
    // repeat of this item next; strong consolidation signal.
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 == item_size {
            score -= 65.0 * (1.0 - 0.4 * progress);
        } else if rem2 > 0 && (rem2 as f64 - it).abs() < 4.0 {
            score -= 20.0 * (1.0 - 0.4 * progress);
        }
    }

    // GEN-34 mutation E: fresh-bin threshold recalibrated — open a new bin only
    // when the best existing option strands more than a data-driven fraction of
    // capacity, blending item size and observed mean demand.
    if fresh && fitting_bins_count > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        let demand = ((it + nx.max(0.0)) * 0.5).max(mean_residual * 0.6).max(8.0);
        let gate = (cap * 0.32).max(demand * 1.1);
        if best_waste < gate {
            score += 48.0 * (1.0 - 0.3 * progress);
        } else if best_waste > gate * 1.6 {
            score -= 30.0 * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: perfect fill with next item -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small leftover
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        score -= 25.0 - leftover as f64 * 0.8;
    }
    // Next item does NOT fit here: penalize leaving space next item can't use
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (post_residual as f64) * 0.5;
    }

    // Dead space penalty: residuals below min item size are wasted
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }
    // Perfect closure
    if post_residual == 0 {
        score -= 50.0;
    }

    // Relative to mean residual: prefer filling below-average-residual bins
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin (only fitting bin): avoid forcing a new bin unless fit is tight
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: keep it attractive only when current bins fit poorly
    if bin_residual == bin_capacity {
        let tight = next_item_size > 0 && post_residual >= next_item_size;
        if tight {
            score += 80.0; // an open bin has a lookahead match; discourage new bin
        } else {
            score -= 5.0;
        }
    }

    // Late stream: prefer closing bins to reduce open-bin sprawl
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.2;

    score
}

