pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * tightness * tightness * tightness;

    // Penalize dead space that can never be used again (post_residual too small
    // for the smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 12.0 * (25.0 - post_residual as f64) / 15.0;
    }

    // Lookahead: strongly reward bins whose post residual fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0;
            // extra reward for near-perfect two-item packing
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // penalize blocking the next item slightly
            score += 8.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).min(cap));
        }
    } else {
        // last item: pure tightness maximization
        score -= 30.0 * tightness;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // multiple options: mild penalty to encourage discrimination
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: it has bin_residual == bin_capacity, so
    // post_residual is large; make it attractive only when open bins are
    // fragmented or the stream is early (exploration).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // early stream: cheaper to open bins (exploration bonus decays over time)
        let exploration = 55.0 * (1.0 - progress).max(0.0);
        score -= exploration;
        // if many open bins with high mean residual, discourage yet another bin
        score += 1.5 * open_bins_count as f64;
        score += 0.6 * mean_residual;
        // never open a new bin for a tiny item
        if item_size < 25 {
            score += 80.0;
        }
    }

    // Global state coupling: prefer filling bins when mean residual is low
    // (bins are already fragmented; use them up).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Slight preference for bins with small current residual (compact bins first)
    score += 0.15 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let nx = next_item_size as f64;
    let it = item_size as f64;
    let fresh = bin_residual == bin_capacity;
    let half = 0.5 * cap;

    // Perfect fit: massive reward, amplified early
    if post_residual == 0 {
        score -= 1250.0 + 150.0 * (1.0 - progress);
    }

    // Cubic dead-space penalty, softened late
    score += pr.powi(3) / (cap * cap * cap) * 90.0 * (1.0 - 0.5 * progress);

    // Last-chance bin: strongly prefer it
    if fitting_bins_count == 1 && !fresh {
        score -= 350.0;
    }

    // Lookahead chain logic with fine residual fitting
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 580.0;
            if nx > 0.4 * cap {
                score -= 40.0 * (1.0 - progress);
            }
        } else if post_residual > next_item_size {
            let chain_left = post_residual - next_item_size;
            let chain_bonus = if chain_left <= item_size { 110.0 } else if chain_left <= next_item_size { 60.0 } else { 0.0 };
            score -= 60.0 * (pr / nx.max(1.0)).ln().max(0.0) + chain_bonus;
            let slack = pr - nx;
            if slack < 8.0 {
                score -= (8.0 - slack) * 12.0;
            }
            if chain_left > item_size && chain_left >= next_item_size {
                score -= 25.0;
            }
            // awkward small gap after next item
            let gap = chain_left;
            if gap > 0 && gap < 8 {
                score -= (8 - gap) as f64 * 7.0 * (0.5 + progress);
            }
        } else {
            score += (next_item_size - post_residual) as f64 * (0.7 + 0.5 * (1.0 - progress));
            if pr < 8.0 {
                score -= 20.0;
            }
            // near-miss calibration in mid band
            let miss = (next_item_size - post_residual) as f64;
            if dist_from_half_ok(pr, half, cap) {
                score += 18.0 * (1.0 - miss / nx.max(1.0));
            }
            if miss <= 20.0 {
                score += miss * (2.5 + 3.0 * progress);
            }
        }
        if post_residual == item_size.saturating_add(next_item_size) {
            score -= 300.0 + 110.0 * (1.0 - 0.5 * progress);
        } else if (post_residual as u32) < item_size.saturating_add(next_item_size) && pr < 0.25 * cap {
            score += 60.0 + 0.5 * (0.25 * cap - pr);
        }
        // two-step chain refinement
        if !fresh && post_residual >= next_item_size {
            let rem2 = post_residual - next_item_size;
            if rem2 as f64 >= 0.2 * cap {
                score -= 22.0 * (1.0 - 0.5 * progress);
            } else if rem2 > 0 && (rem2 as f64) < 0.08 * cap {
                score += 14.0 * (1.0 - rem2 as f64 / (0.08 * cap));
            }
            if rem2 > 0 && (rem2 as f64) < nx * 0.25 && rem2 < 20 {
                score += (20.0 - rem2 as f64) * 3.0 * (0.5 + progress);
            } else if rem2 >= next_item_size {
                score -= 28.0 * (1.0 - 0.4 * progress);
            }
        }
        // pair-sum lookahead on bin residual
        let pair_sum = item_size.saturating_add(next_item_size);
        if bin_residual >= pair_sum {
            let pair_slack = bin_residual - pair_sum;
            if pair_slack <= 10 {
                score -= 70.0 - 4.0 * pair_slack as f64;
            }
        }
        // triple-chain lookahead
        if !fresh {
            let rem3 = bin_residual.saturating_sub(pair_sum);
            if rem3 > 0 && rem3 <= 100 && rem3 >= next_item_size / 2 {
                score -= 35.0 * (1.0 - progress);
            }
        }
    }

    // Tightness vs mean, amplified by open bin count
    score += (pr - mean_residual) * (0.5 + 0.005 * open_bins_count.min(60) as f64);

    // Consolidation pressure
    score += (open_bins_count as f64).powi(2) * 0.004 + open_bins_count as f64 * 0.2;

    // Waste-ratio term
    let fill_fraction = it / cap;
    let hole_fraction = pr / cap;
    if hole_fraction > fill_fraction {
        score += (hole_fraction - fill_fraction) * 140.0;
    }

    // New-bin candidate logic
    if fresh {
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 280.0;
        } else if fitting_bins_count == 1 {
            let waste_if_stuffed = bin_residual.saturating_sub(item_size) as f64;
            score -= 130.0 + 0.7 * waste_if_stuffed;
        } else {
            let best_possible_waste = bin_residual.saturating_sub(item_size) as f64;
            if best_possible_waste > 0.4 * cap {
                score -= 90.0;
            }
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 80.0;
        }
        if progress > 0.8 && pr > 0.45 * cap {
            score += 100.0 * progress;
        }
        if fitting_bins_count > 1 && pr <= 4.0 {
            score += 120.0;
        }
        // gate: don't open when an existing fit wastes little
        if fitting_bins_count > 0 && next_item_size > 0 {
            let best_waste = bin_residual.saturating_sub(item_size) as f64;
            if best_waste < nx * 0.6 {
                score += 55.0 * (1.0 - 0.3 * progress);
            }
            if best_waste < 0.25 * cap {
                score += 70.0 * (1.0 - 0.5 * progress);
            }
            let waste_existing = best_waste;
            let item_frac = it / cap;
            if waste_existing > cap * (0.5 - 0.4 * item_frac) {
                score -= 45.0 + 0.35 * (waste_existing - cap * (0.5 - 0.4 * item_frac));
            }
            if min_waste_large(waste_existing, cap) && progress < 0.7 {
                score -= 60.0 * (1.0 - progress);
            }
        }
        // late restraint
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 140.0 * progress;
        }
        // fresh-bin bias against small items late
        if item_size <= 30 && fitting_bins_count > 0 && progress > 0.3 {
            score += 90.0 * progress;
        }
        // stranded large block late
        if fitting_bins_count > 0 && progress > 0.5 {
            let stranded = bin_residual.saturating_sub(item_size) as f64;
            if stranded > 0.55 * cap {
                score -= 55.0 * (progress - 0.5) * 2.0;
            }
        }
        if progress < 0.25 && open_bins_count < 8 {
            score -= 30.0 * (1.0 - progress);
