            score -= 70.0;
        }
    }

    // Variance-aware dead-space shaping
    let dist_from_half = (pr - half).abs();
    if pr > 0.0 && pr < cap && !fresh {
        score += (1.0 - dist_from_half / half) * 18.0;
    }

    // Late-stream consolidation
    if progress > 0.75 {
        score += (pr / cap) * 35.0 * progress;
    }

    // Mid-stream near-exact chain fit
    if progress > 0.35 && progress < 0.85 && nx > 0.0 && pr >= nx && pr - nx < 12.0 {
        score -= 45.0;
    }

    // Dead-space trap detection
    if post_residual > 0 && post_residual < 15 {
        score += 35.0 * (1.0 - progress);
    }

    // Clean remainder after next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 == 0 {
            score -= 40.0;
        } else if rem2 <= 5 {
            score -= 18.0;
        }
    }

    // Residual variance-aware tightening
    if mean_residual > 0.0 {
        let tight_gain = (pr / mean_residual).powi(2).min(4.0);
        score -= 10.0 * tight_gain * (1.0 - progress) * 0.5;
    }

    // Adaptive sliver threshold
    let sliver_limit = if nx > 0.0 { (nx * 0.5).clamp(8.0, 25.0) } else { 15.0 };
    if post_residual > 0 && (post_residual as f64) < sliver_limit && post_residual != next_item_size {
        score += 40.0 * (1.0 - progress) * (1.0 - post_residual as f64 / sliver_limit);
    }

    // Prefer tightest fit when many bins fit
    if fitting_bins_count > 2 {
        score += pr * 0.12;
    }

    // Fragmentation guard
    if fitting_bins_count <= 2 && !fresh && pr > 0.5 * cap {
        score += 25.0 + 0.3 * (pr - 0.5 * cap);
    }

    // GEN-9: residual-dead-space coupling
    if !fresh && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 20.0 {
            score += miss * (2.5 + 3.0 * progress);
        }
    }

    // GEN-9: reward bins whose post-residual can host plausible future fill
    if !fresh && post_residual > 0 {
        let est_item = (cap - mean_residual).max(1.0);
        let fits_est = (post_residual as f64 / est_item).floor();
        if fits_est >= 1.0 {
            let leftover = post_residual as f64 - fits_est * est_item;
            score -= 14.0 * fits_est.min(3.0) * (1.0 - leftover / est_item) * (1.0 - 0.4 * progress);
        }
    }

    // GEN-13: dead-space budget accounting
    if !fresh && post_residual > 0 {
        let remaining = ((total_items - step_index) as f64).max(1.0);
        let est_item = (cap - mean_residual).max(1.0);
        let recoverable = if pr >= est_item * 0.5 { 1.0 } else { pr / (est_item * 0.5) };
        let permanence = (1.0 - recoverable).clamp(0.0, 1.0);
        let hole_price = pr * (0.15 + 0.55 * permanence) * (1.0 - 0.6 / (1.0 + remaining * 0.02));
        score += hole_price;
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let refund = (pr - next_item_size as f64).min(pr);
            score -= refund * 0.35 * (1.0 - progress);
        }
    }

    // GEN-11: mid-band residual trap
    if !fresh && nx > 0.0 && pr >= nx && pr < 0.3 * cap && fitting_bins_count > 1 {
        let waste = pr - nx;
        score += waste * 1.5 * progress;
    }

    // GEN-20: near-full bin bonus
    if !fresh && pr <= 6.0 {
        score -= (6.0 - pr) * 9.0 * (0.5 + progress);
    }

    // GEN-20: tightness relative to mean among fitting bins
    if fitting_bins_count >= 2 && !fresh {
        let rel = (pr / mean_residual.max(1.0)).min(2.0);
        score += rel * 6.0;
        if pr < 0.15 * cap {
            score -= 30.0 * (1.0 - pr / (0.15 * cap));
        }
    }

    // GEN-20: dead-space shaping near item boundary
    if !fresh && pr > 0.0 && pr < cap {
        if pr < it && progress < 0.9 {
            score += (1.0 - progress) * 30.0 * (pr / cap);
        }
        if nx > 0.0 && (pr - nx).abs() < 3.0 && pr != nx {
            score += 12.0 * (1.0 - progress);
        }
    }

    // GEN-20: residual-band matching against mean residual
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let scrap = (pr % mean_residual) / mean_residual;
        score += scrap * 22.0 * (0.4 + 0.6 * progress);
    }

    // GEN-22: tiling-error coupling — reward near-multiple of mean residual
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let est = mean_residual.max(1.0);
        let k = (pr / est).round().max(1.0);
        let tiling_err = ((pr - k * est).abs()) / est;
        score += tiling_err * 16.0 * (0.5 + 0.5 * progress);
        if tiling_err < 0.1 {
            score -= 20.0 * k.min(3.0) * (1.0 - 0.5 * progress);
        }
    }

    score
}

#[inline]
fn dist_from_half_ok(pr: f64, half: f64, cap: f64) -> bool {
    (pr - half).abs() < 0.15 * cap && pr > 0.0 && pr < cap
}

#[inline]
fn min_waste_large(waste: f64, cap: f64) -> bool {
    waste > 0.6 * cap
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (small post_residual)
    let mut score = pr;

    // Non-linear quadratic coupling of post_residual with stream progress:
    // early on, small waste is fine; later, waste becomes increasingly costly.
    let progress_weight = 0.5 + 3.0 * t * t;
    score += progress_weight * prn * prn * cap * 0.5;

    // Cubic term: extreme waste (near-empty bins) penalized super-linearly
    score += 8.0 * prn * prn * prn * cap;

    // Coupling with mean residual: if this bin's post-residual deviates strongly
    // above the mean residual, it creates fragmented space; penalize.
    let dev = pr - mean_residual;
    score += 0.35 * dev * (1.0 + 2.0 * t);

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) as f64;
            score -= 6.0 * (1.0 - slack / cap) * (0.5 + t);
        } else {
            // post-residual too small for the lookahead: dead space penalty
            score += 4.0 * prn * (1.0 + 3.0 * t);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (unless waste is enormous).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 12.0 * t;
    }

    // Scarcity pressure: many open bins relative to progress -> consolidate.
    let bins_norm = open_bins_count as f64 / (1.0 + total_items as f64 * 0.2);
    score += 2.0 * bins_norm * prn;

    // Mild reward for using existing bins vs. new bin (new bin has prn large,
    // already penalized; add explicit margin scaled by item size).
    score -= 0.05 * item_size as f64 * (1.0 - prn);

    score
}

