            score -= 28.0 * (1.0 - 0.4 * progress);
        }
    }

    // GEN-22 mutation: fresh-bin opening gate
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < nx as f64 * 0.6 {
            score += 55.0 * (1.0 - 0.3 * progress);
        }
    }

    // GEN-35 mutation: combined fine-grained residual fitting + lookahead —
    // reward placements whose post-residual can host the next item AND whose
    // second remainder tiles cleanly against mean residual, coupling the two
    // signals so we pick bins that chain into zero-scrap futures.
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if mean_residual > 1.0 {
            let k2 = (rem2 as f64 / mean_residual).round();
            let err2 = ((rem2 as f64 - k2 * mean_residual).abs()) / mean_residual;
            if err2 < 0.15 {
                score -= (26.0 - 12.0 * progress) * (1.0 - err2 / 0.15);
            }
        }
        // chain-continuation: rem2 still large enough for another next-size item
        if rem2 as f64 >= nx * 0.9 {
            score -= 18.0 * (1.0 - progress);
        }
    }

    // GEN-35 mutation: dual-signal fresh-bin decision — open a new bin only
    // when the best existing waste exceeds both a fraction of the next item
    // and a progress-scaled share of capacity.
    if fresh && fitting_bins_count > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        let gate = (nx.max(mean_residual) * 0.55).max(0.18 * cap * (1.0 - 0.5 * progress));
        if best_waste > gate {
            score -= 40.0 + 0.25 * (best_waste - gate);
        } else {
            score += 45.0 + 0.4 * (gate - best_waste);
        }
    }

    // GEN-35 mutation: residual-dead-space ratio penalty — directly price the
    // fraction of the bin that will end as unusable scrap after this placement.
    if !fresh && post_residual > 0 {
        let scrap_frac = pr / cap;
        let usable = if nx > 0.0 && pr >= nx { 1.0 } else { 0.35 };
        score += scrap_frac * (1.0 - usable) * 55.0 * (0.6 + 0.4 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: post_residual modulo buckets (dead-space classes)
    let pr = post_residual;
    // Perfect fits are golden
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Class residuals by divisibility / smallness: residuals that can
        // plausibly host common item sizes (>=1) are less dead.
        let dead = if pr < 4 {
            40.0 // tiny slivers are almost dead
        } else if pr % 10 == 0 {
            -10.0 // round residuals align with harmonic item classes
        } else if pr % 5 == 0 {
            -5.0
        } else if pr % 2 == 0 {
            0.0
        } else {
            8.0 // odd residuals less reusable
        };
        score += dead;

        // Non-linear penalty on large leftover: quadratic in fraction of capacity
        let frac = pr as f64 / cap;
        score += 30.0 * frac * frac;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            // next item fits: leftover after that matters
            let post2 = pr - next_item_size;
            score -= 40.0 * (1.0 - post2 as f64 / cap);
            if post2 == 0 { score -= 100.0; }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 12.0 * (next_item_size as f64 / cap);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tightest (post_residual already does)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, modulated by stream position and mean residual
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_cost = 220.0;
        open_cost -= 60.0 * progress; // later in stream, consolidation matters more
        open_cost += 1.5 * open_bins_count as f64;
        if mean_residual > 0.0 {
            // if open bins have plenty of room, opening new bin is less harmful
            open_cost -= 0.3 * mean_residual.min(100.0);
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            open_cost -= 200.0; // huge next item: fresh bin is fine
        }
        score += open_cost;
    }

    // Mild preference to keep bins balanced vs mean residual
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Integer division threshold: reward filling past half capacity
    if (bin_residual - item_size) <= bin_capacity / 2 && bin_residual > bin_capacity / 2 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fresh = bin_residual == bin_capacity;
    let half = 0.5 * cap;

    // Perfect fit: strong reward, amplified early
    if post_residual == 0 {
        score -= 1150.0 + 150.0 * (1.0 - progress);
    }

    // Cubic dead-space penalty, softened late
