        } else if rem2 >= next_item_size {
            score -= 28.0 * (1.0 - 0.4 * progress);
        }
    }

    // Fresh-bin opening gate — only open when the best existing fit would
    // strand more than the estimated next-item demand.
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < nx * 0.6 {
            score += 55.0 * (1.0 - 0.3 * progress);
        }
    }

    // GEN-35 mutation: wasted-space budget coupling — when the best existing
    // fit would strand more than the next item's size, penalize proportionally
    // so bins that leave room for the immediate future are preferred.
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let stranded_after = bin_residual.saturating_sub(item_size) as f64;
        if stranded_after > nx {
            let excess = stranded_after - nx;
            score += 0.25 * excess * (0.4 + 0.6 * progress);
        }
    }

    // GEN-35 mutation: dual-fit chain reward — when the post-residual can
    // exactly host the next item AND then another of the current size, this
    // bin chains perfectly; reward it more as the stream progresses.
    if !fresh && next_item_size > 0 {
        let chain2 = next_item_size.saturating_add(item_size);
        if post_residual == chain2 {
            score -= 90.0 + 60.0 * progress;
        } else if post_residual > chain2 && post_residual - chain2 <= 4 {
            score -= 35.0 + 25.0 * progress;
        }
    }

    // GEN-35 mutation: harmonic waste shaping — penalize residuals that sit in
    // the awkward band just below half-capacity where neither small nor large
    // items fit well; scaled by how many alternatives exist.
    if !fresh && pr > 0.0 {
        let awkward_low = 0.25 * cap;
        let awkward_high = 0.45 * cap;
        if pr > awkward_low && pr < awkward_high && fitting_bins_count > 1 {
            let depth = 1.0 - ((pr - awkward_low) / (awkward_high - awkward_low) - 0.5).abs() * 2.0;
            score += depth * 20.0 * (0.3 + 0.7 * progress);
        }
    }

    // GEN-35 mutation: residual compression — when few bins fit the item,
    // push harder toward the absolute tightest fit to avoid opening bins.
    if !fresh && fitting_bins_count <= 2 && post_residual > 0 {
        score += pr * 0.35 * (1.0 - 0.3 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled against capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // 2-step lookahead: perfect chain match (item + next item exactly fills bin)
    if next_item_size > 0 {
        let chain = item_size + next_item_size;
        if chain == bin_residual {
            score -= 50.0; // exact 2-item fill: excellent
        } else if next_item_size == post_residual {
            score -= 40.0; // next item exactly consumes the leftover
        } else if next_item_size <= post_residual {
            // leftover reusable by next item: reward proportionally to reuse
            let reuse = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * reuse;
        } else {
            // next item won't fit in leftover: penalize dead space
            let dead = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 15.0 * dead;
        }
    }

    // Relative to mean residual: placing into a bin with residual below mean
    // concentrates waste, which is good; above mean is wasteful.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = (res_f - mean_residual) / mean_residual;
        score += 8.0 * rel;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        } else {
            // open bins exist; only prefer new bin if all fits are terrible
            // (i.e., item is small relative to available residuals -> high waste)
            let waste_ratio = item_size as f64 / bin_capacity as f64;
            score += 30.0 * (1.0 - waste_ratio);
            if fitting_bins_count == 1 {
                score += 20.0; // discourage abandoning the sole fitting bin
            }
        }
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for many open bins to encourage bin reuse.
    score += open_bins_count as f64 * 0.1;

    score
}

