        let harm = ((pr / est).round() * est - pr).abs().min(((pr - nx).abs()));
        score -= 12.0 * (1.0 - (harm / est).min(1.0)) * (1.0 - 0.4 * progress);
    }

    // GEN-36 mutation: dual-lookahead chain — reward residuals that can host
    // the next item AND leave a multiple of the estimated item size behind,
    // combining fine-grained fitting with two-step anticipation.
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        let est = mean_residual.max(1.0);
        if est > 1.0 {
            let t2 = ((rem2 as f64) / est).round().max(0.0);
            let t2_err = ((rem2 as f64) - t2 * est).abs() / est;
            if t2_err < 0.15 {
                score -= 25.0 * (1.0 - t2_err / 0.15) * (1.0 - 0.3 * progress);
            }
        }
        if rem2 == 0 {
            score -= 30.0;
        }
    }

    // GEN-36 mutation: fresh-bin final gate — demand that opening a new bin
    // beats the best existing fit by a clear margin, scaled by how many
    // bins already fit (more options = higher bar for a new bin).
    if fresh && fitting_bins_count > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        let bar = (0.10 + 0.05 * fitting_bins_count.min(6) as f64) * cap;
        if best_waste < bar {
            score += 45.0 + 20.0 * (1.0 - best_waste / bar) + 40.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strong bonus when the item nearly fills the bin.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness * fill_frac;

    // Penalize small dead space (unusable slivers), reward medium residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 20.0 * next_fit;
    } else if next_item_size > post_residual {
        // Next item won't fit here; slight penalty proportional to waste risk.
        score += 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * fill_frac;
    } else if fitting_bins_count > 1 {
        // Competition: prefer bins where fit is tighter relative to alternatives.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Global state: when many bins are open and mean residual is high,
    // encourage consolidating into existing bins rather than opening new ones.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let consolidation = (open_bins_count as f64).ln() * mean_residual / bin_capacity as f64;
    score -= 6.0 * consolidation * (0.5 + 0.5 * t);

    // New-bin candidate handling: make empty-bin score depend on how poorly
    // the item fits typical open bins. Opening a new bin is attractive early
    // or when the item is large and would leave a bad residual elsewhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, decaying over the stream.
        score += 18.0 * (1.0 - 0.6 * t);
        // Large items that leave awkward residuals in existing bins favor new bin.
        let awkward = ((post_residual as f64) - 25.0).abs() / 25.0;
        score -= 10.0 * awkward * fill_frac;
        // If mean residual across open bins is small, existing bins are tight;
        // opening a fresh bin is reasonable.
        if mean_residual < item_size as f64 {
            score -= 12.0;
        }
        // If no existing bin fits well (many competing bins but bad residuals),
        // new bin becomes more attractive.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Prefer bins with residuals close to item size (best fit).
        let slack = (bin_residual - item_size) as f64;
        score += 0.15 * slack;
    }

    // Mild time-horizon modulation: later in the stream, prioritize closing
    // out bins (tight fits) more aggressively.
    score -= 5.0 * t * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
