        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && (rem2 as f64) < nx * 0.25 && rem2 < 20 {
            score += (20.0 - rem2 as f64) * 3.0 * (0.5 + progress);
        } else if rem2 >= next_item_size {
            score -= 28.0 * (1.0 - 0.4 * progress);
        }
    }

    // fresh-bin opening gate — only open when the best existing fit would
    // strand more than the estimated next-item demand
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < nx as f64 * 0.6 {
            score += 55.0 * (1.0 - 0.3 * progress);
        }
    }

    // GEN-36 mutation: dead-space ratio refinement — penalize residual
    // fractions that sit in the awkward band just above one future item
    // but below two, scaled by remaining stream length.
    if !fresh && post_residual > 0 && next_item_size > 0 {
        let remaining_frac = ((total_items - step_index) as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
        let two_nx = 2.0 * nx;
        if pr > nx && pr < two_nx {
            let band_pos = (pr - nx) / (two_nx - nx).max(1.0);
            score += (1.0 - band_pos) * 26.0 * remaining_frac;
        }
    }

    // GEN-36 mutation: complementary term — reward bins whose post-residual
    // equals a small multiple of the next item (exact tiling with nx)
    if !fresh && next_item_size > 0 && post_residual > 0 {
        let k_nx = (pr / nx.max(1.0)).round();
        if k_nx >= 1.0 && (pr - k_nx * nx).abs() < 1.5 {
            score -= 34.0 * k_nx.min(3.0) * (0.6 + 0.4 * progress);
        }
    }

    // GEN-36 mutation: fresh-bin two-item lookahead — open a new bin only
    // if the stranded residual after this item cannot host the next item
    // plus a small margin, i.e. avoid stranding near-miss gaps.
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let stranded = bin_residual.saturating_sub(item_size) as f64;
        if stranded >= nx && stranded < nx * 1.4 {
            score += 48.0 * (1.0 - 0.4 * progress);
        }
    }

    // GEN-36 mutation: residual variance compaction — when few bins fit,
    // push extra pressure toward the tightest residual to concentrate waste
    if !fresh && fitting_bins_count >= 2 && post_residual > 0 {
        let tightness = 1.0 - (pr / cap).min(1.0);
        score -= tightness * tightness * 18.0 * (0.4 + 0.6 * (1.0 - progress));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 + t);
    score -= 40.0 * poly;

    // Reward tight fits, amplified later in the stream
    let tightness = 1.0 - x;
    score -= 10.0 * tightness * tightness * (0.5 + t);

    // Penalize large dead space quadratically
    score += 0.15 * x * x * cap * (1.0 - 0.5 * t);

    // Lookahead: reward bins whose post residual fits next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild pressure to prefer bins with lower residual relative to mean
    score += 0.05 * (pr - mean_residual);

    // New-bin candidate: penalize opening early, allow later
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - t) + 0.1 * open_bins_count as f64;
    }

    score
}

