    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < nx as f64 * 0.6 {
            score += 55.0 * (1.0 - 0.3 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic classes of post_residual: classify leftover space into residue classes mod 10.
    let residue = post_residual % 10;
    let class = post_residual / 10;

    // Perfect-fit classes are highly desirable: post_residual in {0, 10, 20} leaves clean slots.
    if residue == 0 {
        score -= 18.0 + 0.5 * class as f64;
    } else if residue == 5 {
        score -= 6.0;
    } else if residue <= 3 {
        // Tiny slivers are dead space.
        score += 14.0 + 2.0 * (3 - residue) as f64;
    } else {
        score += 1.5 * residue as f64;
    }

    // Deep classes: post_residual > 50 means bin still half-full afterwards; mildly penalize
    // wasting a large-capacity bin on a small item.
    if post > 50.0 {
        score += 0.3 * (post - 50.0);
    }

    // Next-item coupling: if the lookahead item exactly fills the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual && (post_residual - next_item_size) % 10 == 0 {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            score -= 4.0;
        } else {
            // Next item cannot fit here; penalize slightly less if many bins are open.
            score += 3.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost that grows as the
    // stream progresses, encouraging consolidation of open bins early on.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.75 + 40.0 * progress - 0.2 * mean_residual;
        // If nothing fits anywhere, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Large upcoming item favors a fresh bin.
        if next_item_size > 60 {
            score -= 15.0;
        }
    }

    score
}

