    }

    // GEN-36 mutation: fresh-bin opening gate vs estimated next-item demand
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < nx as f64 * 0.6 {
            score += 55.0 * (1.0 - 0.3 * progress);
        }
    }

    // GEN-37 mutation: dual-item exact-fit lookahead — reward residuals that
    // exactly tile item + next item, and penalize residuals that can only
    // host one of them while stranding the difference.
    if !fresh && next_item_size > 0 {
        let two_sum = item_size as f64 + nx;
        if (pr - two_sum).abs() <= 2.0 {
            score -= 85.0 * (1.0 - 0.4 * progress);
        }
        if pr > nx && pr < two_sum {
            let strand = two_sum - pr;
            score += strand * 2.2 * (0.6 + 0.4 * progress);
        }
    }

    // GEN-37 mutation: residual-decay shaping — penalize residuals that no
    // plausible combination of remaining average items can consume, scaled
    // by how much of the stream is left.
