                // gap can host next item AND another mean-sized item: strong refund
                score -= 55.0 * (1.0 - 0.3 * progress);
            } else if after < est_item * 0.2 {
                score += 20.0 * (0.5 + progress);
            }
        }
    }

    // GEN-37 mutation: two-item lookahead fit — prefer bins where BOTH the current
    // and next item fit with minimal combined slack, especially mid-stream.
    if !fresh && next_item_size > 0 {
        let pair_sum = item_size.saturating_add(next_item_size);
        if bin_residual >= pair_sum {
            let slack = bin_residual - pair_sum;
            let slack_frac = slack as f64 / cap;
            if slack_frac < 0.1 {
                score -= (0.1 - slack_frac) * cap * 2.2 * (0.6 + 0.4 * progress);
            }
        } else if post_residual >= next_item_size {
            // current fits, next fits too (post_residual covers it)
            let rem2 = post_residual - next_item_size;
            let rem_frac = rem2 as f64 / cap;
            if rem_frac < 0.06 {
                score -= (0.06 - rem_frac) * cap * 3.0 * (1.0 - progress);
            }
        }
    }

