    // open, aggressively prefer the tightest fit to close bins early.
    if !fresh && open_bins_count > 10 {
        let pressure = ((open_bins_count - 10) as f64).min(40.0) / 40.0;
        score += (pr / cap) * 30.0 * pressure * (0.5 + 0.5 * progress);
        if pr <= 2.0 {
            score -= 25.0 * pressure;
        }
    }

    // GEN-37 mutation: fresh-bin opening gate refined — open a new bin only when
    // the best existing fit would strand more than the estimated future demand.
    if fresh && fitting_bins_count > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        let est_item = (cap - mean_residual).max(2.0);
        let demand = est_item.max(nx);
