    }

    // Near-miss calibration in mid band
    if !fresh && nx > 0.0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if dist_from_half < 0.15 * cap {
            score += 18.0 * (1.0 - miss / nx.max(1.0));
        }
    }

    // Tiling-error coupling
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let est = mean_residual.max(1.0);
        let k = (pr / est).round().max(1.0);
        let tiling_err = ((pr - k * est).abs()) / est;
        score += tiling_err * 16.0 * (0.5 + 0.5 * progress);
        if tiling_err < 0.1 {
            score -= 20.0 * k.min(3.0) * (1.0 - 0.5 * progress);
        }
    }

    // Keep room for follow-up item after next placement
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && (rem2 as f64) < nx * 0.25 && rem2 < 20 {
            score += (20.0 - rem2 as f64) * 3.0 * (0.5 + progress);
        } else if rem2 >= next_item_size {
            score -= 28.0 * (1.0 - 0.4 * progress);
        }
    }

    // GEN-37 mutation: combined fine-grained fit + lookahead anticipation —
    // reward bins where item+next both fit leaving a clean small remainder
    if !fresh && next_item_size > 0 && bin_residual >= item_size.saturating_add(next_item_size) {
        let rem2 = bin_residual - item_size.saturating_add(next_item_size);
        if rem2 <= 4 {
            score -= 95.0 * (1.0 - 0.4 * progress);
        } else if rem2 as f64 > 0.6 * cap {
            score += 30.0 * progress;
        }
    }

    // GEN-37 mutation: compaction pressure — prefer the bin whose post-residual
    // is smallest among fitting bins when open bins are plentiful
    if !fresh && open_bins_count > 12 {
        score += pr * 0.08;
    }

    score
}

