        }
    }

    // Residual variance-aware tightening
    if mean_residual > 0.0 {
        let tight_gain = (pr / mean_residual).powi(2).min(4.0);
        score -= 10.0 * tight_gain * (1.0 - progress) * 0.5;
    }

    // Adaptive sliver threshold scaled by observed item sizes
    let sliver_limit = if nx > 0.0 { (nx * 0.5).clamp(8.0, 25.0) } else { 15.0 };
    if post_residual > 0 && (post_residual as f64) < sliver_limit && post_residual != next_item_size {
        score += 40.0 * (1.0 - progress) * (1.0 - post_residual as f64 / sliver_limit);
    }

    // Pair-sum lookahead
    if next_item_size > 0 {
        let pair_sum = item_size.saturating_add(next_item_size);
        if bin_residual >= pair_sum {
            let pair_slack = bin_residual - pair_sum;
            if pair_slack <= 10 {
                score -= 70.0 - 4.0 * pair_slack as f64;
            }
        }
    }

    // Prefer tightest fit when many bins fit
    if fitting_bins_count > 2 {
        score += pr * 0.12;
    }

    // Late-stream new-bin restraint
    if progress > 0.85 && fresh && fitting_bins_count > 0 {
        score += 140.0 * progress;
    }

    // Fragmentation guard
    if fitting_bins_count <= 2 && !fresh && pr > 0.5 * cap {
        score += 25.0 + 0.3 * (pr - 0.5 * cap);
    }

    // GEN-9: residual-dead-space coupling
    if !fresh && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 20.0 {
            score += miss * (2.5 + 3.0 * progress);
        }
    }

    // GEN-9: reward bins whose post-residual can host plausible future fill
    if !fresh && post_residual > 0 {
        let est_item = (cap - mean_residual).max(1.0);
        let fits_est = (post_residual as f64 / est_item).floor();
        if fits_est >= 1.0 {
            let leftover = post_residual as f64 - fits_est * est_item;
            score -= 14.0 * fits_est.min(3.0) * (1.0 - leftover / est_item) * (1.0 - 0.4 * progress);
        }
    }

    // GEN-9: fresh-bin decision refined
    if fresh && fitting_bins_count > 0 {
        let waste_existing = bin_residual.saturating_sub(item_size) as f64;
        let item_frac = it / cap;
        if waste_existing > cap * (0.5 - 0.4 * item_frac) {
            score -= 45.0 + 0.35 * (waste_existing - cap * (0.5 - 0.4 * item_frac));
        }
        if progress < 0.25 && open_bins_count < 8 {
            score -= 30.0 * (1.0 - progress);
        }
    }

    // GEN-11: awkward-band gap penalty strengthened with progress coupling
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap < 8 {
            score -= (8 - gap) as f64 * 7.0 * (0.5 + progress);
        }
    }

    // GEN-11: mid-band residual trap
    if !fresh && nx > 0.0 && pr >= nx && pr < 0.3 * cap && fitting_bins_count > 1 {
        let waste = pr - nx;
        score += waste * 1.5 * progress;
    }

    // GEN-11: fresh-bin bias against small items late
    if fresh && item_size <= 30 && fitting_bins_count > 0 && progress > 0.3 {
        score += 90.0 * progress;
    }

    // GEN-13: dead-space budget accounting
    if !fresh && post_residual > 0 {
        let remaining = ((total_items - step_index) as f64).max(1.0);
        let est_item = (cap - mean_residual).max(1.0);
        let recoverable = if pr >= est_item * 0.5 { 1.0 } else { pr / (est_item * 0.5) };
        let permanence = (1.0 - recoverable).clamp(0.0, 1.0);
        let hole_price = pr * (0.15 + 0.55 * permanence) * (1.0 - 0.6 / (1.0 + remaining * 0.02));
        score += hole_price;
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let refund = (pr - next_item_size as f64).min(pr);
            score -= refund * 0.35 * (1.0 - progress);
        }
    }

    // GEN-13: two-step chain refinement
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 >= 0.2 * cap {
            score -= 22.0 * (1.0 - 0.5 * progress);
        } else if rem2 > 0 && (rem2 as f64) < 0.08 * cap {
            score += 14.0 * (1.0 - rem2 as f64 / (0.08 * cap));
        }
    }

    // GEN-13: fresh-bin gate tightened
    if fresh && fitting_bins_count >= 2 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < 0.25 * cap {
            score += 70.0 * (1.0 - 0.5 * progress);
        }
    }

    // GEN-13: triple-chain lookahead
    if !fresh && next_item_size > 0 {
        let pair_sum = item_size.saturating_add(next_item_size);
        if post_residual == pair_sum {
            score -= 110.0 * (1.0 - 0.5 * progress);
        }
        let rem3 = bin_residual.saturating_sub(pair_sum);
        if rem3 > 0 && rem3 <= 100 && rem3 >= next_item_size / 2 {
            score -= 35.0 * (1.0 - progress);
        }
    }

    // GEN-36 mutation: near-full bin squeeze bonus
    if !fresh && pr <= 6.0 {
        score -= (6.0 - pr) * 9.0 * (0.5 + progress);
    }

    // GEN-36 mutation: among several fitting bins, reward tightness relative to mean
    if fitting_bins_count >= 2 && !fresh {
        let rel = (pr / mean_residual.max(1.0)).min(2.0);
        score += rel * 6.0;
        if pr < 0.15 * cap {
            score -= 30.0 * (1.0 - pr / (0.15 * cap));
        }
    }

    // GEN-36 mutation: dead-space shaping near item boundary
    if !fresh && pr > 0.0 && pr < cap {
        if pr < it && progress < 0.9 {
            score += (1.0 - progress) * 30.0 * (pr / cap);
        }
        if nx > 0.0 && (pr - nx).abs() < 3.0 && pr != nx {
            score += 12.0 * (1.0 - progress);
        }
    }

    // GEN-36 mutation: exact next-item fit with large next item
    if !fresh && next_item_size > 0 && post_residual == next_item_size && nx > 0.4 * cap {
        score -= 40.0 * (1.0 - progress);
    }

    // GEN-36 mutation: residual-band scrap minimization
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let scrap = (pr % mean_residual) / mean_residual;
        score += scrap * 22.0 * (0.4 + 0.6 * progress);
    }

    // GEN-36 mutation: near-miss calibration in mid band
    if !fresh && nx > 0.0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if dist_from_half < 0.15 * cap {
            score += 18.0 * (1.0 - miss / nx.max(1.0));
        }
    }

    // GEN-36 mutation: fresh-bin discount when residual would strand a large block late
    if fresh && fitting_bins_count > 0 && progress > 0.5 {
        let stranded = bin_residual.saturating_sub(item_size) as f64;
        if stranded > 0.55 * cap {
            score -= 55.0 * (progress - 0.5) * 2.0;
        }
    }

    // GEN-36 mutation: tiling-error coupling
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let est = mean_residual.max(1.0);
        let k = (pr / est).round().max(1.0);
        let tiling_err = ((pr - k * est).abs()) / est;
        score += tiling_err * 16.0 * (0.5 + 0.5 * progress);
        if tiling_err < 0.1 {
            score -= 20.0 * k.min(3.0) * (1.0 - 0.5 * progress);
        }
    }

    // GEN-36 mutation: keep room for follow-up item after next placement
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && (rem2 as f64) < nx * 0.25 && rem2 < 20 {
            score += (20.0 - rem2 as f64) * 3.0 * (0.5 + progress);
        } else if rem2 >= next_item_size {
            score -= 28.0 * (1.0 - 0.4 * progress);
        }
    }

    // GEN-36 mutation: fresh-bin opening gate vs estimated next-item demand
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < nx as f64 * 0.6 {
            score += 55.0 * (1.0 - 0.3 * progress);
        }
    }

    // GEN-39 mutation: dead-space recovery horizon — weight stranded residual by
    // how many future items could realistically consume it, penalizing holes that
    // exceed the expected remaining demand density.
    if !fresh && post_residual > 0 {
        let remaining_items = ((total_items - step_index) as f64).max(1.0);
        let est_item = (cap - mean_residual).max(1.0);
        let expected_demand = remaining_items * est_item;
        let total_open_space = open_bins_count.max(1) as f64 * mean_residual.max(1.0);
        let scarcity = (expected_demand / (total_open_space + 1.0)).clamp(0.0, 2.0);
        // when space is scarce, dead space is precious: penalize more
        score += pr * 0.08 * scarcity * (1.0 - 0.5 * progress);
        // when space is abundant (scarcity low), tolerate loose fits slightly
        if scarcity < 0.5 && pr > 0.6 * cap {
            score -= 12.0 * (1.0 - scarcity * 2.0);
        }
    }

    // GEN-39 mutation: exact two-item chain completion — strongly reward residuals
    // that after placing this item exactly fit the next item with zero remainder,
    // scaled by how tight the pair is relative to capacity.
    if !fresh && next_item_size > 0 && post_residual == next_item_size {
        let pair_tightness = (item_size as f64 + nx) / cap;
        score -= 25.0 * pair_tightness * (0.5 + progress);
    }

    // GEN-39 mutation: residual-parity smoothing — bins whose post-residual is
    // within a small tolerance of the next item's size get a graded bonus rather
    // than a cliff, reducing dead space from near-miss rejections.
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let overshoot = post_residual - next_item_size;
        if overshoot <= 3 {
            score -= (4 - overshoot) as f64 * 10.0 * (1.0 - 0.4 * progress);
        }
    }

    // GEN-39 mutation: fresh-bin anti-fragmentation for tiny residuals — if the
    // best existing fit leaves a sliver smaller than the mean item's half, prefer
    // the fresh bin more aggressively to keep slivers from accumulating.
    if fresh && fitting_bins_count > 0 && mean_residual > 2.0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < mean_residual * 0.5 && best_waste > 0.0 {
            score -= 35.0 * (1.0 - best_waste / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
        }
    }

    // GEN-39 mutation: late-stream zero-waste push — in the final stretch, any
    // nonzero post-residual in an existing bin is penalized proportionally to
    // remaining item count, driving near-perfect fills when bins are closing out.
    if !fresh && progress > 0.8 && post_residual > 0 {
        let rem_items = (total_items - step_index) as f64;
        score += pr * 0.05 * (1.0 - (rem_items / ((total_items as f64) * 0.2)).clamp(0.0, 1.0)) * 3.0;
    }

    score
}

