        }
    }

    // GEN-40 mutation: late-stream zero-waste gate — near the end, only bins
    // that will end nearly full should win.
    if progress > 0.9 && !fresh && post_residual > 0 {
        score += (pr / cap) * 60.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (small but non-zero, too small for typical items) are heavily penalized.
    if post_residual > 0 {
        let pr = post_residual as f64;
        // Items range 1..100, so any gap < 10 is almost surely dead space.
        if post_residual < 10 {
            score += 60.0 * (10.0 - pr) / 10.0;
        } else if post_residual < 30 {
            // Moderately risky gap zone: quadratic penalty ramping up as gap shrinks.
            score += 0.06 * (30.0 - pr) * (30.0 - pr) / 30.0;
        } else {
            // Large residuals are healthy: mild reward.
            score -= 0.10 * (pr - 30.0);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Exact-fit lookahead: if the next item exactly fills the post_residual,
    // this is a chain fit worth a big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // If next item fits into the post residual, mild bonus for keeping room.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }
    // If next item would NOT fit here, the residual is likely dead space
    // unless it is large enough for future items; penalize small leftovers.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 25 {
        score += 12.0;
    }

    // Open-bin pressure: discourage scattering across many bins; when many
    // bins are open, prefer tighter fills (larger item_size relative to residual).
    let ob = open_bins_count as f64;
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= ob * 1.5 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, avoid forcing a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when the fit into open bins is bad
    // (small fill ratio) or few bins are open; empty-bin residual equals
    // capacity so its base score is high already; adjust with context.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Late in the stream with many open bins, prefer existing bins.
        score += 10.0 + 20.0 * progress + 0.5 * ob;
        if fill_ratio > 0.5 {
            score -= 15.0; // big item: opening fresh bin is reasonable
        }
    }

    // Mean-residual coupling: when the fleet average residual is low,
    // tighten packing further (reward using this bin well).
    score -= 0.05 * mean_residual.max(0.0).min(100.0) * (1.0 - fill_ratio);

    score
}

