    }

    // GEN-40 mutation: dead-space floor coupling — bins whose post-residual
    // falls in the "unfillable band" (below the smallest plausible item)
    // should be penalized proportionally to how much space is stranded.
    if !fresh && post_residual > 0 {
        let est_item = (cap - mean_residual).max(1.0);
        let min_plausible = (est_item * 0.35).clamp(1.0, 30.0);
        if pr < min_plausible {
            let stranded_frac = 1.0 - pr / min_plausible;
            score += stranded_frac * 26.0 * (1.0 - 0.5 * progress);
        }
    }

    // GEN-40 mutation: fresh-bin opening gate tightened — only open a new bin
    // when the best existing-bin waste clearly exceeds what a fresh bin would
    // strand, scaled by stream progress so late-stream opening stays costly.
    if fresh && fitting_bins_count > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        let fresh_strand = cap - it;
        if best_waste > fresh_strand * (0.9 + 0.2 * (1.0 - progress)) {
            score -= 75.0 * (1.0 - 0.4 * progress);
        } else if best_waste < fresh_strand * 0.4 {
            score += 40.0 * (0.5 + 0.5 * progress);
        }
    }

    // GEN-40 mutation: compaction pull — among bins that fit, prefer the one
    // whose post-residual is closest to zero, with a nonlinear (squared) pull
    // that sharpens the preference as the stream matures.
    if !fresh && post_residual > 0 && fitting_bins_count > 1 {
        let pr_frac = pr / cap;
        score += pr_frac * pr_frac * 55.0 * (0.4 + 0.6 * progress);
    }

    // GEN-40 mutation: residual-chain exactness for the item after next —
    // if post-residual minus next item exactly equals a plausible follow-up
    // item size, reward the bin as a planned two-step chain.
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        let est_item = (cap - mean_residual).max(1.0);
        let k = (rem2 as f64 / est_item).round();
        if k >= 1.0 && ((rem2 as f64 - k * est_item).abs()) < 1.5 {
            score -= 30.0 * (1.0 - 0.3 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear penalty
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain fit: strong reward
        if gap == 0.0 {
            score -= 60.0;
        } else if (post_residual as i64) >= (next_item_size as i64) {
            // Next item fits: partial reward scaled by how close
            score -= 25.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // Next item does NOT fit in the leftover: penalize creating dead space
            score += 10.0 + gap * 0.3;
        }

        // If post_residual + item_size could have held next item too, i.e. we
        // split a pair badly: extra penalty when bin_residual could fit next item
        if (bin_residual as i64) >= (next_item_size as i64) && (post_residual as i64) < (next_item_size as i64) {
            score += 8.0;
        }
    } else {
        // Last item: just minimize waste
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Reward bins with below-mean residual (they are the tightest, best to fill)
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Penalize spreading across many open bins slightly; encourage consolidation
    score += (open_bins_count as f64) * 0.05;

    // New-bin candidate handling: only attractive for very large items or when
    // no open bin is a decent fit
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (post_residual as f64) > mean_residual + 20.0;
        if poor_fit && item_size >= 50 {
            score -= 15.0;
        } else {
            // Opening a new bin wastes the residual of existing bins; discourage
            score += 30.0 + (post_residual as f64) * 0.4;
        }
    }

    // Late in the stream, be more conservative about opening bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

