        if rem2 > 0 && (rem2 as f64) < nx * 0.25 && rem2 < 20 {
            score += (20.0 - rem2 as f64) * 3.0 * (0.5 + progress);
        } else if rem2 >= next_item_size {
            score -= 28.0 * (1.0 - 0.4 * progress);
        }
    }

    // GEN-36: fresh-bin opening gate vs estimated next-item demand
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < nx as f64 * 0.6 {
            score += 55.0 * (1.0 - 0.3 * progress);
        }
    }

    // GEN-40: exact-future-tiling reward strengthened
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let est = mean_residual.max(1.0);
        let k = (pr / est).round().max(1.0);
        let tiling_err = ((pr - k * est).abs()) / est;
        if tiling_err < 0.02 && pr >= est {
            score -= 34.0 * k.min(4.0) * (1.0 - 0.3 * progress);
        }
    }

    // GEN-40: two-item chain exactness with small current item
    if !fresh && next_item_size > 0 && post_residual == next_item_size && item_size <= 25 {
        score -= 45.0 * (1.0 - 0.4 * progress);
    }

    // GEN-40: dead-space floor coupling — unfillable-band stranding
    if !fresh && post_residual > 0 {
        let est_item = (cap - mean_residual).max(1.0);
        let min_plausible = (est_item * 0.35).clamp(1.0, 30.0);
        if pr < min_plausible {
            let stranded_frac = 1.0 - pr / min_plausible;
            score += stranded_frac * 26.0 * (1.0 - 0.5 * progress);
        }
    }

    // GEN-40: fresh-bin opening gate vs fresh-bin stranding
    if fresh && fitting_bins_count > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        let fresh_strand = cap - it;
        if best_waste > fresh_strand * (0.9 + 0.2 * (1.0 - progress)) {
            score -= 75.0 * (1.0 - 0.4 * progress);
        } else if best_waste < fresh_strand * 0.4 {
            score += 40.0 * (0.5 + 0.5 * progress);
        }
    }

    // GEN-40: compaction pull — squared tightening among competing bins
    if !fresh && post_residual > 0 && fitting_bins_count > 1 {
        let pr_frac = pr / cap;
        score += pr_frac * pr_frac * 55.0 * (0.4 + 0.6 * progress);
    }

    // GEN-40: residual-chain exactness for the item after next
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        let est_item = (cap - mean_residual).max(1.0);
        let k = (rem2 as f64 / est_item).round();
        if k >= 1.0 && ((rem2 as f64 - k * est_item).abs()) < 1.5 {
            score -= 30.0 * (1.0 - 0.3 * progress);
        }
    }

    // GEN-41 mutation: waste-budget gate on fresh bins — open a new bin only when
    // the total stranded waste across existing fitting bins would exceed the
    // waste a fresh bin incurs, weighted by remaining stream length.
    if fresh && fitting_bins_count > 0 {
        let remaining_frac = 1.0 - progress;
        let fresh_waste = cap - it as f64;
        let existing_waste = bin_residual.saturating_sub(item_size) as f64;
        if existing_waste > fresh_waste * (1.05 - 0.25 * remaining_frac) {
            score -= 95.0 * (0.5 + remaining_frac);
        }
    }

    // GEN-41 mutation: exact two-item closure — when post_residual equals the
    // next item exactly AND the bin's residual equals item+next (perfect chain),
    // grant a decisive bonus so these chains are never broken.
    if !fresh && next_item_size > 0 && post_residual == next_item_size
        && bin_residual == item_size.saturating_add(next_item_size) {
        score -= 130.0 * (1.0 - 0.3 * progress);
    }

    // GEN-41 mutation: harmonic compaction — prefer bins whose post-residual
    // is a small divisor-friendly remainder (fits small follow-ups cleanly),
    // penalizing residues in the 1..=3 range less than mid-range holes.
    if !fresh && post_residual > 0 && fitting_bins_count > 1 {
        if post_residual <= 3 {
            score -= 24.0 * (1.0 - 0.4 * progress);
        } else if post_residual > 10 && post_residual < 25 {
            score += 10.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0) * progress;
        }
    }

    // GEN-41 mutation: large-item urgency — when the next item is very large
    // relative to capacity, prioritize the bin that leaves the largest post-
    // residual headroom so the big item lands without forcing a new bin.
    if !fresh && nx > 0.55 * cap && post_residual >= next_item_size {
        score -= 50.0 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is best.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize leaving dead space that cannot fit the typical next item.
    if post_residual > 0 && (next_item_size == 0 || post_residual < next_item_size) {
        score += 8.0 * (post_residual as f64).sqrt();
    }

    // Lookahead bonus: if the next item fits in the post residual, favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - chain_quality / (bin_capacity as f64));
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize many open bins slightly (encourages consolidation).
    score += 0.6 * open_bins_count as f64;

    // Time horizon: early in the stream, be conservative with new bins;
    // late in the stream, waste matters less, allow looser fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit_penalty = mean_residual.min(item_size as f64) / (item_size as f64 + 1.0);
        score = bin_capacity as f64 * 0.55 + 20.0 * (1.0 - poor_fit_penalty);
        if fitting_bins_count == 0 {
            score -= 40.0; // no open bin fits; new bin is necessary
        } else if fitting_bins_count == 1 {
            score += 30.0; // don't abandon the last usable bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // new bin gives room for large lookahead item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
