    // GEN-36 mutation: near-full bin squeeze bonus
    if !fresh && pr <= 6.0 {
        score -= (6.0 - pr) * 9.0 * (0.5 + progress);
    }

    // GEN-36 mutation: among several fitting bins, reward tightness relative to mean
    if fitting_bins_count >= 2 && !fresh {
        let rel = (pr / mean_residual.max(1.0)).min(2.0);
        score += rel * 6.0;
        if pr < 0.15 * cap {
            score -= 30.0 * (1.0 - pr / (0.15 * cap));
        }
    }

    // GEN-36 mutation: dead-space shaping near item boundary
    if !fresh && pr > 0.0 && pr < cap {
        if pr < it && progress < 0.9 {
            score += (1.0 - progress) * 30.0 * (pr / cap);
        }
        if nx > 0.0 && (pr - nx).abs() < 3.0 && pr != nx {
            score += 12.0 * (1.0 - progress);
        }
    }

    // GEN-36 mutation: exact next-item fit with large next item
    if !fresh && next_item_size > 0 && post_residual == next_item_size && nx > 0.4 * cap {
        score -= 40.0 * (1.0 - progress);
    }

    // GEN-36 mutation: residual-band scrap minimization
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let scrap = (pr % mean_residual) / mean_residual;
        score += scrap * 22.0 * (0.4 + 0.6 * progress);
    }

    // GEN-36 mutation: near-miss calibration in mid band
    if !fresh && nx > 0.0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if dist_from_half < 0.15 * cap {
            score += 18.0 * (1.0 - miss / nx.max(1.0));
        }
    }

    // GEN-36 mutation: fresh-bin discount when residual would strand a large block late
    if fresh && fitting_bins_count > 0 && progress > 0.5 {
        let stranded = bin_residual.saturating_sub(item_size) as f64;
        if stranded > 0.55 * cap {
            score -= 55.0 * (progress - 0.5) * 2.0;
        }
    }

    // GEN-36 mutation: tiling-error coupling
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let est = mean_residual.max(1.0);
        let k = (pr / est).round().max(1.0);
        let tiling_err = ((pr - k * est).abs()) / est;
        score += tiling_err * 16.0 * (0.5 + 0.5 * progress);
        if tiling_err < 0.1 {
            score -= 20.0 * k.min(3.0) * (1.0 - 0.5 * progress);
        }
    }

    // GEN-36 mutation: keep room for follow-up item after next placement
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && (rem2 as f64) < nx * 0.25 && rem2 < 20 {
            score += (20.0 - rem2 as f64) * 3.0 * (0.5 + progress);
        } else if rem2 >= next_item_size {
            score -= 28.0 * (1.0 - 0.4 * progress);
        }
    }

    // GEN-36 mutation: fresh-bin opening gate vs estimated next-item demand
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < nx as f64 * 0.6 {
            score += 55.0 * (1.0 - 0.3 * progress);
        }
    }

    // GEN-41 mutation: dead-space recovery horizon — price stranded residual by
    // how many future placements it could realistically absorb, with a sharper
    // cliff when the residual can host neither the next item nor the mean item.
    if !fresh && post_residual > 0 {
        let est_item = if mean_residual > 1.0 { mean_residual } else { cap * 0.3 };
        let can_next = nx > 0.0 && pr >= nx;
        let can_mean = pr >= est_item;
        if !can_next && !can_mean {
            // residual is dead weight for the near future: heavy penalty
            score += 45.0 + 0.25 * pr * (1.0 - progress);
        } else if can_next && !can_mean {
            // hosts only the next item: mild penalty proportional to leftover
            let leftover = pr - nx;
            score += 8.0 * (leftover / est_item).min(3.0);
        } else {
            score -= 20.0 * (1.0 - progress);
        }
    }

    // GEN-41 mutation: compaction sweep — when many bins fit, drive selection
    // toward the single smallest post-residual with a convex (quadratic) bias
    // so near-perfect fits are strongly preferred over merely-good ones.
    if !fresh && fitting_bins_count >= 3 && pr > 0.0 {
        score += (pr / cap).powi(2) * 55.0;
    }

    // GEN-41 mutation: anti-fragmentation threshold — never strand a residual
    // smaller than half the smallest plausible item when another bin fits.
    if !fresh && post_residual > 0 && fitting_bins_count > 1 {
        let min_item = if nx > 0.0 { nx.min(it) } else { it };
        let stranded = pr.min((pr - nx).max(0.0) as f64);
        if pr < nx && pr < min_item * 0.5 {
            score += 30.0;
        }
        let _ = stranded;
    }

    // GEN-41 mutation: fresh-bin opening gate — compare total expected waste of
    // opening now vs. squeezing into the best existing fit; open only if the
    // existing-fit waste exceeds the fresh-bin amortized cost.
    if fresh && fitting_bins_count > 0 {
        let squeeze_waste = bin_residual.saturating_sub(item_size) as f64;
        let open_cost = 25.0 * (1.0 - 0.5 * progress) + (open_bins_count as f64) * 0.5;
        if squeeze_waste > open_cost + 0.2 * cap {
            score -= 65.0;
        } else if squeeze_waste < 0.1 * cap {
            score += 85.0 * (1.0 - 0.3 * progress);
        }
    }

    // GEN-41 mutation: endgame exactness — in the final stretch, residuals that
    // exactly match any plausible future item are nearly free; others are costly.
    if progress > 0.9 && !fresh && post_residual > 0 {
        if nx > 0.0 && pr >= nx {
            score -= 35.0;
        } else {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward: harmonic class 0 (post_residual % 10 == 0) is ideal.
    let pr = post_residual;
    if pr == 0 {
        score -= 500.0;
    } else if pr % 10 == 0 {
        score -= 60.0;
    } else if pr % 5 == 0 {
        score -= 15.0;
    }

    // Integer-division thresholds: penalize leaving large awkward residuals.
    if pr >= 80 {
        score += 40.0; // huge leftover: better to open a fresh bin
    } else if pr >= 50 {
        score += 10.0;
    } else if pr <= 10 {
        score -= 25.0; // tiny dead space is fine
    }

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 && pr >= next_item_size {
        score -= 30.0 + 0.5 * (next_item_size as f64);
    } else if next_item_size > 0 && pr > 0 {
        // next item can't use leftover: penalize proportionally to wasted potential
        score += 0.3 * (next_item_size as f64).min(pr as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: neutral-ish, slightly penalized so we only
    // open new bins when existing fits are truly poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Early in stream, new bins are cheap; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * (1.0 - progress);
        // If many bins already open, discourage further sprawl.
        score += 2.0 * open_bins_count as f64;
    }

    // Mean-residual coupling: prefer bins near the mean residual (balanced packing).
    score += 0.15 * ((bin_residual as f64) - mean_residual).abs();

    // Tie-break: prefer fuller bins (small residual) with mild nonlinearity.
    score += 0.05 * (bin_residual as f64) * (bin_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
