    if !fresh && pr <= 6.0 {
        score -= (6.0 - pr) * 9.0 * (0.5 + progress);
    }

    // Tiling-error coupling: reward post-residuals near multiples of mean item size
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let est = mean_residual.max(1.0);
        let k = (pr / est).round().max(1.0);
        let tiling_err = ((pr - k * est).abs()) / est;
        score += tiling_err * 16.0 * (0.5 + 0.5 * progress);
        if tiling_err < 0.1 {
            score -= 20.0 * k.min(3.0) * (1.0 - 0.5 * progress);
        }
    }

    // Keep room for follow-up item after next placement
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && (rem2 as f64) < nx * 0.25 && rem2 < 20 {
            score += (20.0 - rem2 as f64) * 3.0 * (0.5 + progress);
        } else if rem2 >= next_item_size {
            score -= 28.0 * (1.0 - 0.4 * progress);
        }
    }

    // Dead-space budget accounting: price unrecoverable holes
    if !fresh && post_residual > 0 {
        let remaining = ((total_items - step_index) as f64).max(1.0);
        let est_item = (cap - mean_residual).max(1.0);
        let recoverable = if pr >= est_item * 0.5 { 1.0 } else { pr / (est_item * 0.5) };
        let permanence = (1.0 - recoverable).clamp(0.0, 1.0);
        let hole_price = pr * (0.15 + 0.55 * permanence) * (1.0 - 0.6 / (1.0 + remaining * 0.02));
        score += hole_price;
        if next_item_size > 0 && pr >= nx {
            let refund = (pr - nx).min(pr);
            score -= refund * 0.35 * (1.0 - progress);
        }
    }

    // Tightness relative to mean among competing bins
    if fitting_bins_count >= 2 && !fresh {
        let rel = (pr / mean_residual.max(1.0)).min(2.0);
        score += rel * 6.0;
        if pr < 0.15 * cap {
            score -= 30.0 * (1.0 - pr / (0.15 * cap));
        }
    }

    // Dead-space shaping near item boundary
    if !fresh && pr > 0.0 && pr < cap {
        if pr < it && progress < 0.9 {
            score += (1.0 - progress) * 30.0 * (pr / cap);
        }
        if nx > 0.0 && (pr - nx).abs() < 3.0 && pr != nx {
            score += 12.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever be useful
    // (below the minimum conceivable item size) are pure waste.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 50.0 + (dead_threshold - post_residual as f64) * 10.0;
    }

    // Penalize awkward mid-range gaps that few items can exploit.
    if post_residual > 0 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 0.8;
    }

    // Reward tight fits strongly.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation
    // into existing bins over spreading; when few are open, opening is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly, more under pressure / early stream.
        score += 8.0 + pressure * 0.3;
    } else {
        // Slight reward for choosing bins already below average residual
        // (keeps residual distribution tight).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Lookahead coupling: if the next item fits the post-residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for the known next item: dead space.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
