        let fleet_avg = (mean_residual * open_bins_count.max(1) as f64 - it) / open_bins_count.max(1) as f64;
        let delta = pr - fleet_avg.max(0.0);
        score += delta * (0.25 + 0.35 * progress);
    }

    // GEN-43 mutation: harmonic dead-space pricing — quadratic residual penalty
    // modulated by how many bins still fit the item (scarce options → tighter).
    if !fresh && post_residual > 0 {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        score += (pr * pr) / cap * (0.10 + 0.25 * scarcity);
    }

    // GEN-43 mutation: chain-exactness dividend — if placing here leaves a
    // residual exactly equal to a plausible small item (≤ half of next),
    // reward it as future-fillable space.
    if !fresh && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size / 2 {
        score -= 30.0 * (1.0 - post_residual as f64 / (next_item_size as f64 / 2.0)) * (1.0 - 0.5 * progress);
    }

    // GEN-43 mutation: fresh-bin veto refined — open a new bin only when the
    // best existing fit would strand more than the next item could recover.
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let stranded = bin_residual.saturating_sub(item_size) as f64;
        if stranded > nx as f64 + 0.35 * cap {
            score -= 40.0 * (1.0 - progress);
        } else if stranded <= nx as f64 {
            score += 45.0 * (0.5 + progress);
        }
    }

    // GEN-43 mutation: endgame squeeze — very late, only near-exact fits matter
    if progress > 0.9 && !fresh && post_residual > 0 {
        score += pr * 0.8;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 4 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight post_residual relative to mean residual.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Aggressive 2-step lookahead: perfect match of post_residual with next item is gold.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + diff);
        // Exact match: huge reward
        if post_residual == next_item_size {
            score -= 50.0;
        }
        // Next item fits in the post-residual slack region: mild reward scaled by proximity
        if next_item_size <= post_residual {
            score -= 5.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item cannot follow into this bin: penalize large dead space
            score += 0.3 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): penalize so we only open when fits are poor.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Late in stream, opening fresh bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    // Penalize leaving residuals below the minimum item size (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild penalty for proliferating open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

