    // GEN-36 mutation: near-full bin squeeze bonus
    if !fresh && pr <= 6.0 {
        score -= (6.0 - pr) * 9.0 * (0.5 + progress);
    }

    // GEN-36 mutation: among several fitting bins, reward tightness relative to mean
    if fitting_bins_count >= 2 && !fresh {
        let rel = (pr / mean_residual.max(1.0)).min(2.0);
        score += rel * 6.0;
        if pr < 0.15 * cap {
            score -= 30.0 * (1.0 - pr / (0.15 * cap));
        }
    }

    // GEN-36 mutation: dead-space shaping near item boundary
    if !fresh && pr > 0.0 && pr < cap {
        if pr < it && progress < 0.9 {
            score += (1.0 - progress) * 30.0 * (pr / cap);
        }
        if nx > 0.0 && (pr - nx).abs() < 3.0 && pr != nx {
            score += 12.0 * (1.0 - progress);
        }
    }

    // GEN-36 mutation: exact next-item fit with large next item
    if !fresh && next_item_size > 0 && post_residual == next_item_size && nx > 0.4 * cap {
        score -= 40.0 * (1.0 - progress);
    }

    // GEN-36 mutation: residual-band scrap minimization
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let scrap = (pr % mean_residual) / mean_residual;
        score += scrap * 22.0 * (0.4 + 0.6 * progress);
    }

    // GEN-36 mutation: near-miss calibration in mid band
    if !fresh && nx > 0.0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if dist_from_half < 0.15 * cap {
            score += 18.0 * (1.0 - miss / nx.max(1.0));
        }
    }

    // GEN-36 mutation: fresh-bin discount when residual would strand a large block late
    if fresh && fitting_bins_count > 0 && progress > 0.5 {
        let stranded = bin_residual.saturating_sub(item_size) as f64;
        if stranded > 0.55 * cap {
            score -= 55.0 * (progress - 0.5) * 2.0;
        }
    }

    // GEN-36 mutation: tiling-error coupling
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let est = mean_residual.max(1.0);
        let k = (pr / est).round().max(1.0);
        let tiling_err = ((pr - k * est).abs()) / est;
        score += tiling_err * 16.0 * (0.5 + 0.5 * progress);
        if tiling_err < 0.1 {
            score -= 20.0 * k.min(3.0) * (1.0 - 0.5 * progress);
        }
    }

    // GEN-36 mutation: keep room for follow-up item after next placement
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && (rem2 as f64) < nx * 0.25 && rem2 < 20 {
            score += (20.0 - rem2 as f64) * 3.0 * (0.5 + progress);
        } else if rem2 >= next_item_size {
            score -= 28.0 * (1.0 - 0.4 * progress);
        }
    }

    // GEN-36 mutation: fresh-bin opening gate vs estimated next-item demand
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < nx as f64 * 0.6 {
            score += 55.0 * (1.0 - 0.3 * progress);
        }
    }

    // GEN-44 mutation: dead-space ratio driver — penalize bins whose post-residual
    // fraction exceeds the item's own footprint, scaled by remaining stream length.
    if !fresh && pr > 0.0 {
        let remaining_frac = ((total_items - step_index) as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
        let dsr = (pr / cap) / (it / cap).max(0.01);
        if dsr > 1.0 {
            score += (dsr - 1.0).min(4.0) * 10.0 * (0.3 + 0.7 * remaining_frac);
        }
    }

    // GEN-44 mutation: refined perfect-refill chain — reward residuals that can be
    // exactly tiled by two more next-sized items (triple exact chain).
    if !fresh && next_item_size > 0 && post_residual > 0 {
        let two_nx = 2 * next_item_size;
        if post_residual == two_nx {
            score -= 85.0 * (1.0 - 0.4 * progress);
        } else if post_residual > two_nx {
            let rem = post_residual - two_nx;
            if rem <= item_size {
                score -= 30.0 * (1.0 - 0.5 * progress);
            }
        }
    }

    // GEN-44 mutation: fresh-bin gate — compare best existing-bin waste against the
    // dead space a fresh bin would leave after this item; open only if clearly better.
    if fresh && fitting_bins_count > 0 {
        let fresh_dead = bin_capacity.saturating_sub(item_size) as f64;
        let best_existing_waste = bin_residual.saturating_sub(item_size) as f64;
        if fresh_dead > best_existing_waste + 0.35 * cap {
            score += 45.0 * (0.5 + 0.5 * progress);
        } else if best_existing_waste < 0.12 * cap {
            score += 65.0;
        }
    }

    // GEN-44 mutation: residual harmonics — prefer residuals that are near-multiples
    // of the next item size for guaranteed multi-step filling.
    if !fresh && nx > 0.0 && pr >= nx {
        let k = (pr / nx).round().max(1.0);
        let harm = ((pr - k * nx).abs()) / nx;
        if harm < 0.15 {
            score -= 26.0 * k.min(4.0) * (1.0 - 0.6 * progress);
        }
    }

    // GEN-44 mutation: mean-residual convergence — pull bin residuals toward the
    // stream mean so future items tile uniformly across open bins.
    if !fresh && mean_residual > 1.0 {
        let dev = (pr - mean_residual).abs() / mean_residual;
        score += dev * 9.0 * (0.4 + 0.6 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: early on be exploratory, later be conservative.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: squared post-residual penalty scaled by capacity.
    let tight = (post_residual as f64) / bin_capacity as f64;
    score += tight * tight * 40.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize crowded bin sets slightly to encourage consolidation when many bins open.
    score += open_bins_count as f64 * 0.5;

    // Mean residual coupling: prefer bins whose residual deviates from the mean
    // in a useful way (use larger residual bins for larger items).
    let dev = bin_residual as f64 - mean_residual;
    score -= (dev * item_size as f64) * 0.004;

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            // dead space that the next item cannot use
            score += (post_residual as f64 - (next_item_size.min(post_residual)) as f64) * 0.3;
        }
        // If next item exactly fills post residual, huge reward (perfect chain).
        if post_residual == next_item_size {
            score -= 45.0;
        }
    } else {
        // Last item: strongly prefer filling bins as tightly as possible.
        score -= 30.0 * (1.0 - tight);
    }

    // Time horizon: early stream, tolerate opening new bins (exploration);
    // late stream, penalize opening a new empty bin unless nothing fits well.
    let new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if new_bin {
        let exploration = (1.0 - progress) * 25.0;
        score += 20.0 - exploration;
        // Opening new bins when many are already open is wasteful late in stream.
        score += open_bins_count as f64 * progress * 2.0;
        // If next item is large, a fresh bin is more valuable.
        score -= next_item_size as f64 * 0.15;
    }

    // Small bonus for bins that are already mostly full (avoid leaving many half-full bins).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * fill_ratio * 12.0;

    // Mild noise-free tiebreaker using bin residual parity-free hash-like term.
    score += ((bin_residual as f64 * 0.017).sin()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
