    // GEN-44 mutation: residual-capacity conservation — when open bins are few and
    // the stream is long, mildly discourage leaving large holes in existing bins
    // to preserve total residual flexibility.
    if !fresh && pr > 0.35 * cap && progress < 0.6 {
        let remaining_items = ((total_items - step_index) as f64).max(1.0);
        if remaining_items > 50.0 {
            score += (pr - 0.35 * cap) * 0.55 * (1.0 - progress);
        }
    }

    // GEN-44 mutation: harmonic near-exact fit bonus — reward residuals that
    // accommodate next item plus any small observed-size remainder exactly.
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 == ((rem2 as f64 / mean_residual.max(1.0)).round() * mean_residual.max(1.0)).round() && rem2 > 0 && (rem2 as f64) < 0.3 * cap {
            score -= 30.0 * (1.0 - 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Smooth non-linear coupling: quadratic/quartic decay of residual
    let pr = post_residual as f64 / cap;
    let poly = pr * pr * (1.0 - pr) * (1.0 - pr); // peaks when post_residual ~ half, low near 0
    score -= 60.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - pr;
    score -= (10.0 + 40.0 * progress) * tightness * tightness;

    // Penalize large leftover relative to mean residual of open bins (fragmentation)
    if mean_residual > 0.0 {
        let frag = (post_residual as f64 - mean_residual) / cap;
        score += 8.0 * frag * frag.abs();
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let chain = next_item_size as f64 / cap;
        score -= 25.0 * chain * (1.0 - pr);
    } else if next_item_size > 0 {
        // smooth penalty when next item cannot chain
        let gap = (next_item_size as f64 - post_residual as f64) / cap;
        score += 15.0 * gap * gap;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly early, more strongly when many bins are open
    // but allow opening when open bins are fragmented (high mean residual spread)
    if bin_residual == bin_capacity {
        let base_penalty = 30.0 + 40.0 * (1.0 - progress);
        let fragmentation = if mean_residual > 0.0 { mean_residual / cap } else { 0.0 };
        score += base_penalty - 20.0 * fragmentation * open_bins_count as f64 / (open_bins_count as f64 + 3.0);
    }

    // Slight preference for bins with less residual before placement (best-fit flavor)
    score += 0.05 * (bin_residual as f64 - item_size as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let nx = next_item_size as f64;
    let it = item_size as f64;
    let fresh = bin_residual == bin_capacity;
    let half = 0.5 * cap;

    // Perfect fit: strong reward, amplified early
    if post_residual == 0 {
        score -= 1250.0 + 150.0 * (1.0 - progress);
    }

    // Cubic dead-space penalty, softened late
