        let est_item = (cap - mean_residual).max(1.0);
        let fits_est = (post_residual as f64 / est_item).floor();
        if fits_est >= 1.0 {
            let leftover = post_residual as f64 - fits_est * est_item;
            score -= 14.0 * fits_est.min(3.0) * (1.0 - leftover / est_item) * (1.0 - 0.4 * progress);
        }
    }

    // Awkward-band gap penalty with progress coupling
    if !fresh && next_item_size > 0 && post_residual > next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap < 8 {
            score -= (8 - gap) as f64 * 7.0 * (0.5 + progress);
        }
    }

    // Mid-band residual trap
    if !fresh && nx > 0.0 && pr >= nx && pr < 0.3 * cap && fitting_bins_count > 1 {
        let waste = pr - nx;
        score += waste * 1.5 * progress;
    }

    // Dead-space budget accounting
    if !fresh && post_residual > 0 {
        let remaining = ((total_items - step_index) as f64).max(1.0);
        let est_item = (cap - mean_residual).max(1.0);
        let recoverable = if pr >= est_item * 0.5 { 1.0 } else { pr / (est_item * 0.5) };
        let permanence = (1.0 - recoverable).clamp(0.0, 1.0);
        let hole_price = pr * (0.15 + 0.55 * permanence) * (1.0 - 0.6 / (1.0 + remaining * 0.02));
        score += hole_price;
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let refund = (pr - next_item_size as f64).min(pr);
            score -= refund * 0.35 * (1.0 - progress);
        }
    }

    // Two-step chain refinement
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 >= 0.2 * cap {
            score -= 22.0 * (1.0 - 0.5 * progress);
        } else if rem2 > 0 && (rem2 as f64) < 0.08 * cap {
            score += 14.0 * (1.0 - rem2 as f64 / (0.08 * cap));
        }
    }

    // Fresh-bin gate tightened
    if fresh && fitting_bins_count >= 2 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < 0.25 * cap {
            score += 70.0 * (1.0 - 0.5 * progress);
        }
    }

    // Triple-chain lookahead
    if !fresh && next_item_size > 0 {
        let pair_sum = item_size.saturating_add(next_item_size);
        if post_residual == pair_sum {
            score -= 110.0 * (1.0 - 0.5 * progress);
        }
        let rem3 = bin_residual.saturating_sub(pair_sum);
        if rem3 > 0 && rem3 <= 100 && rem3 >= next_item_size / 2 {
            score -= 35.0 * (1.0 - progress);
        }
    }

    // Near-full bin squeeze bonus
    if !fresh && pr <= 6.0 {
        score -= (6.0 - pr) * 9.0 * (0.5 + progress);
    }

    // Among several fitting bins, reward tightness relative to mean
    if fitting_bins_count >= 2 && !fresh {
        let rel = (pr / mean_residual.max(1.0)).min(2.0);
        score += rel * 6.0;
        if pr < 0.15 * cap {
            score -= 30.0 * (1.0 - pr / (0.15 * cap));
        }
    }

    // Dead-space shaping near item boundary
    if !fresh && pr > 0.0 && pr < cap {
        if pr < it && progress < 0.9 {
            score += (1.0 - progress) * 30.0 * (pr / cap);
        }
        if nx > 0.0 && (pr - nx).abs() < 3.0 && pr != nx {
            score += 12.0 * (1.0 - progress);
        }
    }

    // Exact next-item fit with large next item
    if !fresh && next_item_size > 0 && post_residual == next_item_size && nx > 0.4 * cap {
        score -= 40.0 * (1.0 - progress);
    }

    // Residual-band scrap minimization
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let scrap = (pr % mean_residual) / mean_residual;
        score += scrap * 22.0 * (0.4 + 0.6 * progress);
    }

    // Near-miss calibration in mid band
    if !fresh && nx > 0.0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if dist_from_half < 0.15 * cap {
            score += 18.0 * (1.0 - miss / nx.max(1.0));
        }
    }

    // Fresh-bin discount when residual would strand a large block late
    if fresh && fitting_bins_count > 0 && progress > 0.5 {
        let stranded = bin_residual.saturating_sub(item_size) as f64;
        if stranded > 0.55 * cap {
            score -= 55.0 * (progress - 0.5) * 2.0;
        }
    }

    // Tiling-error coupling
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let est = mean_residual.max(1.0);
        let k = (pr / est).round().max(1.0);
        let tiling_err = ((pr - k * est).abs()) / est;
        score += tiling_err * 16.0 * (0.5 + 0.5 * progress);
        if tiling_err < 0.1 {
            score -= 20.0 * k.min(3.0) * (1.0 - 0.5 * progress);
        }
    }

    // Keep room for follow-up item after next placement
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && (rem2 as f64) < nx * 0.25 && rem2 < 20 {
            score += (20.0 - rem2 as f64) * 3.0 * (0.5 + progress);
        } else if rem2 >= next_item_size {
            score -= 28.0 * (1.0 - 0.4 * progress);
        }
    }

    // GEN-44 mutation: harmonic dual-threshold chain — reward residuals that
    // exactly tile with either item or next item in 2+ repetitions
    if !fresh && post_residual > 0 {
        if item_size > 0 && post_residual % item_size == 0 && post_residual / item_size >= 2 {
            score -= 24.0 * (1.0 - 0.4 * progress);
        }
        if next_item_size > 1 && post_residual % next_item_size == 0 && post_residual / next_item_size >= 2 {
            score -= 20.0 * (1.0 - 0.4 * progress);
        }
    }

    // GEN-44 mutation: wasted-gap penalty scaled by fitting-bin scarcity —
    // when only few bins fit, dead space in the chosen bin is costlier
    if !fresh && post_residual > 0 && fitting_bins_count <= 3 {
        let scarcity = (4 - fitting_bins_count.min(3)) as f64;
        score += (pr / cap) * 28.0 * scarcity * (0.3 + 0.7 * progress);
    }

    // GEN-44 mutation: fresh-bin arbitration against near-fitting open bin —
    // if an open bin's post-residual would be tiny, strongly prefer it
    if fresh && fitting_bins_count > 0 {
        // estimate: the best existing fit is unknowable here, but if the item
        // is small relative to capacity and bins are plentiful, resist opening
        if it < 0.35 * cap && open_bins_count > 4 && progress < 0.9 {
            score += 45.0 * (1.0 - 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / 10.0).floor(); // 10-unit harmonic classes (0..=9)

    // Reward small, "usable" residual classes (0..3), penalize awkward middle classes.
    match class as u32 {
        0 => score -= 40.0,          // near-perfect fit
        1 => score -= 25.0,
        2 => score -= 12.0,
        3 => score -= 5.0,
        4 | 5 => score += 8.0,       // awkward mid-range dead space
        6 | 7 => score += 15.0,
        _ => score += 20.0,          // huge leftover, bin nearly empty
    }

    // Integer-division threshold: does post_residual still accommodate common item sizes?
    if post_residual >= 50 { score -= 10.0; }
    if post_residual >= 25 && post_residual < 50 { score += 5.0; }

    // Lookahead coupling: if next item fits the post-residual exactly (harmonic pairing), reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item fills leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill;
            // harmonic pair: next item leaves another small residual
            let npr = post_residual - next_item_size;
            if npr <= 10 { score -= 15.0; }
        } else {
            // next item won't fit here; leftover must serve future items — penalize tiny leftovers
            if post_residual < next_item_size && post_residual < 20 {
                score += 25.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: keep it competitive only when open bins have poor fits.
    if bin_residual == bin_capacity {
        // neutral base; discourage slightly unless many bins are fragmented
        score += 5.0;
        if mean_residual < 20.0 && open_bins_count > 0 {
            score -= 30.0; // open bins are nearly full -> new bin is good
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    } else {
        // prefer tighter existing bins: reward closeness of item to residual
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 20.0 * tightness;
        // prefer bins with below-mean residual (fuller bins)
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // Modulo arithmetic on post_residual: multiples of 10 are "clean" classes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    score
}

