        if pr < it && progress < 0.9 {
            score += (1.0 - progress) * 30.0 * (pr / cap);
        }
        if nx > 0.0 && (pr - nx).abs() < 3.0 && pr != nx {
            score += 12.0 * (1.0 - progress);
        }
    }

    // GEN-36: exact next-item fit with large next item
    if !fresh && next_item_size > 0 && post_residual == next_item_size && nx > 0.4 * cap {
        score -= 40.0 * (1.0 - progress);
    }

    // GEN-36: residual-band scrap minimization
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let scrap = (pr % mean_residual) / mean_residual;
        score += scrap * 22.0 * (0.4 + 0.6 * progress);
    }

    // GEN-36: near-miss calibration in mid band
    if !fresh && nx > 0.0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if dist_from_half < 0.15 * cap {
            score += 18.0 * (1.0 - miss / nx.max(1.0));
        }
    }

    // GEN-36: fresh-bin discount when residual would strand a large block late
    if fresh && fitting_bins_count > 0 && progress > 0.5 {
        let stranded = bin_residual.saturating_sub(item_size) as f64;
        if stranded > 0.55 * cap {
            score -= 55.0 * (progress - 0.5) * 2.0;
        }
    }

    // GEN-36: tiling-error coupling
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let est = mean_residual.max(1.0);
        let k = (pr / est).round().max(1.0);
        let tiling_err = ((pr - k * est).abs()) / est;
        score += tiling_err * 16.0 * (0.5 + 0.5 * progress);
        if tiling_err < 0.1 {
            score -= 20.0 * k.min(3.0) * (1.0 - 0.5 * progress);
        }
    }

    // GEN-36: keep room for follow-up item after next placement
    if !fresh && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && (rem2 as f64) < nx * 0.25 && rem2 < 20 {
            score += (20.0 - rem2 as f64) * 3.0 * (0.5 + progress);
        } else if rem2 >= next_item_size {
            score -= 28.0 * (1.0 - 0.4 * progress);
        }
    }

    // GEN-36: fresh-bin opening gate vs estimated next-item demand
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste < nx as f64 * 0.6 {
            score += 55.0 * (1.0 - 0.3 * progress);
        }
    }

    // GEN-45: dead-space-per-item density pricing — price residual holes by how
    // many future items they can still absorb relative to the mean item size.
    if !fresh && post_residual > 0 {
        let est_item = mean_residual.max(2.0);
        let capacity_units = (pr / est_item).floor().min(4.0);
        let density = capacity_units / (pr / cap).max(0.01);
        score -= density * 9.0 * (1.0 - 0.5 * progress);
    }

    // GEN-45: harmonic-fit bonus — reward residuals that split evenly across
    // two future items of approximately the observed mean size.
    if !fresh && post_residual > 0 && mean_residual > 1.0 {
        let two_fit = pr / 2.0;
        let err = (two_fit - mean_residual).abs() / mean_residual;
        if err < 0.35 {
            score -= (0.35 - err) * 55.0 * (1.0 - 0.4 * progress);
        }
    }

    // GEN-45: open-bin pressure coupling — with many open bins, tighten selection
    // toward minimal post-residual; with few bins, allow flexible fills.
    let pressure = (open_bins_count as f64 / (cap / 8.0).max(1.0)).min(1.0);
    score += pr * 0.08 * pressure * (1.0 - progress);

    // GEN-45: fresh-bin anti-fragmentation gate — never open a new bin while the
    // next item would still fit into the fresh bin's residual after placement.
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let after = bin_residual.saturating_sub(item_size);
        if after >= next_item_size && after.saturating_sub(next_item_size) <= 6 {
            score += 65.0 * (1.0 - progress);
        }
    }

    // GEN-45: endgame exact-closure chase — late in the stream, aggressively
    // prefer bins whose post-residual matches any plausible future item size.
    if progress > 0.7 && !fresh && post_residual > 0 {
        let est_item = mean_residual.max(2.0);
        let closeness = (pr - est_item).abs();
        if closeness < 10.0 {
            score -= (10.0 - closeness) * 6.0 * (progress - 0.7) * 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest possible item are pure waste; penalize them heavily.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // exact fit is fine, but guard anyway
    } else if post_residual < item_size.min(10) {
        // Gap smaller than likely next items: dead space.
        score += 40.0 + 2.0 * post_residual as f64;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 15.0 * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // placement is genuinely good; encourage consolidation when bins are many.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 1.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: placing into a bin far from the mean residual
    // either wastes a large gap (bad) or empties a small one (good).
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.3 * dev;
    } else {
        score += 0.15 * dev; // mild reward for reducing mean residual
    }

    // Lookahead: if the next item fits exactly into post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this gap; slightly penalize leaving gaps
        // that the lookahead cannot consume.
        score += 3.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make it attractive only when this bin would be a
    // poor host (large post_residual waste) or few bins are open.
    if bin_residual == bin_capacity {
        let waste_penalty = if post_residual < 20 { 80.0 } else { 0.0 };
        score += 5.0 + waste_penalty - 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
