        }
    }

    // GEN-46 mutation: sharpen the squeeze band — extend near-full bonus to
    // slightly larger residuals with progress-scaled strength.
    if !fresh && pr > 6.0 && pr <= 14.0 {
        score -= (14.0 - pr) * 3.0 * progress;
    }

    // GEN-46 mutation: fresh-bin gate — open a new bin only when the best
    // existing fit would strand more than the expected next-item demand.
    if fresh && fitting_bins_count > 0 && next_item_size > 0 {
        let best_waste = bin_residual.saturating_sub(item_size) as f64;
        if best_waste > nx * 1.4 {
            score -= 35.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= 9) are pure waste; penalize heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Small, hard-to-fill gaps are semi-dead space.
        score += 15.0;
    }

    // Reward leaving a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap cannot host the next item: mild penalty scaled by gap size.
        score += 0.1 * post_residual as f64;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins tighter than average (good fits).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Mild preference for filling bins more fully as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * item_size as f64 * 0.05;

    // New-bin candidate: only attractive when existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 5.0;
        if fitting_bins_count == 1 {
            score += 40.0; // opening new bin still better than last-chance? no: push new bin score up
        }
    }

    score
}

